   !  Protein stuff

   !  Protein letter protein codes -- middle is charge
   MAT(STR(len=3),3,20), public :: protein_letter_codes
   data protein_letter_codes/ &
       "A  ", "0  ", "ALA", &
       "R  ", "1  ", "ARG", &
       "N  ", "0  ", "ASN", &
       "D  ", "-1 ", "ASP", &
       "C  ", "0  ", "CYS", &
       "E  ", "-1 ", "GLU", &
       "Q  ", "0  ", "GLN", &
       "G  ", "0  ", "GLY", &
       "H  ", "0  ", "HIS", &
       "I  ", "0  ", "ILE", &
       "L  ", "0  ", "LEU", &
       "K  ", "1  ", "LYS", &
       "M  ", "0  ", "MET", &
       "F  ", "0  ", "PHE", &
       "P  ", "0  ", "PRO", &
       "S  ", "0  ", "SER", &
       "T  ", "0  ", "THR", &
       "W  ", "0  ", "TRP", &
       "Y  ", "0  ", "TYR", &
       "V  ", "0  ", "VAL"/
   type(ATOM_TYPE), PTR, private :: saved_self DEFAULT_NULL

contains

!  ==================
!  Allocation methods
!  ==================

   PURE subroutine create(self)
   ! Allocate an object
      type(ATOM_TYPE), allocatable, OUT :: self

#ifdef USE_PRECONDITIONS
      INT :: status
#endif

#ifdef USE_PRECONDITIONS

      ! The following code is inherited from OBJECT
      allocate(self,stat=status)
      ENSURE(status==0,"ATOM:create ... error in allocating memory")
#else
      allocate(self)
#endif
   end subroutine

   PURE subroutine destroy(self)
   ! Deallocate "self"
      type(ATOM_TYPE), allocatable, INOUT :: self

#ifdef USE_PRECONDITIONS
      INT :: status
#endif

      ! The following code is inherited from OBJECT
      if (NOT allocated(self)) return

#ifdef USE_PRECONDITIONS
      deallocate(self,stat=status)
      ENSURE(status==0,"ATOM:destroy ... error in deallocating memory")
#else
      deallocate(self)
#endif
   end subroutine

   PURE subroutine destroy_ptr_part(self)
   ! Destroy the pointer parts of an atom
   ! WARNING: take care using this, you may need
   ! a unique-atom or all-atom destruction for the
   ! different pointer parts depending on how they
   ! were created.
      type(ATOM_TYPE), INOUT :: self

      ! WARNING: this may not be correct
      ! The destroy should be done outside of this module
      call destroy_(self%first_basis_fn_for_shell)
      call destroy_(self%last_basis_fn_for_shell)
      call destroy_(self%angular_moment_for_shell)
      call destroy_(self%basis_shell1pair)
      call destroy_(self%AOs)
      call destroy_(self%density_mx)
      call destroy_(self%NOs)
      call destroy_(self%NO_occ_nos)
      call destroy_(self%interpolator)

      ! Destroy NAOs - can always do this
      call destroy_NAO_matrices_(self)

      ! Do always destroy these
      call destroy_(self%pADP_vector)
      call destroy_(self%pADP_errors)
   end subroutine

   PURE subroutine destroy_NAO_matrices(self)
   ! Destroy the NAO pointer parts
      type(ATOM_TYPE), INOUT :: self
      if (NOT has_NAO_matrices_(self)) return
      call destroy_(self%NAOs)
      call destroy_(self%NAO_occupations)
   end subroutine

   PURE subroutine destroy_ANO_matrices(self)
   ! Destroy the (unique-atom) ANO pointer parts
   ! (and related info)
      type(ATOM_TYPE), INOUT :: self
      if (NOT has_ANO_matrices_(self)) return
      call destroy_(self%AOs)
      call destroy_(self%density_mx)
      call destroy_(self%NOs)
      call destroy_(self%NO_occ_nos)
   end subroutine

   PURE subroutine destroy_interpolators(self)
   ! Destroy the (unique-atom) ANO interpolators
      type(ATOM_TYPE), INOUT :: self
      if (NOT allocated(self%interpolator)) return
      if (self%is_unique_kind) call destroy_(self%interpolator)
   end subroutine

   PURE subroutine destroy_atom_data(self)
   ! Destroy the (non-unique) ANO pointer parts
      type(ATOM_TYPE), INOUT :: self
      if (NOT self%atom_data_made) return
      call destroy_(self%AOs)
      call destroy_(self%density_mx)
      call destroy_(self%NOs)
      call destroy_(self%NO_occ_nos)
      call destroy_(self%interpolator)
      self%atom_data_made = FALSE
   end subroutine

   PURE subroutine destroy_shell_info(self)
   ! Destroy the (unique-atom) shell info
      type(ATOM_TYPE), INOUT :: self
      if (NOT has_shell_info_(self)) return
      call destroy_(self%first_basis_fn_for_shell)
      call destroy_(self%last_basis_fn_for_shell)
      call destroy_(self%angular_moment_for_shell)
      call destroy_(self%basis_shell1pair)
   end subroutine


!  =========================
!  Set atom, shell, ANO info
!  =========================

   PURE subroutine set_NAOs(self,atom)
   ! Copy the NAO pointer parts (and related info)
      type(ATOM_TYPE), INOUT :: self
      type(ATOM_TYPE), IN :: atom
      if (NOT has_NAO_matrices_(atom)) return
      self%NAOs = atom%NAOs
      self%NAO_occupations = atom%NAO_occupations
   end subroutine

   PURE subroutine set_ANOs(self,atom)
   ! Copy the (unique-atom) ANO pointer parts (and related info)
      type(ATOM_TYPE), INOUT :: self
      type(ATOM_TYPE), IN :: atom
      if (NOT has_ANO_matrices_(atom)) return
      self%AOs = atom%AOs
      self%density_mx = atom%density_mx
      self%NOs = atom%NOs
      self%NO_occ_nos = atom%NO_occ_nos
   end subroutine

   PURE subroutine set_ANO_interpolators(self,atom)
   ! Copy the (unique-atom) ANO interpolators
      type(ATOM_TYPE), INOUT :: self
      type(ATOM_TYPE), IN :: atom
      if (NOT allocated(atom%interpolator)) return
      self%interpolator = atom%interpolator
   end subroutine

   PURE subroutine set_shell_info(self,atom)
   ! Destroy the (unique-atom) shell info
      type(ATOM_TYPE), INOUT :: self
      type(ATOM_TYPE), IN :: atom
      if (NOT has_shell_info_(atom)) return
      self%first_basis_fn_for_shell = atom%first_basis_fn_for_shell
      self%last_basis_fn_for_shell = atom%last_basis_fn_for_shell
      self%angular_moment_for_shell = atom%angular_moment_for_shell
      self%basis_shell1pair = atom%basis_shell1pair
   end subroutine

   PURE subroutine set_atom_data(self,atom)
   ! Copy the (non-unique) ANO pointer parts
      type(ATOM_TYPE), INOUT :: self
      type(ATOM_TYPE), IN :: atom
      if (NOT atom%atom_data_made) return
      call destroy_(self%AOs)
      call destroy_(self%density_mx)
      call destroy_(self%NOs)
      call destroy_(self%NO_occ_nos)
      self%AOs = atom%AOs
      self%density_mx = atom%density_mx
      self%NOs = atom%NOs
      self%NO_occ_nos = atom%NO_occ_nos
      call destroy_(self%interpolator)
      self%interpolator = atom%interpolator

      ! Kinds may not be sequential
      self%atom_data_made = TRUE
   end subroutine

   PURE subroutine set_interpolators(self,atom)
   ! Destroy the (non-unique) interpolators
      type(ATOM_TYPE), INOUT :: self
      type(ATOM_TYPE), IN :: atom
      if (NOT allocated(atom%interpolator)) return
      call destroy_(self%interpolator)
      self%interpolator = atom%interpolator
   end subroutine


