!  ============================
!  Set labels, dummies, charges
!  ============================

   PURE subroutine set_atom_data_from_label(self,label)
   ! Set the atom data such as its label, atomic_number, mass_number,
   ! nuclear_charge and atomic mass.
      type(ATOM_TYPE), INOUT :: self
      STR(len=*), IN :: label
      INT :: Z
      if (is_int_(label)) then

         ! Integer label must be the atomic number
         Z = to_int_(label)
         call set_atomic_number_(self,Z)
      else if (label(1:2)==ATOM_DUMMY_CHARGE_INPUT_SYMBOL) then

         ! This is a dummy charge, e.g Q:-0.3
         call set_dummy_charge_(self,label)
      else
         call set_label_(self,label)
      end if
   end subroutine

   elemental subroutine set_label(self,label,skip_mass)
   ! Set the atom "label" and related variables
      type(ATOM_TYPE), INOUT :: self
      STR(len=*), IN :: label
      BIN, optional, IN :: skip_mass

   ! ENSURE(label(1:1).is_alphabetical,"unacceptable atom symbol: "// trim(label))
      STR(len=2) :: chemical_symbol

      ! Set the tag - may not be unique
      self%tag = label
      self%label = label

      ! Skip next bit if requested
      if (present(skip_mass)) then
         if (skip_mass) then
            return
         end if
      end if

      ! Set atomic number and mass from symbol
      chemical_symbol = element_symbol_from_label_(label)
      call set_atomic_number_and_mass_(self,chemical_symbol)
   end subroutine


!   set_mm_label(label,Z)
!   ! Set a macromolecular atom "label" and related variables
!      self :: INOUT
!      label :: STR, IN
!      Z :: INT, IN
!
!      ! Set the tag - may not be unique
!      .tag   = label
!      .label = label
!
!      .set_atomic_number_and_mass(Z)
!
!   end

   elemental function element_symbol_from_label(label) result (symbol)
   ! Return a normalized element symbol from an atom "label"
      STR(len=*), IN :: label
      STR(len=2) :: symbol

   ! ENSURE(label(1:1).is_alphabetical,"unacceptable atom symbol: "// trim(label))
      INT :: lensym

      ! Label ends on nonalphabetical character
      lensym = index_of_nonalphabetical_(label)-1

      ! Check label is no more than two character long
      ! ENSURE(lensym<=2,"unacceptable atom symbol: "// trim(label(1:lensym)))

      ! lensym could be negative -- if no nonalphabetical chars!
      if (lensym<0) lensym = len_trim(label)

      ! Recheck label is no more than two character long
      ! ENSURE(lensym<=2,"unacceptable atom symbol: "// trim(label(1:lensym)))

      ! Get chemical symbol
      symbol = label(1:lensym)
      call to_upper_case_(symbol(1:1))
      if (lensym>1 AND is_upper_case_(symbol(2:2))) call to_lower_case_(symbol(2:2))
   end function

   PURE subroutine set_atomic_number_and_mass_0(self)
   ! Set the atomic mass from the .label and .mass_number
      type(ATOM_TYPE), INOUT :: self
   ENSURE(self%label/="?" AND self%label/=" ","ATOM:set_atomic_number_and_mass_0 ... label not set")
      call set_AN_and_M_helper_(self,self%label)
   end subroutine

   elemental subroutine set_atomic_number_and_mass_1(self,chemical_symbol)
   ! Set the atomic mass from the .label and .mass_number
      type(ATOM_TYPE), INOUT :: self
      STR(len=*), IN :: chemical_symbol
      call set_AN_and_M_helper_(self,chemical_symbol)
   end subroutine

   elemental subroutine set_AN_and_M_helper_0(self,symbol)
   ! Set the atomic mass from the .label and .mass_number
      type(ATOM_TYPE), INOUT :: self
      STR(len=*), IN :: symbol
      INT :: Z

      ! Assign atomic number from symbol
      select case (symbol(1:2))

      case ("El")
         ! An electron
         self%atomic_number = -1
         self%nuclear_charge = -ONE
         ! Mass of electron in C12 mass units
         self%mass = MASS_OF_ELECTRON_SI/AMU_SI

      case ("D")
         ! Dueterium
         self%atomic_number = 1
         self%mass_number = 2
         self%nuclear_charge = ONE
         self%mass = mass_of_isotope(Z=1,A=2)

      case ("T")
         ! This is dueterium/tritium
         self%atomic_number = 1
         self%mass_number = 2
         self%nuclear_charge = ONE
         self%mass = mass_of_isotope(Z=1,A=3)

      case default
         ! Regular element
         Z = index_of_(element_symbols(1:),symbol(1:2))
         if (Z==0) Z = index_of_(element_symbols(1:),symbol(1:1))  ! Try
         ! ENSURE(Z>0,"unknown element symbol: "//trim(symbol))
         self%atomic_number = Z
         self%nuclear_charge = Z*ONE
         self%mass = mass(self)
      end select
   end subroutine

   PURE subroutine set_atomic_number_and_mass_2(self,Z)
   ! Set the atomic mass from the .label and .mass_number
      type(ATOM_TYPE), INOUT :: self
      INT, IN :: Z
      call set_AN_and_M_helper_(self,Z)
   end subroutine

   PURE subroutine set_AN_and_M_helper_1(self,Z)
   ! Set the atomic mass from the .label and .mass_number
      type(ATOM_TYPE), INOUT :: self
      INT, IN :: Z
      self%atomic_number = Z
      self%nuclear_charge = Z*ONE
      self%mass = mass(self)
   end subroutine

   PURE subroutine set_dummy_charge(self,label)
   ! Set a dummy charge (integer) and related variables
      type(ATOM_TYPE), INOUT :: self
      STR(len=*), IN :: label
   ENSURE(label(1:2)==ATOM_DUMMY_CHARGE_INPUT_SYMBOL,"ATOM:set_dummy_charge ... invalid q-charge label: "//trim(label(1:2)))
   ENSURE(is_real_(label(3:)),"ATOM:set_dummy_charge ... invalid q-charge: "//trim(label(3:)))
      self%label = ATOM_DUMMY_CHARGE_LABEL
      self%atomic_number = 0
      self%nuclear_charge = to_real_(label(3:))  ! extract the charge
   end subroutine

   PURE subroutine set_atomic_number(self,val)
   ! Set the atomic number (integer) and related variables
      type(ATOM_TYPE), INOUT :: self
      INT, IN :: val
   ENSURE(val>0 OR val<119,"ATOM:set_atomic_number ... unknown atomic number: "//trim(to_str_(val)))
      self%atomic_number = val
      self%nuclear_charge = val
      self%label = chemical_symbol_(self)
      call set_atomic_number_and_mass_(self)
   end subroutine

   PURE subroutine set_is_cap_atom(self,val)
   ! Generic set
      type(ATOM_TYPE), INOUT :: self
