      ! The following code is inherited from OBJECT
      self%is_cap_atom = val
   end subroutine

   PURE subroutine set_n_core_electrons(self,val)
   ! Set the number of core electronbs in the case ECPs are used.
   ! For gaussian only so far.
      type(ATOM_TYPE), INOUT :: self
      INT, IN :: val
   ENSURE(val>0 OR val<119,"ATOM:set_n_core_electrons ... val out of range: "//trim(to_str_(val)))
      self%n_core_electrons = val
   end subroutine

   PURE subroutine set_mass_number(self,val)
   ! Set the atomic mass number. If the mass number is zero the
   ! atom is assumed to have an abunfance weighted mass, otherwise
   ! its mass is worked out from the isotope table
      type(ATOM_TYPE), INOUT :: self
      INT, IN :: val
   ENSURE(val>0 AND val<=118,"ATOM:set_mass_number ... unknown atomic number: "//trim(to_str_(val)))
   ENSURE(self%atomic_number>0,"ATOM:set_mass_number ... set mass number *after* atomic number")
      self%mass_number = val
      self%mass = mass(self)
   end subroutine

