!  =============
!  Set positions
!  =============

   PURE subroutine set_position(self,val)
   ! Set positions. Also set the pADP_vector.
   ! NOTE: Do you need to set the axis system too?
      type(ATOM_TYPE), INOUT :: self
      VEC(REAL,3), IN :: val
      self%position = val
      if (NOT allocated(self%pADP_vector)) then
         call create_(self%pADP_vector,9)
         self%pADP_vector(1:9) = ZERO
      end if
      self%pADP_vector(1:3) = val
   end subroutine

   PURE subroutine set_position_error(self,val)
   ! Set position error. Also set the pADP_error.
   ! NOTE: Do you need to set the axis system too?
      type(ATOM_TYPE), INOUT :: self
      VEC(REAL,3), IN :: val
   ENSURE(allocated(self%pADP_vector),"ATOM:set_position_error ... pADP_vector destroyed")
      self%position_error = val
      if (NOT allocated(self%pADP_errors)) then
         call create_(self%pADP_errors,9)
         self%pADP_errors(1:9) = ZERO
      end if
      self%pADP_errors(1:3) = val
   end subroutine

   subroutine check_position_and_pADP(self)
   ! Check if the .position and .pADP vector are consistent
      type(ATOM_TYPE), IN :: self
      if (allocated(self%pADP_vector)) then
         DIE_IF(NOT equals_(self%pADP_vector(1:3),self%position),"ATOM:check_position_and_pADP ... pADP_vector /= position")
      end if
   end subroutine


!  ========
!  Set ADPs
!  ========

   PURE subroutine set_U_iso(self,val)
   ! Set U_iso. Call "change_ADP2_axis_system"
   ! to get the full ADP_tensor from this!.
      type(ATOM_TYPE), INOUT :: self
      REAL, IN :: val

      ! Set it
      self%U_iso = val

   ! ! Set ADP tensor
   ! ADP.to_unit_mx
   ! ADP = ADP*.U_iso

   ! ! Set ADP_tensor & pADP_vector 
   ! .set_ADP2_tensor(ADP)
   end subroutine

   PURE subroutine set_U_iso_from_pADP(self,X)
   ! Set U_iso from the pADP vector "X". 
      type(ATOM_TYPE), INOUT :: self
      VEC(REAL,:), IN :: X
      REAL :: val

      ! Definition
      val = THIRD*sum(X(4:6))

      ! Set
      self%U_iso = val
   end subroutine

   PURE subroutine set_U_iso_error(self,err)
   ! Set U_iso_error. Call "change_ADP2_axis_system"
   ! to get the full pADP_errors from this!.
      type(ATOM_TYPE), INOUT :: self
      REAL, IN :: err
      self%U_iso_error = err
   end subroutine

   PURE subroutine set_U_iso_error_from_pADP(self,X)
   ! Set U_iso_error from the pADP vector "X". 
      type(ATOM_TYPE), INOUT :: self
      VEC(REAL,:), IN :: X
      REAL :: val

      ! Definition
      val = THIRD*sum(X(4:6))

      ! Set
      self%U_iso_error = val
   end subroutine

   PURE subroutine set_M_ani(self,val)
   ! Set M_ani. Call "change_ADP2_axis_system"
   ! to get the full ADP_tensor from this!.
      type(ATOM_TYPE), INOUT :: self
      REAL, IN :: val

      ! Set it
      self%M_ani = val
   end subroutine

   PURE subroutine set_M_ani_from_pADP(self,X)
   ! Set M_ani from the pADP vector "X". 
      type(ATOM_TYPE), INOUT :: self
      VEC(REAL,:), IN :: X
      REAL :: val

      ! Definition
      val = THREE*sum(X(7:9)*X(7:9))
      val = val+HALF*(X(4)-X(5))**2
      val = val+HALF*(X(4)-X(6))**2
      val = val+HALF*(X(5)-X(6))**2

      ! Set
      self%M_ani = sqrt(val)
   end subroutine

   PURE subroutine set_M_ani_error(self,err)
   ! Set U_iso_error. Call "change_ADP2_axis_system"
   ! to get the full pADP_errors from this!.
      type(ATOM_TYPE), INOUT :: self
      REAL, IN :: err
      self%M_ani_error = err
   end subroutine

   PURE subroutine set_M_ani_error_from_pADP(self)
   ! Set M_ani from the ".covariance_mx" and the .pADP_vector
   ! and .M_ani is already set!
      type(ATOM_TYPE), INOUT :: self
      VEC(REAL,6) :: dU
      REAL :: val
   ENSURE(allocated(self%pADP_vector),"ATOM:set_M_ani_error_from_pADP ... no .pADP_vector")
   ENSURE(size(self%covariance_mx,1)==no_of_pADPs_(self),"ATOM:set_M_ani_error_from_pADP ... wrong size, .covariance_mx")
   ENSURE(allocated(self%covariance_mx),"ATOM:set_M_ani_error_from_pADP ... no .covariance_mx")
   ENSURE(size(self%covariance_mx,1)==no_of_pADPs_(self),"ATOM:set_M_ani_error_from_pADP ... wrong size, .covariance_mx")

      ! Work out derivative
      dU(1) = 2*self%pADP_vector(4)-self%pADP_vector(5)-self%pADP_vector(6)  ! U_11
      dU(2) = 2*self%pADP_vector(5)-self%pADP_vector(4)-self%pADP_vector(6)  ! U_22
      dU(3) = 2*self%pADP_vector(6)-self%pADP_vector(4)-self%pADP_vector(5)  ! etc ...
      dU(4) = 6*self%pADP_vector(7)
      dU(5) = 6*self%pADP_vector(8)
      dU(6) = 6*self%pADP_vector(9)

      ! Error in (M_ani)^2 - use cov matrix here!
      val = dot_product(dU,matmul(self%covariance_mx(4:9,4:9),dU))

      ! Error - calculate max of of the difference on the square
      ! root of the upper and lower limits of M2_ani. For M = sqrt(M2),
      ! that difference is sigma(M2)/(2M), and "val" above is the
      ! VARIANCE of M2 -- so it is sqrt(val) that goes on top. Using val
      ! itself gave units of U^3 where an esd of U^2 must have units U^2,
      ! and a number ~4e5 too small, which always printed as "(0)" and so
      ! looked exactly like the "no covariance available" case. See
      ! TASKS_AND_HISTORY.md.
      ! NOTE: M_ani is a square root, so this expression is singular at
      ! M_ani = 0 -- which is the case whenever the ADP tensor is exactly
      ! isotropic or absent, as it is for an atom read from a CIF with no
      ! anisotropic ADPs. Linear propagation says nothing about the error
      ! there, so report zero rather than Inf or NaN.
      if (self%M_ani>ZERO) then
         self%M_ani_error = sqrt(max(val,ZERO))/(2*self%M_ani)
      else
         self%M_ani_error = ZERO
      end if
   end subroutine

   PURE subroutine set_ADP_tensor_0(self,val)
   ! Set the ADP tensor, p_ADP_tensor and U_iso, if possible.  
   ! NOTE: pADP_vector is created when position is set.
   ! NOTE: Do you need to set the .ADP_axis_system too?
      type(ATOM_TYPE), INOUT :: self
      REAL, IN :: val
   ENSURE(allocated(self%pADP_vector),"ATOM:set_ADP_tensor_0 ... pADP_vector destroyed")
      self%ADP_tensor = val
      self%pADP_vector(4:9) = val

      ! Set U_iso
      if (self%ADP_axis_system=="cartesian") then
         call set_U_iso_(self,THIRD*val)
         call set_M_ani_(self,ZERO)
      end if
   end subroutine

   PURE subroutine set_ADP_tensor_1(self,vec)
   ! Set the ADP tensor, p_ADP_tensor and U_iso, if possible.  
   ! Set from vector "vec" in the order: xx, yy, zz, xy, xz, yz.
   ! NOTE: pADP_vector is created when position is set.
   ! NOTE: Do you need to set the .ADP_axis_system too?
      type(ATOM_TYPE), INOUT :: self
      VEC(REAL,:), IN :: vec
      MAT(REAL,3,3) :: ADP
   ENSURE(size(vec)==6,"ATOM:set_ADP_tensor_1 ... val: wrong size")

      ! Transfer
      ADP(1,1) = vec(1)
      ADP(2,2) = vec(2)
      ADP(3,3) = vec(3)
      ADP(1,2) = vec(4)
      ADP(2,1) = vec(4)
      ADP(1,3) = vec(5)
      ADP(3,1) = vec(5)
      ADP(2,3) = vec(6)
      ADP(3,2) = vec(6)

      ! Set *all* ADP parameters
      call set_ADP_tensor_(self,ADP)
   end subroutine

   PURE subroutine set_ADP_tensor_2(self,mx)
   ! Set the ADP tensor, p_ADP_tensor and U_iso, if possible.  
   ! NOTE: pADP_vector is created when position is set.
   ! NOTE: Do you need to set the .ADP_axis_system too?
      type(ATOM_TYPE), INOUT :: self
      MAT(REAL,3,3), IN :: mx
   ENSURE(allocated(self%pADP_vector),"ATOM:set_ADP_tensor_2 ... pADP_vector destroyed")

      ! Set tensor
      call set_ADP2_tensor_(self,mx)

      ! Set U_iso
      if (self%ADP_axis_system=="cartesian") then
         call set_U_iso_from_pADP_(self,self%pADP_vector)
         call set_M_ani_from_pADP_(self,self%pADP_vector)
      end if
   end subroutine

   PURE subroutine set_ADP2_tensor(self,mx)
   ! Set *only* the ADP_tensor and pADP_vector
      type(ATOM_TYPE), INOUT :: self
      MAT(REAL,3,3), IN :: mx
   ENSURE(allocated(self%pADP_vector),"ATOM:set_ADP2_tensor ... pADP_vector destroyed")

      ! Set tensor
      self%ADP_tensor = mx

      ! Set pADP
      self%pADP_vector(4) = mx(1,1)
      self%pADP_vector(5) = mx(2,2)
      self%pADP_vector(6) = mx(3,3)
      self%pADP_vector(7) = mx(1,2)
      self%pADP_vector(8) = mx(1,3)
      self%pADP_vector(9) = mx(2,3)
   end subroutine


!  ===============
!  Set axis system
!  ===============

   PURE subroutine set_axis_system_to(self,word)
   ! Set the axis system type to "word".
   ! Currently allowed is: "cartesian" or "crystal".
      type(ATOM_TYPE), INOUT :: self
      STR(len=*), IN :: word
   ENSURE(is_one_of_(word,["cartesian","crystal  "]),"ATOM:set_axis_system_to ... unknown axis system!")
      call set_pos_axis_system_to_(self,word)
      call set_ADP_axis_system_to_(self,word)
      call set_ADPn_axis_system_to_(self,word)
   end subroutine

   PURE subroutine set_pos_axis_system_to(self,word)
   ! Set the position axis system type to "word".
   ! Currently allowed is: "cartesian" or "crystal".
   ! NOTE: all .ADP_axis_system's are changed too.
      type(ATOM_TYPE), INOUT :: self
      STR(len=*), IN :: word
   ENSURE(is_one_of_(word,["cartesian","crystal  "]),"ATOM:set_pos_axis_system_to ... unknown axis system!")
      self%pos_axis_system = word
   end subroutine

   PURE subroutine set_ADP_axis_system_to(self,word)
   ! Set **all** the ADP axis systems to "word".
   ! Currently allowed, is: "cartesian" or "crystal".
      type(ATOM_TYPE), INOUT :: self
      STR(len=*), IN :: word
   ENSURE(is_one_of_(word,["cartesian","crystal  "]),"ATOM:set_ADP_axis_system_to ... unknown axis system!")
      self%ADP_axis_system = word
   end subroutine

   PURE subroutine set_ADPn_axis_system_to(self,word)
   ! Set the ADPn axis systems to "word".
   ! Currently allowed, is: "cartesian" or "crystal".
      type(ATOM_TYPE), INOUT :: self
      STR(len=*), IN :: word
   ENSURE(is_one_of_(word,["cartesian","crystal  "]),"ATOM:set_ADPn_axis_system_to ... unknown axis system!")
      self%ADPn_axis_system = word
   end subroutine


!  =======================================
!  Parameter vector (position/ADP) setting
!  =======================================

! Put tensors

   PURE subroutine put_ADP2_vector_to_0(self,adp2,fac)
   ! Put the ADP2s into the "adp2" tensor from the pADP_vector.
   ! If present, include length-conversion factor "fac".
      type(ATOM_TYPE), IN :: self
      MAT(REAL,3,3), OUT :: adp2
      REAL, optional, IN :: fac
      REAL :: fac2
      VEC(REAL,6) :: v2
   ENSURE(allocated(self%pADP_vector),"ATOM:put_ADP2_vector_to_0 ... no pADP_vector")
   ENSURE(size(self%pADP_vector)>=9,"ATOM:put_ADP2_vector_to_0 ... pADP_vector too small")

      ! Reorder from lexical -> lower pyramid
      call lexical_2_to_lower_pyramid_(self%pADP_vector(4:9),v2)

      ! Uncompress lower pyramid -> tensor
      call uncompress_from_pyramid_(adp2,v2)
      if (present(fac)) then
         fac2 = fac*fac
         adp2 = fac2*adp2
      end if
   end subroutine

   PURE subroutine put_ADP3_vector_to_0(self,adp3,fac)
   ! Put the ADP3s into the "adp3" tensor from the pADP_vector.
   ! If present, include length-conversion factor "fac".
      type(ATOM_TYPE), IN :: self
      MAT3(REAL,3,3,3), OUT :: adp3
      REAL, optional, IN :: fac
      REAL :: fac3
      VEC(REAL,10) :: v3
   ENSURE(allocated(self%pADP_vector),"ATOM:put_ADP3_vector_to_0 ... no pADP_vector")
   ENSURE(size(self%pADP_vector)>=19,"ATOM:put_ADP3_vector_to_0 ... pADP_vector too small")

      ! Reorder from lexical -> lower pyramid
      call lexical_3_to_lower_pyramid_(self%pADP_vector(10:19),v3)

      ! Uncompress lower pyramid -> tensor
      call uncompress_from_pyramid_(adp3,v3)

      ! Change units
      if (present(fac)) then
         fac3 = fac*fac*fac
         adp3 = fac3*adp3
      end if
   end subroutine

   PURE subroutine put_ADP4_vector_to_0(self,adp4,fac)
   ! Put the ADP4s into the "adp4" tensor from the pADP_vector.
   ! If present, include length-conversion factor "fac".
      type(ATOM_TYPE), IN :: self
      MAT4(REAL,3,3,3,3), OUT :: adp4
      REAL, optional, IN :: fac
      REAL :: fac4
      VEC(REAL,15) :: v4
   ENSURE(allocated(self%pADP_vector),"ATOM:put_ADP4_vector_to_0 ... no pADP_vector")
   ENSURE(size(self%pADP_vector)>=34,"ATOM:put_ADP4_vector_to_0 ... pADP_vector too small")

      ! Reorder from lexical -> lower pyramid
      call lexical_4_to_lower_pyramid_(self%pADP_vector(20:34),v4)

      ! Uncompress lower pyramid -> tensor
      call uncompress_from_pyramid_(adp4,v4)

      ! Change units
      if (present(fac)) then
         fac4 = fac*fac*fac*fac
         adp4 = fac4*adp4
      end if
   end subroutine

   PURE subroutine put_ADP2_errors_to_0(self,adp2_errors,fac)
   ! Put the ADP2s into the "adp2" tensor from the pADP_vector.
   ! If present, include length-conversion factor "fac".
      type(ATOM_TYPE), IN :: self
      MAT(REAL,3,3), OUT :: adp2_errors
      REAL, optional, IN :: fac
      REAL :: fac2
      VEC(REAL,6) :: v2
   ENSURE(allocated(self%pADP_errors),"ATOM:put_ADP2_errors_to_0 ... no pADP_errors")
   ENSURE(size(self%pADP_errors)>=9,"ATOM:put_ADP2_errors_to_0 ... pADP_errors too small")

      ! Reorder from lexical -> lower pyramid
      call lexical_2_to_lower_pyramid_(self%pADP_errors(4:9),v2)

      ! Uncompress lower pyramid -> tensor
      call uncompress_from_pyramid_(adp2_errors,v2)
      if (present(fac)) then
         fac2 = fac*fac
         adp2_errors = fac2*adp2_errors
      end if
   end subroutine

   PURE subroutine put_ADP3_errors_to_0(self,adp3_errors,fac)
   ! Put the ADP3 errors into the "adp3" tensor from the pADP_vector.
   ! If present, include length-conversion factor "fac".
      type(ATOM_TYPE), IN :: self
      MAT3(REAL,3,3,3), OUT :: adp3_errors
      REAL, optional, IN :: fac
      REAL :: fac3
      VEC(REAL,10) :: v3
   ENSURE(allocated(self%pADP_errors),"ATOM:put_ADP3_errors_to_0 ... no pADP_errors")
   ENSURE(size(self%pADP_errors)>=19,"ATOM:put_ADP3_errors_to_0 ... pADP_errors too small")

      ! Reorder from lexical -> lower pyramid
      call lexical_3_to_lower_pyramid_(self%pADP_errors(10:19),v3)

      ! Uncompress lower pyramid -> tensor
      call uncompress_from_pyramid_(adp3_errors,v3)

      ! Change units
      if (present(fac)) then
         fac3 = fac*fac*fac
         adp3_errors = fac3*adp3_errors
      end if
   end subroutine

   PURE subroutine put_ADP4_errors_to_0(self,adp4_errors,fac)
   ! Put the ADP4 errors into the "adp4" tensor from the pADP_vector.
   ! If present, include length-conversion factor "fac".
      type(ATOM_TYPE), IN :: self
      MAT4(REAL,3,3,3,3), OUT :: adp4_errors
      REAL, optional, IN :: fac
      REAL :: fac4
      VEC(REAL,15) :: v4
   ENSURE(allocated(self%pADP_errors),"ATOM:put_ADP4_errors_to_0 ... no pADP_errors")
   ENSURE(size(self%pADP_errors)>=34,"ATOM:put_ADP4_errors_to_0 ... pADP_errors too small")

      ! Reorder from lexical -> lower pyramid
      call lexical_4_to_lower_pyramid_(self%pADP_errors(20:34),v4)

      ! Uncompress lower pyramid -> tensor
      call uncompress_from_pyramid_(adp4_errors,v4)

      ! Change units
      if (present(fac)) then
         fac4 = fac*fac*fac*fac
         adp4_errors = fac4*adp4_errors
      end if
   end subroutine


! Reset

   PURE subroutine reset_pADPs_and_errors(self,dim)
   ! Reset the positional-ADP parameters and errors to size "dim".
   ! NOTE: the pADPs and errors are *expanded*.
      type(ATOM_TYPE), INOUT :: self
      INT, IN :: dim
      VEC(REAL,:), allocatable :: X,dX

      ! Create pADPs, and set to existing pADPs
      if (NOT allocated(self%pADP_vector)) then
         call create_(X,9)
         call put_pADP_vector_to_(self,X)
         call create_(self%pADP_vector,9)
         call set_pADP_vector_to_(self,X)
         call destroy_(X)
      end if

      ! Create pADPs_error, and set to ZERO
      if (NOT allocated(self%pADP_errors)) then
         call create_(dX,9)
         dX = ZERO
         call create_(self%pADP_errors,9)
         call set_pADP_errors_to_(self,dX)
         call destroy_(dX)
      end if

      ! Expand if necessary.
      ! New (if any) values to zero.
      if (dim>size(self%pADP_vector)) then
         call expand_(self%pADP_vector,dim,init=ZERO)
         call expand_(self%pADP_errors,dim,init=ZERO)
      end if
   end subroutine


! Set via pADP_vector

   PURE subroutine set_pADP_vector_to(self,X)
   ! Set the pADP vector from vector "X".
   ! NOTE: Also sets positions and ADP_tensor.
   ! NOTE: "X" musts be correct size.
      type(ATOM_TYPE), INOUT :: self
      VEC(REAL,:), IN :: X
   ENSURE(size(X)>=9,"ATOM:set_pADP_vector_to ... X too small")
   ENSURE(allocated(self%pADP_vector),"ATOM:set_pADP_vector_to ... no pADP_vector")
   ENSURE(size(self%pADP_vector)==size(X),"ATOM:set_pADP_vector_to ... wrong size, X")

      ! Set positions
      self%position(1) = X(1)
      self%position(2) = X(2)
      self%position(3) = X(3)

      ! Set ADP tensor
      self%ADP_tensor(1,1) = X(4)
      self%ADP_tensor(2,2) = X(5)
      self%ADP_tensor(3,3) = X(6)
      self%ADP_tensor(1,2) = X(7)
      self%ADP_tensor(2,1) = X(7)
      self%ADP_tensor(1,3) = X(8)
      self%ADP_tensor(3,1) = X(8)
      self%ADP_tensor(2,3) = X(9)
      self%ADP_tensor(3,2) = X(9)

      ! Set. Must be correct size
      self%pADP_vector = X

      ! Set U_iso
      if (self%ADP_axis_system=="cartesian") then
         call set_U_iso_from_pADP_(self,X)
         call set_M_ani_from_pADP_(self,X)
      end if
   end subroutine

   PURE subroutine set_ADP2_vector_to(self,U)
   ! Set the ADP2s from vector "U".
      type(ATOM_TYPE), INOUT :: self
      VEC(REAL,:), IN :: U
   ENSURE(allocated(self%pADP_vector),"ATOM:set_ADP2_vector_to ... no pADPs")
   ENSURE(size(self%pADP_vector)>=9,"ATOM:set_ADP2_vector_to ... pADP_vector: wrong size")
   ENSURE(size(U)==6,"ATOM:set_ADP2_vector_to ... wrong size, U")
      self%pADP_vector(4:9) = U(1:6)

      ! Set U_iso
      if (self%ADP_axis_system=="cartesian") then
         call set_U_iso_from_pADP_(self,self%pADP_vector)
         call set_M_ani_from_pADP_(self,self%pADP_vector)
      end if
   end subroutine

   PURE subroutine set_ADP3_vector_to_0(self,U)
   ! Set the ADP3s from vector "U".
      type(ATOM_TYPE), INOUT :: self
      VEC(REAL,:), IN :: U
   ENSURE(allocated(self%pADP_vector),"ATOM:set_ADP3_vector_to_0 ... no pADPs")
   ENSURE(size(self%pADP_vector)>=19,"ATOM:set_ADP3_vector_to_0 ... pADP_vector: wrong size")
   ENSURE(size(U)==10,"ATOM:set_ADP3_vector_to_0 ... wrong size, U")
      self%pADP_vector(10:19) = U(1:10)
   end subroutine

   PURE subroutine set_ADP4_vector_to_0(self,U)
   ! Set the ADP4s from vector "U".
      type(ATOM_TYPE), INOUT :: self
      VEC(REAL,:), IN :: U
   ENSURE(allocated(self%pADP_vector),"ATOM:set_ADP4_vector_to_0 ... no pADPs")
   ENSURE(size(self%pADP_vector)>=34,"ATOM:set_ADP4_vector_to_0 ... pADP_vector: wrong size")
   ENSURE(size(U)==15,"ATOM:set_ADP4_vector_to_0 ... wrong size, U")
      self%pADP_vector(20:34) = U(1:15)
   end subroutine


! Set via tensors

   PURE subroutine set_ADP3_vector_to_1(self,adp3)
   ! Set the ADP3s from the "adp3" tensor into the pADP_vector.
      type(ATOM_TYPE), INOUT :: self
      MAT3(REAL,3,3,3), OUT :: adp3
      VEC(REAL,10) :: v3,w3
   ENSURE(allocated(self%pADP_vector),"ATOM:set_ADP3_vector_to_1 ... no pADP_vector")
   ENSURE(size(self%pADP_vector)>=19,"ATOM:set_ADP3_vector_to_1 ... pADP_vector too small")

      ! Compress tensor -> lower pyramid
      call compress_to_pyramid_(adp3,v3)

      ! Reorder from lower pyramid -> lexical
      call lower_pyramid_to_lexical_3_(v3,w3)

      ! Set it
      call set_ADP3_vector_to_(self,w3)
   end subroutine

   PURE subroutine set_ADP4_vector_to_1(self,adp4)
   ! Set the ADP4s into the "adp3" tensor from the pADP_vector.
      type(ATOM_TYPE), INOUT :: self
      MAT4(REAL,3,3,3,3), OUT :: adp4
      VEC(REAL,15) :: v4,w4
   ENSURE(allocated(self%pADP_vector),"ATOM:set_ADP4_vector_to_1 ... no pADP_vector")
   ENSURE(size(self%pADP_vector)>=19,"ATOM:set_ADP4_vector_to_1 ... pADP_vector too small")

      ! Compress tensor -> lower pyramid
      call compress_to_pyramid_(adp4,v4)

      ! Reorder from lower pyramid -> lexical
      call lower_pyramid_to_lexical_4_(v4,w4)

      ! Set it
      call set_ADP4_vector_to_(self,w4)
   end subroutine

   PURE subroutine set_ADP3_errors_to_0(self,adp3)
   ! Set the ADP3 errors from the "adp3" tensor into the pADP_errors.
      type(ATOM_TYPE), INOUT :: self
      MAT3(REAL,3,3,3), OUT :: adp3
      VEC(REAL,10) :: v3,w3
   ENSURE(allocated(self%pADP_errors),"ATOM:set_ADP3_errors_to_0 ... no pADP_errors")
   ENSURE(size(self%pADP_errors)>=19,"ATOM:set_ADP3_errors_to_0 ... pADP_errors too small")

      ! Compress tensor -> lower pyramid
      call compress_to_pyramid_(adp3,v3)

      ! Reorder from lower pyramid -> lexical
      call lower_pyramid_to_lexical_3_(v3,w3)

      ! Set it
      call set_ADP3_errors_to_(self,w3)
   end subroutine

   PURE subroutine set_ADP4_errors_to_0(self,adp4)
   ! Set the ADP4 errorss into the "adp3" tensor from the pADP_errors.
      type(ATOM_TYPE), INOUT :: self
      MAT4(REAL,3,3,3,3), OUT :: adp4
      VEC(REAL,15) :: v4,w4
   ENSURE(allocated(self%pADP_errors),"ATOM:set_ADP4_errors_to_0 ... no pADP_errors")
   ENSURE(size(self%pADP_errors)>=19,"ATOM:set_ADP4_errors_to_0 ... pADP_errors too small")

      ! Compress tensor -> lower pyramid
      call compress_to_pyramid_(adp4,v4)

      ! Reorder from lower pyramid -> lexical
      call lower_pyramid_to_lexical_4_(v4,w4)

      ! Set it
      call set_ADP4_errors_to_(self,w4)
   end subroutine


! Set via pADP_errors

   PURE subroutine zero_pADP_error(self)
   ! Set position error. Also set the pADP_error.
   ! NOTE: Do you need to set the axis system too?
      type(ATOM_TYPE), INOUT :: self
      VEC(REAL,9) :: dX
   ENSURE(allocated(self%pADP_errors),"ATOM:zero_pADP_error ... pADP_errors destroyed")
      dX = ZERO
      call set_pADP_errors_to_(self,dX)

      ! Do these as well?
      self%U_iso = ZERO
      self%M_ani = ZERO
   end subroutine

   PURE subroutine set_pADP_errors_to_0(self,dX)
   ! Set the parameter errors (positions and ADPs) to "dX".
   ! NOTE: The pADP's and errors must be already created
   ! NOTE: "dX" must be correct size.
      type(ATOM_TYPE), INOUT :: self
      VEC(REAL,:), IN :: dX
   ENSURE(allocated(self%pADP_errors),"ATOM:set_pADP_errors_to_0 ... no pADP_errors")
   ENSURE(size(self%pADP_errors)==size(dX),"ATOM:set_pADP_errors_to_0 ... wrong size, dX")
      self%position_error = dX(1:3)
      self%pADP_errors = dX
   end subroutine

   PURE subroutine set_pADP_errors_to_1(self,covariance_mx,H_U_iso)
   ! Set the parameter errors (positions and ADPs) to "dX".
   ! and set the errors in U_iso and M_ani.
   ! NOTE: The pADP's and errors must be already created
   ! NOTE: "dX" must be correct size.
      type(ATOM_TYPE), INOUT :: self
      MAT(REAL,:,:), IN :: covariance_mx
      BIN, IN :: H_U_iso
      VEC(REAL,:), allocatable :: dX
      REAL :: val
   ENSURE(allocated(self%pADP_errors),"ATOM:set_pADP_errors_to_1 ... no pADP_errors")

      ! Store the covariance mx
      self%covariance_mx = covariance_mx

      ! Get dX as sqrt of diagonal of "cov"
      call create_(dX,size(covariance_mx,1))
      call put_diagonal_to_(covariance_mx,dX)

      ! A variance cannot be negative. But if the least-squares
      ! variance-covariance matrix is not positive definite its diagonal can
      ! come out slightly negative, and sqrt() then returns NaN -- which
      ! propagated silently into .pADP_errors, into the ADP esds, and into the
      ! CIF, where it was printed as "(0)": a meaningless number wearing the
      ! clothes of a confident one. Confirmed 2026-07-29 in
      ! long/urea_rhf_STO-3G_HAR (one NaN esd) and, without the sqrt, as
      ! negative esds in short/urea_lamaGOET_grown_CIF.
      ! Clamp to zero so the esd is visibly meaningless instead, and say so.
      ! NOTE this only makes the SYMPTOM safe. A negative variance means the
      ! v-cov matrix is wrong and that root cause is still open -- see
      ! TASKS_AND_HISTORY.md.
      WARN_IF(any(dX<ZERO),"ATOM:set_pADP_errors_to_1 ... negative variance on the covariance diagonal: the variance-covariance matrix is not positive definite. The affected esd is set to zero and is NOT meaningful")
      dX = sqrt(max(dX,ZERO))

      ! Set
      call set_pADP_errors_to_(self,dX)
      call destroy_(dX)

      ! Set U_iso error. An isotropic U is one refined parameter whose
      ! variance every diagonal component carries, so the mean is its esd.
      if (self%atomic_number==1 AND H_U_iso) then
         val = THIRD*sum(self%pADP_errors(4:6))
         call set_U_iso_error_(self,val)
      else
         call set_U_iso_error_from_pADP_(self,self%pADP_errors)  ! This is what you expect, normally
         call set_M_ani_error_from_pADP_(self)
      end if
   end subroutine

   pure function pADP_covariance_can_be_made(self) result (res)
   ! Return TRUE if a cartesian covariance matrix can be made for this
   ! atom from its own standard uncertainties.
   ! The atom must still be in the crystal frame -- a cartesian CIF needs
   ! no conversion -- and its parameter count must be one Tonto knows how
   ! to map: 9 (harmonic), 19 (with ADP3s) or 34 (with ADP4s too).
   ! NOTE: a real runtime test, not an ENSURE, which compiles to nothing
   ! in an optimised build.
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = FALSE
      if (self%pos_axis_system/="crystal") return
      if (self%ADP_axis_system/="crystal") return
      ! NOTE: only ask about the ADPn frame if there ARE ADPn's. That
      ! component DEFAULTs to "cartesian" and is set to "crystal" only by
      ! the ADP3/ADP4 readers, so testing it unconditionally silently
      ! disables this for every harmonic structure. Same idiom as
      ! VEC{ATOM}:all_ADPn_axis_systems_are_cartesian.
      if (has_ADP3s_(self) AND self%ADPn_axis_system/="crystal") return
      if (NOT allocated(self%pADP_errors)) return
      if (size(self%pADP_errors)/=no_of_pADPs_(self)) return
      if (size(self%pADP_errors)/=9 AND size(self%pADP_errors)/=19 AND size(self%pADP_errors)/=34) return
      res = TRUE
   end function

   subroutine make_pADP_covariance_from_esds(self,cell)
   ! Make the cartesian covariance matrix for this atom's positions and
   ! ADP2's from its own standard uncertainties, ASSUMING THOSE ARE
   ! UNCORRELATED, and reset the errors from it.
   !
   ! Call this while the atom is still in the crystal frame. Afterwards
   ! ".covariance_mx" -- and hence ".pADP_errors" -- are cartesian, like
   ! everything else in Tonto, and every later frame change is exact
   ! because a covariance carries what a sigma throws away.
   !
   ! The independence assumption is the one approximation, and it is made
   ! once, here, at the only point where the information genuinely does
   ! not exist: a CIF reports uncertainties but not the covariance they
   ! would have to be propagated through. ".pADP_covariances_derived" is
   ! set so a consumer can tell this from a refinement's own covariance.
   !
   ! NOTE: T V T^T is positive semi-definite whenever V is, so no
   ! variance can come out negative and no esd can come out NaN. That is
   ! by construction, not by clamping.
      type(ATOM_TYPE), INOUT :: self
      type(UNIT_CELL_TYPE), IN :: cell
      MAT(REAL,6,6) :: T6
      MAT(REAL,10,10) :: T10
      MAT(REAL,15,15) :: T15
      MAT(REAL,3,3) :: D3,C3
      MAT(REAL,6,6) :: D6,C6
      MAT(REAL,10,10) :: D10,C10
      MAT(REAL,15,15) :: D15,C15
      MAT(REAL,:,:), allocatable :: V
      VEC(REAL,:), allocatable :: s
      INT :: n
      if (NOT pADP_covariance_can_be_made_(self)) return
      n = no_of_pADPs_(self)
      call create_(s,n)
      s = self%pADP_errors(1:n)

      ! Positions: dimensionless fractional sigmas -> bohr, via the direct
      ! cell matrix, which carries the axis change and the units together
      D3 = ZERO
      call set_diagonal_to_(D3,s(1:3)*s(1:3))
      call back_transform_to_(D3,C3,cell%direct_mx)

      ! ADP2's: the induced map on the packed vector for the SAME basis
      ! change the ADP values themselves use, MAT:change_basis_to(direct_U_mx).
      ! to_tensor_change_basis_of builds exactly that map, in the
      ! crystallographic 11,22,33,12,13,23 order, so there is no transpose
      ! left to get backwards -- which is how the sibling defect in
      ! CRYSTAL:make_CIF_esds arose. See TASKS_AND_HISTORY.md.
      call to_tensor_change_basis_of_(T6,cell%direct_U_mx,reorder=TRUE)
      D6 = ZERO
      call set_diagonal_to_(D6,s(4:9)*s(4:9))
      call back_transform_to_(D6,C6,T6)

      ! Assemble. Parameters of different order do not mix under an axis
      ! change, so the off-diagonal blocks are genuinely zero, not merely
      ! unknown.
      call create_(V,n,n)
      V = ZERO
      V(1:3,1:3) = C3
      V(4:9,4:9) = C6

      ! ADP3's and ADP4's, if this atom is anharmonic. Their value
      ! transform is MAT3/MAT4:back_transform_to(new,direct_mx), and
      ! symmetric_tensor_3/4_product_mx(res,R) is exactly the induced map
      ! for that -- verified numerically to 1e-15 against the tensor
      ! contraction, R and NOT its transpose. See TASKS_AND_HISTORY.md.
      if (n>=19) then
         call symmetric_tensor_3_product_mx_(T10,cell%direct_mx)
         D10 = ZERO
         call set_diagonal_to_(D10,s(10:19)*s(10:19))
         call back_transform_to_(D10,C10,T10)
         V(10:19,10:19) = C10
      end if
      if (n>=34) then
         call symmetric_tensor_4_product_mx_(T15,cell%direct_mx)
         D15 = ZERO
         call set_diagonal_to_(D15,s(20:34)*s(20:34))
         call back_transform_to_(D15,C15,T15)
         V(20:34,20:34) = C15
      end if

      ! This is the same entry point the refinement path uses: it stores
      ! the covariance, sets .pADP_errors to sqrt of its diagonal, and
      ! derives the U_iso and M_ani errors.
      call set_pADP_errors_to_(self,V,FALSE)
      self%pADP_covariances_derived = TRUE
      call destroy_(V)
      call destroy_(s)
   end subroutine

   PURE subroutine set_ADP2_errors_to_0(self,dU)
   ! Set the second-order ADP errors from vector "dU".
      type(ATOM_TYPE), INOUT :: self
      VEC(REAL,:), IN :: dU
   ENSURE(allocated(self%pADP_errors),"ATOM:set_ADP2_errors_to_0 ... no pADP_errors")
   ENSURE(size(self%pADP_errors)>=9,"ATOM:set_ADP2_errors_to_0 ... wrong size, pADP_errors")
   ENSURE(size(dU)==6,"ATOM:set_ADP2_errors_to_0 ... wrong size, dU")
      self%pADP_errors(4:9) = dU(1:6)
   end subroutine


