! Set via tensors

   PURE subroutine set_ADP2_errors_to_1(self,dU)
   ! Set the second-order ADP errors from vector "dU" *matrix*
      type(ATOM_TYPE), INOUT :: self
      MAT(REAL,3,3), IN :: dU
   ENSURE(allocated(self%pADP_errors),"ATOM:set_ADP2_errors_to_1 ... no pADP_errors")
   ENSURE(size(self%pADP_errors)>=9,"ATOM:set_ADP2_errors_to_1 ... wrong size, pADP_errors")
      self%pADP_errors(4) = dU(1,1)
      self%pADP_errors(5) = dU(2,2)
      self%pADP_errors(6) = dU(3,3)
      self%pADP_errors(7) = dU(1,2)
      self%pADP_errors(8) = dU(1,3)
      self%pADP_errors(9) = dU(2,3)
   end subroutine


