! Put vector

   PURE subroutine put_pos_vector_to(self,X,fac)
   ! Put the position vector into vector "X".
   ! If present, include length-conversion factor "fac".
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: X
      REAL, optional, IN :: fac
   ENSURE(size(X)>=3,"ATOM:put_pos_vector_to ... wrong size, X")
      if (NOT present(fac)) then

         ! In atomic units
         X(1) = self%position(1)
         X(2) = self%position(2)
         X(3) = self%position(3)
      else

         ! Change length units
         X(1) = fac*self%position(1)
         X(2) = fac*self%position(2)
         X(3) = fac*self%position(3)
      end if
   end subroutine

   PURE subroutine put_pADP_vector_to(self,X,fac)
   ! Put the pADP vector into vector "X".
   ! If present, include length-conversion factor "fac".
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: X
      REAL, optional, IN :: fac
      REAL :: fac2,fac3,fac4
   ENSURE(size(X)>=no_of_pADPs_(self),"ATOM:put_pADP_vector_to ... wrong size, X")

      ! In atomic units
      if (NOT present(fac)) then

         ! Set from position
         X(1) = self%position(1)
         X(2) = self%position(2)
         X(3) = self%position(3)

         ! Set from ADP_tensor
         X(4) = self%ADP_tensor(1,1)
         X(5) = self%ADP_tensor(2,2)
         X(6) = self%ADP_tensor(3,3)
         X(7) = self%ADP_tensor(1,2)
         X(8) = self%ADP_tensor(1,3)
         X(9) = self%ADP_tensor(2,3)
         if (allocated(self%pADP_vector)) then
            if (size(self%pADP_vector)>=19) then
               X(10:19) = self%pADP_vector(10:19)
            end if
            if (size(self%pADP_vector)>=34) then
               X(20:34) = self%pADP_vector(20:34)
            end if
         end if
      else  ! Change length units

         ! Length scales
         fac2 = fac*fac
         fac3 = fac*fac2
         fac4 = fac*fac3

         ! Set from position
         X(1) = fac*self%position(1)
         X(2) = fac*self%position(2)
         X(3) = fac*self%position(3)

         ! Set from ADP_tensor
         X(4) = fac2*self%ADP_tensor(1,1)
         X(5) = fac2*self%ADP_tensor(2,2)
         X(6) = fac2*self%ADP_tensor(3,3)
         X(7) = fac2*self%ADP_tensor(1,2)
         X(8) = fac2*self%ADP_tensor(1,3)
         X(9) = fac2*self%ADP_tensor(2,3)
         if (allocated(self%pADP_vector)) then
            if (size(self%pADP_vector)>=19) then
               X(10:19) = fac3*self%pADP_vector(10:19)
            end if
            if (size(self%pADP_vector)>=34) then
               X(20:34) = fac4*self%pADP_vector(20:34)
            end if
         end if
      end if
   end subroutine

   PURE subroutine put_pADP2_vector_to(self,X,fac)
   ! Put the pADP2 vector into vector "X".
   ! If present, include length-conversion factor "fac".
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: X
      REAL, optional, IN :: fac
      REAL :: fac2
   ENSURE(size(X)==9,"ATOM:put_pADP2_vector_to ... wrong size, X")

      ! In atomic units
      if (NOT present(fac)) then

         ! Set from position
         X(1) = self%position(1)
         X(2) = self%position(2)
         X(3) = self%position(3)

         ! Set from ADP_tensor
         X(4) = self%ADP_tensor(1,1)
         X(5) = self%ADP_tensor(2,2)
         X(6) = self%ADP_tensor(3,3)
         X(7) = self%ADP_tensor(1,2)
         X(8) = self%ADP_tensor(1,3)
         X(9) = self%ADP_tensor(2,3)
      else  ! Change length units

         ! Length scales
         fac2 = fac*fac

         ! Set from position
         X(1) = fac*self%position(1)
         X(2) = fac*self%position(2)
         X(3) = fac*self%position(3)

         ! Set from ADP_tensor
         X(4) = fac2*self%ADP_tensor(1,1)
         X(5) = fac2*self%ADP_tensor(2,2)
         X(6) = fac2*self%ADP_tensor(3,3)
         X(7) = fac2*self%ADP_tensor(1,2)
         X(8) = fac2*self%ADP_tensor(1,3)
         X(9) = fac2*self%ADP_tensor(2,3)
      end if
   end subroutine

   PURE subroutine put_ADP2_vector_to_1(self,U,fac)
   ! Put the second-order ADPs into vector "U".
   ! If present, include length-conversion factor "fac".
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: U
      REAL, optional, IN :: fac
      REAL :: fac2
   ENSURE(size(U)==6,"ATOM:put_ADP2_vector_to_1 ... wrong size, U")

      ! In atomic units
      if (NOT present(fac)) then

         ! Set from ADP tensor
         U(1) = self%ADP_tensor(1,1)
         U(2) = self%ADP_tensor(2,2)
         U(3) = self%ADP_tensor(3,3)
         U(4) = self%ADP_tensor(1,2)
         U(5) = self%ADP_tensor(1,3)
         U(6) = self%ADP_tensor(2,3)
      else  ! Change length units

         ! Length scales
         fac2 = fac*fac

         ! Set from ADP tensor
         U(1) = fac2*self%ADP_tensor(1,1)
         U(2) = fac2*self%ADP_tensor(2,2)
         U(3) = fac2*self%ADP_tensor(3,3)
         U(4) = fac2*self%ADP_tensor(1,2)
         U(5) = fac2*self%ADP_tensor(1,3)
         U(6) = fac2*self%ADP_tensor(2,3)
      end if
   end subroutine

   PURE subroutine put_ADP3_vector_to_1(self,U,fac)
   ! Put the ADP3s into vector "U".
   ! If present, include length-conversion factor "fac".
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: U
      REAL, optional, IN :: fac
      REAL :: fac2,fac3
   ENSURE(allocated(self%pADP_vector),"ATOM:put_ADP3_vector_to_1 ... no pADPs")
   ENSURE(size(self%pADP_vector)>=19,"ATOM:put_ADP3_vector_to_1 ... no pADP3s")
   ENSURE(size(U)==10,"ATOM:put_ADP3_vector_to_1 ... wrong size, U")

      ! In atomic units
      if (NOT present(fac)) then
         U(1:10) = self%pADP_vector(10:19)
      else  ! Change length units

         ! Length scales
         fac2 = fac*fac
         fac3 = fac*fac2
         U(1:10) = fac3*self%pADP_vector(10:19)
      end if
   end subroutine

   PURE subroutine put_ADP4_vector_to_1(self,U,fac)
   ! Put the ADP4s into vector "U".
   ! If present, include length-conversion factor "fac".
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: U
      REAL, optional, IN :: fac
      REAL :: fac2,fac3,fac4
   ENSURE(allocated(self%pADP_vector),"ATOM:put_ADP4_vector_to_1 ... no pADPs")
   ENSURE(size(self%pADP_vector)>=34,"ATOM:put_ADP4_vector_to_1 ... no pADP3s")
   ENSURE(size(U)==15,"ATOM:put_ADP4_vector_to_1 ... wrong size, U")

      ! In atomic units
      if (NOT present(fac)) then
         U(1:15) = self%pADP_vector(20:34)
      else  ! Change length units

         ! Length scales
         fac2 = fac*fac
         fac3 = fac*fac2
         fac4 = fac*fac3
         U(1:15) = fac4*self%pADP_vector(20:34)
      end if
   end subroutine


! Put errors

   PURE subroutine put_pos_errors_to(self,dX,fac)
   ! Put the position errors into vector "dX".
   ! If present, include length conversion factor "fac".
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: dX
      REAL, optional, IN :: fac
   ENSURE(size(dX)==3,"ATOM:put_pos_errors_to ... wrong size, dX")
      dX = ZERO

      ! Return if there are no errors
      if (NOT allocated(self%pADP_errors)) return

      ! In atomic units
      if (NOT present(fac)) then

         ! Copy all errors
         dX(1:3) = self%pADP_errors(1:3)
      else  ! Change length units

         ! Copy all errors
         dX(1:3) = fac*self%pADP_errors(1:3)
      end if
   end subroutine

   PURE subroutine put_pADP_errors_to(self,dX,fac)
   ! Put the pADP errors into vector "dX".
   ! If present, include length conversion factor "fac".
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: dX
      REAL, optional, IN :: fac
      REAL :: fac2,fac3,fac4
   ENSURE(allocated(self%pADP_errors),"ATOM:put_pADP_errors_to ... no pADP_errors")
   ENSURE(size(self%pADP_errors)==size(dX),"ATOM:put_pADP_errors_to ... wrong size, dX")

      ! In atomic units
      if (NOT present(fac)) then

         ! Copy all errors
         dX = self%pADP_errors
      else  ! Change length units

         ! Length scales
         fac2 = fac*fac
         fac3 = fac*fac2
         fac4 = fac*fac3

         ! Copy all errors
         dX = fac*self%pADP_errors
      end if
   end subroutine

   PURE subroutine put_pADP2_errors_to(self,dX,fac)
   ! Put the pADP2 errors into vector "dX".
   ! If present, include length conversion factor "fac".
