      VEC(REAL,:), OUT :: dX
      REAL, optional, IN :: fac
      REAL :: fac2
   ENSURE(allocated(self%pADP_errors),"ATOM:put_pADP2_errors_to ... no pADP_errors")
   ENSURE(size(self%pADP_errors)>=9,"ATOM:put_pADP2_errors_to ... wrong size, pADP_errors")
   ENSURE(size(dX)==9,"ATOM:put_pADP2_errors_to ... wrong size, dX")

      ! In atomic units
      if (NOT present(fac)) then

         ! Copy all errors
         dX(1:3) = self%pADP_errors(1:3)
         dX(4:9) = self%pADP_errors(4:9)
      else  ! Change length units

         ! Length scales
         fac2 = fac*fac

         ! Copy all errors
         dX(1:3) = fac*self%pADP_errors(1:3)
         dX(4:9) = fac2*self%pADP_errors(4:9)
      end if
   end subroutine

