! Transform

   PURE subroutine transform_pADP_vector_with(self,R)
   ! Transform the pADP vector, using the rotation matrix "R".
   ! e.g. transformed = R . pos
   ! NOTE: this works even if pADP_vector is *not* created,
   ! then it works on the positions and ADPs.
      type(ATOM_TYPE), INOUT :: self
      MAT(REAL,3,3), IN :: R
      MAT(REAL,:,:), allocatable :: W
      VEC(REAL,:), allocatable :: X,U

      ! Create
      call create_(X,no_of_pADPs_(self))

      ! Transform position
      if (allocated(self%pADP_vector)) then
         ENSURE(equals_(self%pADP_vector(1:3),self%position),"ATOM:transform_pADP_vector_with ... pADP_vector /= position")
      end if
      call to_product_of_(X(1:3),R,self%position)

      ! Transform ADP's
      call create_(W,6,6)
      call symmetric_tensor_2_product_mx_(W,R)
      call create_(U,6)
      call put_ADP2_vector_to_(self,U)
      call to_product_of_(X(4:9),W,U)
      call destroy_(U)
      call destroy_(W)

      ! Transform ADP3's
      if (allocated(self%pADP_vector)) then
         if (size(self%pADP_vector)>=19) then
            call create_(W,10,10)
            call symmetric_tensor_3_product_mx_(W,R)
            call to_product_of_(X(10:19),W,self%pADP_vector(10:19))
            call destroy_(W)
         end if
      end if

      ! Transform ADP4's
      if (allocated(self%pADP_vector)) then
         if (size(self%pADP_vector)>=34) then
            call create_(W,15,15)
            call symmetric_tensor_4_product_mx_(W,R)
            call to_product_of_(X(20:34),W,self%pADP_vector(20:34))
            call destroy_(W)
         end if
      end if

      ! Set pADPs & U_iso and M2_aniso
      call set_pADP_vector_to_(self,X)

      ! Clean
      call destroy_(X)
   end subroutine


!  ===============
!  Set atom groups
!  ===============

   PURE subroutine set_isotropic_ADP(self)
   ! Set the ADP to be isotropic.
      type(ATOM_TYPE), INOUT :: self
      REAL :: val
      MAT(REAL,3,3) :: ADP
   ENSURE(self%ADP_axis_system=="cartesian","ATOM:set_isotropic_ADP ... not cartesian axis system")

      ! The averaged trace
      val = THIRD*(self%ADP_tensor(1,1)+self%ADP_tensor(2,2)+self%ADP_tensor(3,3))

      ! Make it isotropic
      ADP(1,1) = val
      ADP(2,2) = val
      ADP(3,3) = val
      ADP(1,2) = ZERO
      ADP(2,1) = ZERO
      ADP(1,3) = ZERO
      ADP(3,1) = ZERO
      ADP(2,3) = ZERO
      ADP(3,2) = ZERO
      call set_ADP_tensor_(self,ADP(:,:))

      ! Now set the errors
      if (allocated(self%pADP_errors)) then

         ! The averaged trace of errors
         val = THIRD*(self%pADP_errors(4)+self%pADP_errors(5)+self%pADP_errors(6))
      else

         ! Use this as last resort
         val = self%U_iso_error
      end if

      ! Make isotropic error
      self%pADP_errors(4) = val
      self%pADP_errors(5) = val
      self%pADP_errors(6) = val
      self%pADP_errors(7) = ZERO
      self%pADP_errors(8) = ZERO
      self%pADP_errors(9) = ZERO
   end subroutine

