   subroutine set_covalent_radii_ccdc()
   ! Set the the covalent radii for a given atomic number.
      INT :: an
      REAL :: new_radius
      call read_(stdin,an)
      ENSURE(an>0 AND an<111,"ATOM:set_covalent_radii_ccdc ... atomic number out of range")
      call read_quantity_(stdin,new_radius)
      covalent_radii_ccdc(an) = new_radius*ANGSTROM_PER_BOHR
   end subroutine

   subroutine set_vdw_radii_ccdc()
   ! Set the the VDW radii for a given atomic number.
