   recursive subroutine read_keywords(self)
   ! Read data from "stdin" using keyword style input.
      type(ATOM_TYPE), INOUT :: self
      STR(len=STR_SIZE) :: word
   ENSURE(next_item_(stdin)=="{","ATOM:read_keywords ... expecting open bracket symbol, {")

      ! Read the open braces {

      ! The following code is inherited from OBJECT
      call read_(stdin,word)

      ! Echo keyword if requested
      if (tonto%keyword_echo) then
         call flush_(stdout)
         call text_(stdout,"keyword found --> "//trim(word))
      end if
      do  ! Loop over input keywords

         ! Read the keyword
         call read_(stdin,word)
         DIE_IF(reverted_(stdin),"ATOM:read_keywords ... unexpected end of file while reading list keywords")
         call to_lower_case_(word)

         ! Append any lonely = sign
         if (NOT exhausted_(stdin%buffer)) then
            if (next_item_(stdin)=="=") then
               call skip_next_item_(stdin)
               word = trim(word)//"="
            end if
         end if

         ! Echo keyword if requested
         if (tonto%keyword_echo) then
            call flush_(stdout)
            call text_(stdout,"keyword found --> "//trim(word))
         end if

         ! Exit if keyword is closing brace }
         if (word=="}") exit

         ! Process the keyword 
         call process_keyword_(self,word)
      end do
   end subroutine

   subroutine process_keyword(self,keyword)
   ! Process command "keyword". Any required data needed by the
   ! "keyword" is inputted from "stdin".
      type(ATOM_TYPE), INOUT :: self
      STR(len=*), IN :: keyword
      STR(len=STR_SIZE) :: word
      word = keyword
      call to_lower_case_(word)
      select case (word)
      case ("}                            ")  ! exit case
      case ("adp_axis_system=             "); call read_ADP_axis_system_(self)
      case ("adp_tensor=                  "); call read_ADP_tensor_(self)
      case ("adp2_tensor=                 "); call read_ADP_tensor_(self)
      case ("adp3_tensor=                 "); call read_ADP3_tensor_(self)
      case ("adp4_tensor=                 "); call read_ADP4_tensor_(self)
      case ("axis_system=                 "); call read_axis_system_(self)
      case ("basis_label=                 "); call read_basis_label_(self)
      case ("b_eq=                        "); call read_B_iso_(self)
      case ("b_iso=                       "); call read_B_iso_(self)
      case ("charge=                      "); call read_charge_(self)
      case ("coppensbasis_label=          "); call read_coppensbasis_label_(self)
      case ("dipole=                      "); call read_dipole_(self)
      case ("dispersion_coefficients=     "); call read_dispersion_coefficients_
      case ("f_i=                         "); call read_f_i_(self)
      case ("f_r=                         "); call read_f_r_(self)
      case ("group=                       "); call read_group_(self)
      case ("junk=                        "); call read_junk_(self)
      case ("label=                       "); call read_label_(self)
      case ("mass_number=                 "); call read_mass_number_(self)
      case ("mm_atom_type=                "); call read_mm_atom_type_(self)
      case ("mm_charge=                   "); call read_mm_charge_(self)
      case ("mm_forcefield_name=          "); call read_mm_forcefield_name_(self)
      case ("nuclear_charge=              "); call read_nuclear_charge_(self)
      case ("oxidation_state=             "); call read_oxidation_state_(self)
   ! case ("pdb_input_line=              "); .read_pdb_input_line
      case ("pos=                         "); call read_position_(self)  ! deprecated
      case ("position=                    "); call read_position_(self)
      case ("put                          "); call put_(self)
      case ("put_interpolator             "); call put_interpolator_(self)
      case ("restraining_position=        "); call read_restraining_position_(self)
      case ("restraining_force_constant=  "); call read_restraining_force_(self)
   ! case ("residue_sequence_number=     "); .read_residue_sequence_number
      case ("set_covalent_radii_ccdc      "); call set_covalent_radii_ccdc
      case ("set_vdw_radii_ccdc           "); call set_vdw_radii_ccdc
      case ("site_disorder_group=         "); call read_site_disorder_group_(self)
      case ("site_occupancy=              "); call read_site_occupancy_(self)
      case ("slaterbasis_label=           "); call read_slaterbasis_label_(self)
      case ("thermal_axis_system=         "); call read_ADP_axis_system_(self)  ! deprecated
      case ("thermal_tensor=              "); call read_ADP_tensor_(self)  ! deprecated
      case ("u_eq=                        "); call read_U_iso_(self)
      case ("u_iso=                       "); call read_U_iso_(self)
      case ("u_tensor=                    "); call read_ADP_tensor_(self)
      case ("u2_tensor=                   "); call read_ADP_tensor_(self)
      case ("u3_tensor=                   "); call read_ADP3_tensor_(self)
      case ("u4_tensor=                   "); call read_ADP4_tensor_(self)
      case ("units=                       "); call read_units_(self)
      case default; allocate(tonto%known_keywords(45))
      tonto%known_keywords(1) = "}                            "
      tonto%known_keywords(2) = "adp_axis_system=             "
      tonto%known_keywords(3) = "adp_tensor=                  "
      tonto%known_keywords(4) = "adp2_tensor=                 "
      tonto%known_keywords(5) = "adp3_tensor=                 "
      tonto%known_keywords(6) = "adp4_tensor=                 "
      tonto%known_keywords(7) = "axis_system=                 "
      tonto%known_keywords(8) = "basis_label=                 "
      tonto%known_keywords(9) = "b_eq=                        "
      tonto%known_keywords(10) = "b_iso=                       "
      tonto%known_keywords(11) = "charge=                      "
      tonto%known_keywords(12) = "coppensbasis_label=          "
      tonto%known_keywords(13) = "dipole=                      "
      tonto%known_keywords(14) = "dispersion_coefficients=     "
      tonto%known_keywords(15) = "f_i=                         "
      tonto%known_keywords(16) = "f_r=                         "
      tonto%known_keywords(17) = "group=                       "
      tonto%known_keywords(18) = "junk=                        "
      tonto%known_keywords(19) = "label=                       "
      tonto%known_keywords(20) = "mass_number=                 "
      tonto%known_keywords(21) = "mm_atom_type=                "
      tonto%known_keywords(22) = "mm_charge=                   "
      tonto%known_keywords(23) = "mm_forcefield_name=          "
      tonto%known_keywords(24) = "nuclear_charge=              "
      tonto%known_keywords(25) = "oxidation_state=             "
      tonto%known_keywords(26) = "pos=                         "
      tonto%known_keywords(27) = "position=                    "
      tonto%known_keywords(28) = "put                          "
      tonto%known_keywords(29) = "put_interpolator             "
      tonto%known_keywords(30) = "restraining_position=        "
      tonto%known_keywords(31) = "restraining_force_constant=  "
      tonto%known_keywords(32) = "set_covalent_radii_ccdc      "
      tonto%known_keywords(33) = "set_vdw_radii_ccdc           "
      tonto%known_keywords(34) = "site_disorder_group=         "
      tonto%known_keywords(35) = "site_occupancy=              "
      tonto%known_keywords(36) = "slaterbasis_label=           "
      tonto%known_keywords(37) = "thermal_axis_system=         "
      tonto%known_keywords(38) = "thermal_tensor=              "
      tonto%known_keywords(39) = "u_eq=                        "
      tonto%known_keywords(40) = "u_iso=                       "
      tonto%known_keywords(41) = "u_tensor=                    "
      tonto%known_keywords(42) = "u2_tensor=                   "
      tonto%known_keywords(43) = "u3_tensor=                   "
      tonto%known_keywords(44) = "u4_tensor=                   "
      tonto%known_keywords(45) = "units=                       "
      call unknown_(tonto,word,"ATOM:process_keyword")
      deallocate(tonto%known_keywords)
      end select
   end subroutine

