   end subroutine

   subroutine read_slaterbasis_label(self)
   ! Read the slater basis set label from "stdin" which will be used
   ! to match a basis set to ... the element symbol may be prepended
      type(ATOM_TYPE), INOUT :: self
      call read_(stdin,self%slaterbasis_label)

      ! If no element symbol, prepend it
      if (does_not_include_(self%basis_label,':')) then
         self%basis_label = trim(generic_chemical_symbol_(self))//':'//trim(self%basis_label)
      end if
   end subroutine

   subroutine read_coppensbasis_label(self)
   ! Read the Coppens basis set label from "stdin" which will be used to match a
   ! basis set to ... (in fact there is only one coppens basis type)
      type(ATOM_TYPE), INOUT :: self
      call read_(stdin,self%coppensbasis_label)

      ! If no element symbol, prepend it
      if (does_not_include_(self%basis_label,':')) then
         self%basis_label = trim(generic_chemical_symbol_(self))//':'//trim(self%basis_label)
      end if
   end subroutine

   subroutine read_U_iso(self)
   ! Read the isotropic thermal parameters from "stdin".  NOTE: units are
   ! Bohr^2, not Angstrom^2.
      type(ATOM_TYPE), INOUT :: self
      call read_quantity_(stdin,self%U_iso)
   end subroutine

   subroutine read_B_iso(self)
   ! Read the isotropic B factor.NOTE: units are Bohr^2, not Angstrom^2.
      type(ATOM_TYPE), INOUT :: self
      REAL :: B_iso

      ! Read
      call read_quantity_(stdin,B_iso)

      ! Set
      self%U_iso = B_iso/(EIGHT*PI*PI)
   end subroutine

   subroutine read_ADP_tensor(self)
   ! Read the ADP (thermal) from "stdin". These are assumed to be in the
   ! cartesian axis system, and in bohr^2.  The expansion of the thermal
   ! smearing temperature factor term is:
   !              TF = exp ( -2\pi^2 U_{ij} h_i h_j a^*_i a^*_j )
   ! where (h) are the miller indices and (a^*) are the reciprocal lattice
   ! constants in angstrom^{-2}.
   ! NOTE: The pADP_vector/pADP_errors are set also.
      type(ATOM_TYPE), INOUT :: self
      VEC(REAL,6) :: ADP

      ! Read elements in lexical order
      call read_quantity_(stdin,ADP)

      ! Set the tensor
      call reset_pADPs_and_errors_(self,9)
      call set_ADP_tensor_(self,ADP)
   end subroutine

   subroutine read_ADP3_tensor(self)
   ! Read the third-order ADP (thermal) tensor, assumed to be in the
   ! cartesian axis system, and in bohr^2. The interpretation of these
   ! coefficients as Gram-Charlier, Edgeworth, cumulants or other is
   ! not specified.
      type(ATOM_TYPE), INOUT :: self
      VEC(REAL,10) :: tensor

      ! Read elements in lexical order
      call read_quantity_(stdin,tensor)

      ! Set the tensor
      call reset_pADPs_and_errors_(self,19)
      call set_ADP3_vector_to_(self,tensor)
   end subroutine

   subroutine read_ADP4_tensor(self)
   ! Read the fourth-order ADP (thermal) tensor, assumed to be in the
   ! cartesian axis system, and in bohr^2. The interpretation of these
   ! coefficients as Gram-Charlier, Edgeworth, cumulants or other is
   ! not specified.
      type(ATOM_TYPE), INOUT :: self
      VEC(REAL,15) :: tensor

      ! Read elements in lexical order
      call read_quantity_(stdin,tensor)

      ! Set the tensor
      call reset_pADPs_and_errors_(self,34)
      call set_ADP4_vector_to_(self,tensor)
   end subroutine


!  ====================
!  Key related routines
!  ====================

   subroutine read_keys(self)
   ! Read the "keys".
      type(ATOM_TYPE), INOUT :: self

      ! The following code is inherited from OBJECT
      if (FALSE) self = self
      call destroy_(keys)
      call read_all_(stdin,keys)
   end subroutine

   subroutine process_keys(self)
   ! Process each of the words in the "keys" list.
      type(ATOM_TYPE), INOUT :: self
      INT :: k,l,n_key
      STR(len=STR_SIZE) :: keyword
      BIN :: keyword_echo
   ENSURE(allocated(keys),"ATOM:process_keys ... no keys")

      ! The number of keys

      ! The following code is inherited from OBJECT
      n_key = size(keys)

      ! Keyword counter
      k = 0
      do  ! Loop over keywords in "keys"

         ! Get the next keyword
         k = k+1
         keyword = keys(k)

         ! Exit if close brace
         if (keyword=="}") exit
         if (keyword=="{") then  ! embedded keyword

            ! Turn off keyword echo
            keyword_echo = tonto%keyword_echo
            call set_keyword_echo_(tonto,FALSE)

            ! Find closing brace of embedded section
            l = index_of_matching_bracket_(keys(k:),"{")
            DIE_IF(l==0,"ATOM:process_keys ... no matching closing brace in embedded keyword")

            ! Process internalized keywords
            call redirect_(stdin,keys(k:k+l-1))
            call read_keywords_(self)
            call revert_(stdin)

            ! Reset key counter
            k = k+l-1

            ! Reset keyword echo
            call set_keyword_echo_(tonto,keyword_echo)
         else  ! plain-old keyword

            ! Process plain-old keyword
            call process_keyword_(self,keyword)
         end if

         ! Exit if no keys left
         if (k==n_key) exit
      end do
   end subroutine

   function keys_created(self) result (res)
   ! Return TRUE if the list-element keys are created.
      type(ATOM_TYPE), INOUT :: self
      BIN :: res

      ! The following code is inherited from OBJECT
      if (FALSE) self = self
      res = allocated(keys)
      if (res) res = size(keys)>0
   end function

   subroutine set_keys(self,the_keys)
   ! This is for setting the "keys" externally.
      type(ATOM_TYPE), INOUT :: self
      VEC(STR(len=*),:), IN :: the_keys

      ! The following code is inherited from OBJECT
      if (FALSE) self = self
      keys = the_keys
   end subroutine

   subroutine clear_keys(self)
   ! This is for destroying the "keys" externally.
      type(ATOM_TYPE), INOUT :: self

      ! The following code is inherited from OBJECT
      if (FALSE) self = self
      call destroy_(keys)
      call create_(keys,0)
   end subroutine


!  ===================
!  Axis change methods
!  ===================

   PURE subroutine change_axis_system_to(self,axis_system,cell)
   ! Change the axis system for the position *and* ADP tensors to "axis_system",
   ! either "crystal" or "cartesian". "cell" holds the unit cell axis system
   ! information. Specify the "form" for the anharmonic ADPs.
   ! NOTE: Errors are *not* transformed since that needs covariances.
   !       The errors must be transformed outside this routine.
      type(ATOM_TYPE), INOUT :: self
      STR(len=*), IN :: axis_system
      type(UNIT_CELL_TYPE), IN :: cell
   ! H_U_iso :: BIN, IN
      call change_pos_axis_system_to_(self,axis_system,cell)
      call change_ADP2_axis_system_to_(self,axis_system,cell)
      call change_ADPn_axis_system_to_v2_(self,axis_system,cell)
   end subroutine

   PURE subroutine change_axis_for_xtal23_system_to(self,axis_system,cell)
   ! Change the axis system for the position *and* ADP tensors to "axis_system",
   ! either "crystal" or "cartesian". "cell" holds the unit cell axis system
   ! information. Specify the "form" for the anharmonic ADPs.
   ! NOTE: Errors are *not* transformed since that needs covariances.
   !       The errors must be transformed outside this routine.
      type(ATOM_TYPE), INOUT :: self
      STR(len=*), IN :: axis_system
      type(UNIT_CELL_TYPE), IN :: cell
   ! H_U_iso :: BIN, IN
      call change_pos_axis_for_xtal23_system_to_(self,axis_system,cell)
      call change_ADP2_axis_system_to_(self,axis_system,cell)
      call change_ADPn_axis_system_to_v2_(self,axis_system,cell)
   end subroutine

   PURE subroutine change_pos_axis_system_to(self,axis_system,cell)
   ! Change atom positions to a new "axis_system".
      type(ATOM_TYPE), INOUT :: self
      STR(len=*), IN :: axis_system
      type(UNIT_CELL_TYPE), IN :: cell
      VEC(REAL,3) :: pos
   ENSURE(is_one_of_(axis_system,["cartesian","crystal  "]),"ATOM:change_pos_axis_system_to ... unknown axis system!")
      select case (axis_system)

      case ("cartesian")
         if (self%pos_axis_system=="cartesian") return

!        pos.to_product_of(cell.direct_mx,.position*ANGSTROM_PER_BOHR)
         call to_product_of_(pos,cell%direct_mx,self%position)
         call set_position_(self,pos)
         self%pos_axis_system = "cartesian"

      case ("crystal  ")
         if (self%pos_axis_system=="crystal") return

!        pos.to_product_of(cell.inverse_mx,.position*BOHR_PER_ANGSTROM)
         call to_product_of_(pos,cell%inverse_mx,self%position)
         call set_position_(self,pos)
         self%pos_axis_system = "crystal"
      end select
   end subroutine

   PURE subroutine change_pos_axis_for_xtal23_system_to(self,axis_system,cell)
   ! Change atom positions to a new "axis_system".
      type(ATOM_TYPE), INOUT :: self
      STR(len=*), IN :: axis_system
      type(UNIT_CELL_TYPE), IN :: cell
      VEC(REAL,3) :: pos
   ENSURE(is_one_of_(axis_system,["cartesian","crystal  "]),"ATOM:change_pos_axis_for_xtal23_system_to ... unknown axis system!")
      select case (axis_system)

      case ("cartesian")
         if (self%pos_axis_system=="cartesian") return
         call to_product_of_(pos,cell%direct_mx,self%position*ANGSTROM_PER_BOHR)
!        pos.to_product_of(cell.direct_mx,.position)
         call set_position_(self,pos)
         self%pos_axis_system = "cartesian"

      case ("crystal  ")
         if (self%pos_axis_system=="crystal") return
         call to_product_of_(pos,cell%inverse_mx,self%position*BOHR_PER_ANGSTROM)
!        pos.to_product_of(cell.inverse_mx,.position)
         call set_position_(self,pos)
         self%pos_axis_system = "crystal"
      end select
   end subroutine

   PURE subroutine change_ADP_axis_system_to(self,axis_system,cell)
   ! Change *all* ADP tensor to the desired "axis_system". The axes
   ! are described by the unit "cell". 
      type(ATOM_TYPE), INOUT :: self
      STR(len=*), IN :: axis_system
      type(UNIT_CELL_TYPE), IN :: cell
      call change_ADP2_axis_system_to_(self,axis_system,cell)
      call change_ADPn_axis_system_to_v2_(self,axis_system,cell)
   end subroutine

   PURE subroutine change_ADP2_axis_system_to(self,axis_system,cell)
   ! Change ADP2/s axis system into the "axis_system" frame.
   ! NOTE: the ESDs are NOT transformed, and must not be. The congruence
   ! U' = M U M^T makes every U'_ij a combination of all six U_kl, so the
   ! variance of U'_ij needs the full 6x6 covariance. Running the
   ! congruence over the sigmas instead forms signed combinations of
   ! standard deviations, which understates them, can overstate them, and
   ! can even come out negative. The ESDs stay in the frame they were made
   ! in; a writer emits them only into that frame. See TASKS_AND_HISTORY.md.
      type(ATOM_TYPE), INOUT :: self
      STR(len=*), IN :: axis_system
      type(UNIT_CELL_TYPE), IN :: cell
   ! H_U_iso :: BIN, IN
      MAT(REAL,3,3) :: ADP
      BIN :: chk
      REAL :: val
   ENSURE(is_one_of_(axis_system,["cartesian","crystal  "]),"ATOM:change_ADP2_axis_system_to ... unknown axis system!")
      chk = FALSE
      select case (axis_system)

      case ("cartesian")

         ! Convert U_iso to an ADP and use it if necessary
         if (self%U_iso>ZERO) then

            ! Change U_iso!
            if (is_zero_(self%ADP_tensor)) then

               ! Note: U_iso/U_eq is always in cartesian system
               ! Change ADP to crystal axis system
               call to_unit_mx_(ADP)
               ADP = ADP*self%U_iso
               call change_basis_using_(ADP,cell%reciprocal_U_mx)
               call set_ADP_tensor_(self,ADP)
            else

               ! ADP exists already
               ! Check U_iso later ...
               chk = TRUE
            end if
         end if
         if (self%ADP_axis_system=="cartesian") return

         ! Change to cartesians !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
         call change_basis_to_(self%ADP_tensor,ADP,cell%direct_U_mx)

         ! Set axis system *before* U_iso is set
         self%ADP_axis_system = "cartesian"

         ! Now U_iso *is* set as a trace
         call set_ADP_tensor_(self,ADP)

         ! Change errors?
         ! Set U_iso from trace of tensor.
         ! Could also check if supplied U_iso was correct
         if (chk) then
            val = THIRD*trace_(self%ADP_tensor)
            call set_U_iso_(self,val)
         end if

      case ("crystal")
         if (self%ADP_axis_system=="crystal") return
         call change_basis_to_(self%ADP_tensor,ADP,cell%reciprocal_U_mx)

         ! Set axis system *before* U_iso is set
         self%ADP_axis_system = "crystal"

         ! Now U_iso is not set as a trace
         call set_ADP_tensor_(self,ADP)
      end select
   end subroutine

   PURE subroutine change_ADPn_axis_system_to_v2(self,axis_system,cell)
   ! Change ADPn vector to the "axis_system" frame.
   ! NOTE: Unlike the ADP2's, in the "crystal" axis_system these are
   ! reported in dimensionless Gram-Charlier "g" form. For
   ! consistency, we also produce them in dimensioned "u" form
   ! which have reciprocal lengths in them like the IUCr ADPs
   ! in the crystal axis system.  However, internally, and during the
   ! refinement, the axis_system is always "cartesian" and Bohr units.
      type(ATOM_TYPE), INOUT :: self
      STR(len=*), IN :: axis_system
      type(UNIT_CELL_TYPE), IN :: cell
      MAT3(REAL,3,3,3) :: adp3,new3
      MAT4(REAL,3,3,3,3) :: adp4,new4
   ENSURE(is_one_of_(axis_system,["cartesian","crystal  "]),"ATOM:change_ADPn_axis_system_to_v2 ... unknown axis system!")
      select case (axis_system)

      case ("cartesian")  ! Change INTO cartesian FROM crystal
         if (self%ADPn_axis_system=="cartesian") return
         self%ADPn_axis_system = "cartesian"
         if (NOT has_ADP3s_(self)) return
         call put_ADP3_vector_to_(self,adp3)
         call back_transform_to_(adp3,new3,cell%direct_mx)
         call set_ADP3_vector_to_(self,new3)
         if (NOT has_ADP4s_(self)) return
         call put_ADP4_vector_to_(self,adp4)
         call back_transform_to_(adp4,new4,cell%direct_mx)
         call set_ADP4_vector_to_(self,new4)

      case ("crystal")  ! Change INTO crystal FROM cartesian
         if (self%ADPn_axis_system=="crystal") return
         self%ADPn_axis_system = "crystal"
         if (NOT has_ADP3s_(self)) return
         call put_ADP3_vector_to_(self,adp3)
         call change_basis_to_(adp3,new3,cell%reciprocal_mx)
         call set_ADP3_vector_to_(self,new3)
         if (NOT has_ADP4s_(self)) return
         call put_ADP4_vector_to_(self,adp4)
         call change_basis_to_(adp4,new4,cell%reciprocal_mx)
         call set_ADP4_vector_to_(self,new4)
      end select
   end subroutine

   PURE subroutine change_coordinate_axes(self,axes)
   ! Change the coordiantes and ADP (thermal) tensors to be expressed
   ! in terms of a new set of orthogonal "axes". We must be n the
   ! cartesian axis system.
      type(ATOM_TYPE), INOUT :: self
      MAT(REAL,3,3), IN :: axes
      VEC(REAL,3) :: pos
      MAT(REAL,3,3) :: ADP
   ENSURE(self%pos_axis_system=="cartesian","ATOM:change_coordinate_axes ... positions must be in cartesian axis system")
   ENSURE(self%ADP_axis_system=="cartesian","ATOM:change_coordinate_axes ... U's must be in cartesian axis system")
   ENSURE(NOT has_ADP3s_(self),"ATOM:change_coordinate_axes ... does not work for U3's yet")
   ENSURE(NOT has_ADP4s_(self),"ATOM:change_coordinate_axes ... does not work for U4's yet")
      call to_product_of_(pos,axes,self%position)
      call set_position_(self,pos)

      ! WARNING: this may not be correct
      call change_basis_to_(self%ADP_tensor,ADP,axes)
      call set_ADP_tensor_(self,ADP)
   end subroutine

!  ========================
!  Basis resolution methods
!  ========================

   PURE subroutine resolve_basis_0(self,basis,suffix,found)
   ! Resolve the BASIS from the list of them in "basis"
   ! . First, if "suffix" is present and not blank, generate a
   !   library basis label by concatenating the element symbol with
   !   the "suffix" e.g. "Mg:STO-3G"
   ! . If that fails, try to match any existing basis label with one
   !   of the labels from "basis" e.g. if the user entered their own
   !   basis with user-defined labels
   ! . If that fails, try to matching using only the chemical symbol
   !   e.g. if the basis was obtained from reading an external
   !   program, like gaussian.
      type(ATOM_TYPE), INOUT :: self
      VEC(type(BASIS_TYPE),:), allocatable, IN :: basis
      STR(len=*), optional, IN :: suffix
      BIN, optional, OUT :: found
      STR(len=STR_SIZE) :: library_label,symbol
      BIN :: fnd
   ENSURE(allocated(basis),"ATOM:resolve_basis_0 ... no basis")

      ! The following code is inherited from ATOM
      fnd = FALSE

      ! First, try matching the basis from the "suffix"
      ! e.g. like "Mg:STO-3G"
      if (present(suffix)) then
         if (suffix/=" ") then

         ! This makes "Mg:STO-3G"
            library_label = library_basis_label_(self,suffix)

         ! Assign into "basis"
            call resolve_by_label_(self%basis,library_label,basis,clobber=TRUE,found=fnd)

         ! Set the basis label
            if (fnd) self%basis_label = library_label
         end if
      end if

      ! Next, try matching the basis to an existing label, if there ...
      if (NOT fnd AND self%basis_label/=" ") then
         call resolve_by_label_(self%basis,self%basis_label,basis,clobber=TRUE,found=fnd)
      end if

      ! Last chance: try (minimal) matching using only the chemical symbol ...
      if (NOT fnd) then
         symbol = trim(generic_chemical_symbol_(self))//":"

         ! Pointer assign into "basis"
         call resolve_by_label_(self%basis,symbol,basis,clobber=TRUE,minmatch=TRUE,found=fnd)

         ! Set the basis label
         if (fnd) self%basis_label = self%basis%label
      end if
      if (present(found)) found = fnd
   end subroutine

   PURE subroutine resolve_basis_1(self,basis,suffix,found)
