!  =========================
!  Atom-kind inquiry methods
!  =========================

   elemental function has_a_dummy_label(self) result (res)
   ! Return TRUE if this has a dummy charge label (charged or not,
   ! with basis set or not)
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = self%label==ATOM_DUMMY_CHARGE_LABEL
   end function

   elemental function is_a_dummy_atom(self) result (res)
   ! Return TRUE if this is a dummy atom (no charge, no basis)
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = has_a_dummy_label_(self) AND self%nuclear_charge==ZERO AND NOT allocated(self%basis)
   end function

   elemental function is_a_nondummy_atom(self) result (res)
   ! Return TRUE if this is a *not* dummy atom
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = NOT has_a_dummy_label_(self) OR self%nuclear_charge/=ZERO OR allocated(self%basis)
   end function

   elemental function is_a_ghost_atom(self) result (res)
   ! Return TRUE if this is a ghost atom
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = has_a_dummy_label_(self) AND self%nuclear_charge==ZERO AND has_basis_(self)
   end function

   elemental function is_a_point_charge(self) result (res)
   ! Return TRUE if this is a point-charge (no basis set)
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = has_a_dummy_label_(self) AND self%nuclear_charge>ZERO AND NOT allocated(self%basis)
   end function

   elemental function is_a_pseudo_atom(self) result (res)
   ! Return TRUE if this is a pseudo atom without integral charge
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = has_a_dummy_label_(self) AND NOT is_int_(self%nuclear_charge) AND has_basis_(self)
   end function

   pure function is_same_kind_as(self,atom) result (res)
   ! Return TRUE if self is the same kind of atom as "atom". The
   ! position and label are not compared since the same kind of atom
   ! can have a different position and label.  To check if the basis
   ! set is the same, only the label is used.
      type(ATOM_TYPE), IN :: self
      type(ATOM_TYPE), IN :: atom
      BIN :: res
      BIN :: bases_created,coppens_created,slater_created
      BIN :: bases_destroyed,coppens_destroyed,slater_destroyed
      BIN :: mixed

      ! Which kind of bases created?
      bases_created = allocated(self%basis) AND allocated(atom%basis)
      coppens_created = allocated(self%coppensbasis) AND allocated(atom%coppensbasis)
      slater_created = allocated(self%slaterbasis) AND allocated(atom%slaterbasis)

      ! Which kind of bases destroyed?
      bases_destroyed = NOT allocated(self%basis) AND NOT allocated(atom%basis)
      coppens_destroyed = NOT allocated(self%coppensbasis) AND NOT allocated(atom%coppensbasis)
      slater_destroyed = NOT allocated(self%slaterbasis) AND NOT allocated(atom%slaterbasis)

      ! Mixed bases?
      mixed = NOT (bases_created OR bases_destroyed) OR NOT (coppens_created OR coppens_destroyed) OR NOT (slater_created OR slater_destroyed)

      ! Set same kind
      if (mixed) then
         res = FALSE
      else

         ! Set here ...
         res = self%atomic_number==atom%atomic_number
         if (bases_created) res = res AND self%basis%label==atom%basis%label
         if (coppens_created) res = res AND self%coppensbasis%label==atom%coppensbasis%label
         if (slater_created) res = res AND self%slaterbasis%label==atom%slaterbasis%label
      end if
   end function

   elemental function is_xtal_identical_to(self,atom) result (res)
   ! Return true if self and "atom" are crystallographically i.e.
   ! identical based on occupancy and atomic number *and* position.
      type(ATOM_TYPE), IN :: self
      type(ATOM_TYPE), IN :: atom
      BIN :: res
      res = is_xtal_identical_kind_to_(self,atom) AND equals_(self%position,atom%position)
   end function

   elemental function is_xtal_identical_kind_to(self,atom) result (res)
   ! Return true if self and "atom" are crystallographically
   ! identical based on occupancy and atomic number
      type(ATOM_TYPE), IN :: self
      type(ATOM_TYPE), IN :: atom
      BIN :: res
      res = self%atomic_number==atom%atomic_number
      res = res AND self%site_disorder_group==atom%site_disorder_group
      res = res AND equals_(self%site_occupancy,atom%site_occupancy)
   end function

   elemental function is_in_cartesian_system(self) result (res)
   ! Return TRUE if the axis system is cartesian
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = self%pos_axis_system=="cartesian" AND self%ADP_axis_system=="cartesian"
   end function


!  =====================
!  Basis inquiry methods
!  =====================

   elemental function has_shell_info(self) result (res)
   ! Return TRUE if the shell info is made
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = allocated(self%first_basis_fn_for_shell) AND allocated(self%last_basis_fn_for_shell) AND allocated(self%angular_moment_for_shell) AND allocated(self%basis_shell1pair)
   end function

   elemental function has_basis(self) result (res)
   ! Return TRUE if this is a pseudo atom without integral charge
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = allocated(self%basis) AND is_resolved_(self%basis)
   end function

   elemental function basis_descriptor(self) result (res)
   ! Return a basis descriptor, either the .basis_label or whether the
   ! atom is a dummy or a ghost.
      type(ATOM_TYPE), IN :: self
      STR(len=STR_SIZE) :: res

      ! The following code is inherited from ATOM
      if (allocated(self%basis)) then
         res = self%basis%label
         if (is_a_ghost_atom_(self)) then
            res = trim(res)//" (ghost atom)"
         else if (is_a_pseudo_atom_(self)) then
            res = trim(res)//" (pseudo atom)"
         end if
      else if (is_a_point_charge_(self)) then
         res = "n/a (pt. charge)"
      else if (is_a_dummy_atom_(self)) then
         res = "n/a (dummy atom)"
      else
         res = "??"
      end if
   end function

   elemental function slaterbasis_descriptor(self) result (res)
   ! Return a basis descriptor, either the .basis_label or whether the
   ! atom is a dummy or a ghost.
      type(ATOM_TYPE), IN :: self
      STR(len=STR_SIZE) :: res

      ! The following code is inherited from ATOM
      if (allocated(self%slaterbasis)) then
         res = self%slaterbasis%label
         if (is_a_ghost_atom_(self)) then
            res = trim(res)//" (ghost atom)"
         else if (is_a_pseudo_atom_(self)) then
            res = trim(res)//" (pseudo atom)"
         end if
      else if (is_a_point_charge_(self)) then
         res = "n/a (pt. charge)"
      else if (is_a_dummy_atom_(self)) then
         res = "n/a (dummy atom)"
      else
         res = "??"
      end if
   end function

   elemental function coppensbasis_descriptor(self) result (res)
   ! Return a basis descriptor, either the .basis_label or whether the
   ! atom is a dummy or a ghost.
      type(ATOM_TYPE), IN :: self
      STR(len=STR_SIZE) :: res

      ! The following code is inherited from ATOM
      if (allocated(self%coppensbasis)) then
         res = self%coppensbasis%label
         if (is_a_ghost_atom_(self)) then
            res = trim(res)//" (ghost atom)"
         else if (is_a_pseudo_atom_(self)) then
            res = trim(res)//" (pseudo atom)"
         end if
      else if (is_a_point_charge_(self)) then
         res = "n/a (pt. charge)"
      else if (is_a_dummy_atom_(self)) then
         res = "n/a (dummy atom)"
      else
         res = "??"
      end if
   end function

   PURE function library_basis_label_0(self,suffix) result (label)
   ! Return a library basis set label by appending "suffix" to the
   ! chemical symbol.
      type(ATOM_TYPE), IN :: self
      STR(len=*), IN :: suffix
      STR(len=STR_SIZE) :: label
      STR(len=STR_SIZE) :: symbol
      symbol = generic_chemical_symbol_(self)
      select case (suffix)

      case ("Coppens","Clementi-Roetti")
         ! Replace bases for high atomic numbers
         ! where bases do not exist
         if (self%atomic_number>55) then
            select case (self%atomic_number)
            case (56); symbol = "Sr"
            case (57:71); symbol = "Y"
            case (72:86); symbol = generic_chemical_symbol_(self%atomic_number-32)
            case (87); symbol = "Rb"
            case (88); symbol = "Sr"
            case (89:103); symbol = "Y"
            end select
         ! WARN("Atom "//trim(.generic_chemical_symbol)//" basis is now "//trim(symbol))
         end if
         label = trim(symbol)//trim(oxidation_state_str_(self))//":"//trim(suffix)

      case default
         label = trim(symbol)//":"//trim(suffix)
      end select
   end function

   PURE function library_basis_label_1(Z,suffix) result (label)
   ! Return a library basis set label for the atom with atomic number
   ! "Z", by appending "suffix" to the chemical symbol.
      INT, IN :: Z
      STR(len=*), IN :: suffix
      STR(len=STR_SIZE) :: label
      STR(len=STR_SIZE) :: symbol
   ENSURE(Z>=1 AND Z<=118,"ATOM:library_basis_label_1 ... Z out of range")
      symbol = element_symbols(Z)
      select case (suffix)

      case ("Coppens","Thakkar","Clementi-Roetti")
         if (Z>55) then
            select case (Z)
            case (56); symbol = "Sr"
            case (57:71); symbol = "Y"
            case (72:86); symbol = element_symbols(Z-32)
            case (87); symbol = "Rb"
            case (88); symbol = "Sr"
            case (89:103); symbol = "Y"
            end select
         end if
         label = trim(symbol)//":"//trim(suffix)

      case default
         label = trim(symbol)//":"//trim(suffix)
      end select
   end function


