!  =============================
!  Chemical-data related inquiry
!  =============================

   elemental function generic_chemical_symbol_0(self) result (res)
   ! Return the generic chemical symbol, which ignores isotopes.
      type(ATOM_TYPE), IN :: self
      STR(len=2) :: res
      INT :: Z
      Z = self%atomic_number
      res = generic_chemical_symbol_(Z)
   end function

   elemental function generic_chemical_symbol_1(Z) result (res)
   ! Return the element symbol for atomic number "Z".
      INT, IN :: Z
      STR(len=2) :: res
      res = "?"
      if (Z==0) then
         res = ATOM_DUMMY_CHARGE_LABEL
      else if (is_in_range_(Z,[1,118])) then
         res = element_symbols(Z)
      end if
   end function

   elemental function chemical_symbol_0(self) result (res)
   ! Return the chemical symbol for this atom. Accounts for D and T.
      type(ATOM_TYPE), IN :: self
      STR(len=2) :: res
      INT :: Z,A
      Z = self%atomic_number
      A = self%mass_number
      res = chemical_symbol_(Z,A)
   end function

   elemental function chemical_symbol_1(Z,A) result (res)
   ! The element symbol for atomic number "Z" mass_number "A".
      INT, IN :: Z
      INT, IN :: A
      STR(len=2) :: res
      res = "?"
      if (Z==0) then
         res = ATOM_DUMMY_CHARGE_LABEL
      else if (Z==1 AND A==2) then
         res = "D"
      else if (Z==1 AND A==3) then
         res = "T"
      else if (is_in_range_(Z,[1,118])) then
         res = element_symbols(Z)
      end if
   end function

   function atomic_number_from_label(label) result (Z)
   ! Return the atomic number from an atom label.
      STR(len=*), IN :: label
      INT :: Z
      STR(len=STR_SIZE) :: symbol
      symbol = element_symbol_from_label_(label)
      Z = index_of_(element_symbols(1:),symbol(1:2))
   end function

   pure function mass(self) result (res)
   ! Return the abundance-weighted mass C12 mass units unless
   ! mass_number is non-zero, in which case give the isotope mass.
      type(ATOM_TYPE), IN :: self
      REAL :: res
      if (self%mass_number>0) then
         res = mass_of_isotope(self%atomic_number,self%mass_number)
      else
         res = mass_of_atom(self%atomic_number)
      end if
   end function

   elemental function mass_of_atom(Z) result (res)
   ! Return the natural-abundance-weighted atomic mass in C12 mass units.
      INT, IN :: Z
      REAL :: res
      res = 0
      if (is_in_range_(Z,[1,92])) res = atomic_masses(Z)
   end function

   elemental function mass_of_isotope(Z,A) result (res)
   ! Return the atomic mass in C12 mass unoits for the isotope with
   ! atomic number "Z" and atomic mass number "A".
      INT, IN :: Z
      INT, IN :: A
      REAL :: res
      INT :: Zf,Zl,Af,Al
      REAL :: Zr,Ar
      Zr = Z
      Ar = A
      Zf = index_of_value_(isotope_data(1,:),Zr)
      Zl = index_of_value_(isotope_data(1,:),Zr,last=TRUE)
      Af = index_of_value_(isotope_data(2,Zf:Zl),Ar)
      Al = index_of_value_(isotope_data(2,Zf:Zl),Ar,last=TRUE)
      res = 0
      if (Af==Al) res = isotope_data(3,Af+Zf-1)
   end function

   pure function mean_neutron_number(self) result (res)
   ! Return the average (abundance weighted) number of neutrons for this atom,
   ! calculated roughly by subtracting the number of protons from the atomic mass.
      type(ATOM_TYPE), IN :: self
      REAL :: res
      if (self%atomic_number<1 OR self%atomic_number>92) then; res = ZERO
      else; res = self%mass-self%atomic_number
      end if
   end function

   pure function bragg_slater_radius(self) result (res)
   ! Return the Bragg-Slater radius for this atom
   ! WARNING: this is in Angstroms!
      type(ATOM_TYPE), IN :: self
      REAL :: res
      if (self%atomic_number<1) then; res = ZERO
      else if (self%atomic_number>54) then; res = 1.30d0
      else; res = bragg_slater_radii(self%atomic_number)
      end if
   end function

   pure function neutron_scattering_length(self) result (res)
   ! Return the neutron scattering length for this atom
      type(ATOM_TYPE), IN :: self
      REAL :: res
      if (self%atomic_number<1 OR self%atomic_number>95) then; res = ZERO
      else; res = neutron_scattering_lengths(self%atomic_number)
      end if
   end function

   elemental function n_core_electrons(self,Z) result (noble)
   ! Return the number of core electrons for the atom in the n-shell
   ! one less than the valence shell.  If "Z" is present it is used as
   ! the atomic number.
      type(ATOM_TYPE), IN :: self
      INT, optional, IN :: Z
      INT :: noble
      INT :: p
      INT :: atomic_number,tmp,n
      atomic_number = self%atomic_number
      if (present(Z)) atomic_number = Z
      noble = 0
      if (atomic_number<1) return
      p = 1
      do
         n = (p+2)/2
         tmp = noble+2*n**2
         if (atomic_number<=tmp) exit
         noble = tmp  ! add core electrons
         p = p+1  ! next period
      end do
   end function

   pure function period_number(self,Z) result (p)
   ! Return the period (i.e. row) on which the atom lies.
   ! If "Z" is present it is used as the atomic number.
      type(ATOM_TYPE), IN :: self
      INT, optional, IN :: Z
      INT :: p
      INT :: atomic_number,noble,n
      atomic_number = self%atomic_number
      if (present(Z)) atomic_number = Z
      p = 0
      if (atomic_number<1) return
      p = 1
      noble = 0
      do
         n = (p+2)/2
         noble = noble+2*n**2
         if (atomic_number<=noble) exit
         p = p+1
      end do
   end function

   pure function column_number(self,Z) result (col)
   ! Return the periodic table column of the atom.
   ! If "Z" is present it is used as the atomic number.
      type(ATOM_TYPE), IN :: self
      INT, optional, IN :: Z
      INT :: col
      INT :: atomic_number,p,noble,n
      atomic_number = self%atomic_number
      if (present(Z)) atomic_number = Z
      col = 0
      if (atomic_number<1) return
      p = 1
      noble = 0
      do
         n = (p+2)/2
         noble = noble+2*n**2
         if (atomic_number<=noble) exit
         p = p+1
      end do
      noble = noble-2*n**2
      col = atomic_number-noble
   end function

   PURE function period_block(self,Z) result (b)
   ! Return the period block character in which the atom lies.
   ! If "Z" is present it is used as the atomic number.
      type(ATOM_TYPE), IN :: self
      INT, optional, IN :: Z
      STR(len=1) :: b
      INT :: p,col
   ENSURE(Z>0,"ATOM:period_block ... atomic charge Z not +ve")
   ENSURE(period_number_(self,Z)<8,"ATOM:period_block ... Z is too large")
      p = period_number_(self,Z)
      col = column_number_(self,Z)
      b = "?"
      if (p<4) then
         select case (col)
         case (1:2); b = "s"
         case (3:8); b = "p"
         end select
      else if (p<6) then
         select case (col)
         case (1:2); b = "s"
         case (3:12); b = "d"
         case (13:18); b = "p"
         end select
      else if (p<8) then
         select case (col)
         case (1:2); b = "s"
         case (3:16); b = "f"
         case (17:26); b = "d"
         case (27:32); b = "p"
         end select
      end if
   end function

   elemental function is_a_H_atom(self) result (res)
   ! Return whether the atom is a H atom
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = self%atomic_number==1
   end function

   elemental function is_not_a_H_atom(self) result (res)
   ! Return whether the atom is not a H atom
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = self%atomic_number/=1
   end function

   elemental function is_a_nonmetal(self,Z) result (res)
   ! Return whether the atom is a nonmetal.
   ! If "Z" is present it is used as the atomic number.
      type(ATOM_TYPE), IN :: self
      INT, IN, optional :: Z
      BIN :: res
      INT :: atomic_number

      ! Get atomic number
      atomic_number = self%atomic_number
      if (present(Z)) atomic_number = Z
      res = FALSE
      select case (atomic_number)
      case (1:2); res = TRUE  !  H - He
      case (6:10); res = TRUE  !  C - Ne
      case (15:18); res = TRUE  !  P - Ar
      case (34:36); res = TRUE  ! Se - Kr
      case (53:54); res = TRUE  !  I - Xe
      case (86); res = TRUE  !  Rn
      end select
   end function

   elemental function is_a_metalloid(self,Z) result (res)
   ! Return whether the atom is a metalloid.
   ! If "Z" is present it is used as the atomic number.
      type(ATOM_TYPE), IN :: self
      INT, IN, optional :: Z
      BIN :: res
      INT :: atomic_number

      ! Get atomic number
      atomic_number = self%atomic_number
      if (present(Z)) atomic_number = Z
      res = FALSE
      select case (atomic_number)
      case (5); res = TRUE  !  B
      case (14); res = TRUE  ! Si
      case (32:33); res = TRUE  ! Ge - As
      case (51:52); res = TRUE  ! Sb - Te
      case (85); res = TRUE  ! As
      end select
   end function

   elemental function is_a_metal(self,Z) result (res)
   ! Return whether the atom is a metalloid.
   ! If "Z" is present it is used as the atomic number.
      type(ATOM_TYPE), IN :: self
      INT, IN, optional :: Z
      BIN :: res
      BIN :: metalloid,nonmetal
      nonmetal = is_a_nonmetal_(self,Z)
      metalloid = is_a_metalloid_(self,Z)
      res = NOT nonmetal AND NOT metalloid
   end function

   PURE function ground_state_multiplicity(self,Z) result (mult)
   ! Return the ground state multiplicity for this atom according to Hunds rule
   ! (Note this is not neccesarily the real ground state, esp. for Cu)
   ! If "Z" is present it is used as the atomic number.
      type(ATOM_TYPE), IN :: self
      INT, optional, IN :: Z
      INT :: mult
      INT :: p,col
   ENSURE(is_in_range_(period_number_(self,Z),[0,7]),"ATOM:ground_state_multiplicity ... cannot assign for Z ="//trim(to_str_(Z)))

      ! Get period and column
      p = period_number_(self,Z)
      col = column_number_(self,Z)
      mult = 0
      select case (p)

      case (0)

         ! Dummy atom or Electron
         mult = 1

      case (1,2,3)

         ! First three periods
         select case (col)
         case (8); mult = 1
         case (1,3,7); mult = 2
         case (2,4,6); mult = 3
         case (5); mult = 4
         end select

      case (4,5)

         ! First two transition metal periods
         select case (col)
         case (2,12,18); mult = 1
         case (1,3,11,13,17); mult = 2
         case (4,10,14,16); mult = 3
         case (5,9,15); mult = 4
         case (6,8); mult = 5
         case (7); mult = 6
         end select

      case (6,7)

         ! First two actinide metal periods
         select case (col)
         case (2,16,26,32); mult = 1
         case (1,3,15,17,25,27,31); mult = 2
         case (4,14,18,24,28,30); mult = 3
         case (5,13,19,23,29); mult = 4
         case (6,12,20,22); mult = 5
         case (7,11,21); mult = 6
         case (8,10); mult = 7
         case (9); mult = 8
         end select
      end select
   end function

   PURE function oxidation_state_str(self) result (res)
   ! Return the oxidation state string, i.e. if the oxidation state is +3, then
   ! the returned string is "3+"; or if the oxidation state is -1 then the
   ! returned string is "-". This is useful for resolving certain library basis
   ! labels.
      type(ATOM_TYPE), IN :: self
      STR(len=STR_SIZE) :: res
      INT :: charge
      charge = self%oxidation_state
      if (charge==0) then
         res = " "
      else
         if (charge>0) then; res = "+"
         else; res = "-"
         end if
         charge = abs(charge)
         if (charge/=1) res = trim(to_str_(charge))//trim(res)
      end if
   end function


!  =======================
!  Protien related inquiry
!  =======================

   PURE function compound_id_str(self) result (res)
   ! Return the unique compound id string.
      type(ATOM_TYPE), IN :: self
      STR(len=STR_SIZE) :: res
      res = trim(self%compound_id)//"-"//trim(to_str_(self%compound_sequence_id))
   end function

   PURE function id_compound_str(self) result (res)
   ! Return the unique compound id string - this is reverse relative
   ! to the above routine which is better for ordering file names.
      type(ATOM_TYPE), IN :: self
      STR(len=STR_SIZE) :: res
      res = trim(to_str_(self%compound_sequence_id))//"-"//trim(self%compound_id)
   end function

   PURE function is_in_a_residue(self) result (res)
   ! Return TRUE if the atom belongs to a protein residue as
   ! determined by the compound_id
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = any(self%compound_id(1:3)==protein_letter_codes(3,:))
   end function

   PURE function std_protein_residue_charge(self) result (res)
   ! Return the standard charge of the residue to which
   ! the atom belongs to.
      type(ATOM_TYPE), IN :: self
      INT :: res
      INT :: ind
   ENSURE(is_in_a_residue_(self),"ATOM:std_protein_residue_charge ... not in a residue")
      ind = index_of_(protein_letter_codes(3,:),self%compound_id(1:3))
      res = to_int_(protein_letter_codes(2,ind))
   end function


!  =========================
!  Form factors & dispersion
!  =========================

   elemental function H_SDS_form_factor(k) result (res)
   ! The H atom SDS form factor where "k" is the scattering vector
   ! in reciprocal Bohr.
      REAL, IN :: k
      REAL :: res
      REAL :: stl,a,b
      INT :: i

      ! Convert k to s.t.l.
      ! See Dunitz p.27-28
      stl = HALF*k*BOHR_PER_ANGSTROM/(2*PI)
      stl = stl*stl

      ! Do it baby
      res = ZERO
      do i = 0,4
         a = H_SDS_form_factor_coeff(1,i)
         b = H_SDS_form_factor_coeff(2,i)
         res = res+a*exp(-b*stl)
      end do
   end function

   elemental function H_HF0_form_factor(k) result (res)
   ! The H atom *neutral* form factor where "k" is the scattering
   ! vector in reciprocal Bohr.
      REAL, IN :: k
      REAL :: res
      REAL :: stl,a,b
      INT :: i

      ! Convert k to s.t.l.
      ! See Dunitz p.27-28
      stl = HALF*k*BOHR_PER_ANGSTROM/(2*PI)
      stl = stl*stl

      ! Do it baby
      res = ZERO
      do i = 0,4
         a = H_HF0_form_factor_coeff(1,i)
         b = H_HF0_form_factor_coeff(2,i)
         res = res+a*exp(-b*stl)
      end do
   end function

   PURE subroutine ground_state_open_shell(Z,l,n)
   ! The Aufbau open shell of the neutral atom of atomic number "Z": its
   ! angular momentum "l" and its electron count "n", 0 for a closed
   ! shell. "l" is -1 when the rule does not give one open shell: Z above
   ! 36, and Cr and Cu, whose ground states are 3d5 4s1 and 3d10 4s1.
      INT, IN :: Z
      INT, OUT :: l,n
      VEC(INT,8) :: shell_l
      INT :: left,i,cap
      l = -1
      n = 0
      if (Z<1 OR Z>36 OR Z==24 OR Z==29) return
      shell_l = [0,0,1,0,1,0,2,1]  ! 1s 2s 2p 3s 3p 4s 3d 4p
      left = Z
      do i = 1,8
         cap = 2*(2*shell_l(i)+1)
         if (left<=cap) then
            l = shell_l(i)
            if (left<cap) n = left
            return
         end if
         left = left-cap
      end do
   end subroutine

   pure function AOC_coupling(n_orbitals,n_electrons) result (res)
   ! Roothaan's coupling constant a (= b) for the average of configuration
   ! of "n_electrons" in an open shell of "n_orbitals": 1 for a closed
   ! shell, 0 for one electron.
      INT, IN :: n_orbitals,n_electrons
      REAL :: res
      res = TWO*n_orbitals*(n_electrons-ONE)/(n_electrons*(TWO*n_orbitals-ONE))
   end function

   PURE subroutine IT_form_factor_coeffs(Z,a,b,c)
   ! The International Tables (Vol. C, Table 6.1.1.4) form factor
   ! coefficients of the neutral atom of atomic number "Z":
   ! f(s) = sum_i a(i) exp(-b(i) s^2) + c, s = sin(theta)/lambda in 1/A.
      INT, IN :: Z
      VEC(REAL,4), OUT :: a,b
      REAL, OUT :: c
      INT :: i
   ENSURE(is_in_range_(Z,[1,98]),"ATOM:IT_form_factor_coeffs ... Z out of range, Z = "//trim(to_str_(Z)))
      do i = 1,4
         a(i) = HF_n0_form_factor_coeff(1,i,Z)
         b(i) = HF_n0_form_factor_coeff(2,i,Z)
      end do
      c = HF_n0_form_factor_coeff(1,0,Z)
   end subroutine

   PURE function HF_n0_form_factor(self,k) result (res)
   ! The HF *neutral* form factor for atom, where "k" is the
   ! scattering vector in reciprocal Bohr.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), IN :: k
      VEC(REAL,size(k)) :: res
      VEC(REAL,:), allocatable :: stl
      REAL :: a,b
      INT :: i
   ENSURE(is_in_range_(self%atomic_number,[1,98]),"ATOM:HF_n0_form_factor ... Z out of range, Z = "//trim(to_str_(self%atomic_number)))

      ! Convert k to s.t.l.
      ! See Dunitz p.27-28
      call create_(stl,size(k))
      stl = HALF*k*BOHR_PER_ANGSTROM/(2*PI)
      stl = stl*stl

      ! Do it baby
      res = ZERO
      do i = 0,4
         a = HF_n0_form_factor_coeff(1,i,self%atomic_number)
         b = HF_n0_form_factor_coeff(2,i,self%atomic_number)
         res = res+a*exp(-b*stl)
      end do
      call destroy_(stl)
   end function

   elemental function has_dispersion(self) result (res)
   ! Return TRUE if the atom has non-zero dispersion coefficients
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = NOT is_zero_(self%f_r) OR NOT is_zero_(self%f_i)
   end function

   ELEMENTAL function has_tabular_dispersion(self) result (res)
   ! Return TRUE if this element has a valid dispersion coefficient in
   ! the table.
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = has_tabular_dispersion_for_(self%atomic_number)
   end function

   ELEMENTAL function has_tabular_dispersion_for(Z) result (res)
   ! Return TRUE if the element with atomic number "Z"  has a
   ! valid dispersion coefficient in the table.
      INT, IN :: Z
      BIN :: res
      res = abs(element_xray_dispersion(Z))>=ZERO
   end function

   elemental function dispersion_correction(self) result (res)
   ! The dispersion correction at a certain "wavelength".
      type(ATOM_TYPE), IN :: self
      CPX :: res
      res = element_xray_dispersion(self%atomic_number)
   end function


