   PURE function xray_dispersion_entered() result (res)
   ! Return whether xray_dispersion table was entered.
      BIN :: res
      res = xray_dispersion_set
   end function

   subroutine set_dispersion_coefficients_0(Z,f_r,f_i)
   ! Set the elemental dispersion coefficients from f_r and f_i.
      INT, IN :: Z
      REAL, IN :: f_r,f_i

      ! Set them in the table
      element_xray_dispersion(Z) = COMPLEXIFY(f_r,f_i)
      xray_dispersion_set = TRUE
   end subroutine

   subroutine set_dispersion_coefficients_1(string)
   ! Set the elemental dispersion coefficients from a "string"
   ! of values comprising sequential element symbols, f' and f''.
      STR(len=*), IN :: string
      VEC(STR(len=STR_SIZE),:), allocatable :: table
      table = split_(string)
      call set_dispersion_coefficients_(table)
      call destroy_(table)
   end subroutine

   subroutine set_dispersion_coefficients_2(table)
   ! Set the elemental dispersion coefficients from a "table"
   ! of values comprising sequential element symbols, f' and f''.
      VEC(STR(len=*),:), IN :: table
      STR(len=2) :: symbol
      STR(len=STR_SIZE) :: val1,val2,val3
      INT :: i,offset,Z
      REAL :: f_r,f_i
   DIE_IF((size(table)/3)*3/=size(table),"ATOM:set_dispersion_coefficients_2 ... the table is not divisible by 3")
      offset = 0
      do i = 1,size(table)/3
         val1 = table(offset+1)
         val2 = table(offset+2)
         val3 = table(offset+3)

         ! Get the atomic number Z
         symbol = element_symbol_from_label_(val1)
         Z = index_of_(element_symbols(1:),symbol(1:2))
         DIE_IF(Z==0,"ATOM:set_dispersion_coefficients_2 ... unknown element symbol: "//trim(symbol))

         ! Get f' and f''
         f_r = to_real_(val2)
         f_i = to_real_(val3)

         ! Set them in the table
         element_xray_dispersion(Z) = COMPLEXIFY(f_r,f_i)

         ! Next in the table
         offset = offset+3
      end do
      xray_dispersion_set = TRUE
   end subroutine

   PURE subroutine set_tabular_dispersion(self)
   ! Set the atom's own dispersion coefficients from
   ! the element_xray_dispersion table (if there).
      type(ATOM_TYPE), INOUT :: self
      INT :: Z
      REAL :: f_r,f_i
      Z = self%atomic_number
      f_r = RE(element_xray_dispersion(Z))
      f_i = IM(element_xray_dispersion(Z))
      self%f_r = f_r
      self%f_i = f_i
   end subroutine

   PURE subroutine get_dispersion(self,Fa,k_pts,rf)
   ! Get the anamalous dispersion correction into "Fa", for a given
   ! set of "k_pts" and with "rf" the site symmetry factors.
      type(ATOM_TYPE), IN :: self
      VEC(CPX,:), INOUT :: Fa
      MAT(REAL,:,:), IN :: k_pts
      REAL, IN :: rf
      CPX :: II,anom,phase
      VEC(REAL,3) :: kv
      MAT(REAL,3,3) :: adp2
      MAT3(REAL,3,3,3) :: adp3
      MAT4(REAL,3,3,3,3) :: adp4
      REAL :: c2,c3,c4
      INT :: k,n_k
      CPX :: val
   ENSURE(size(Fa,1)==size(k_pts,1),"ATOM:get_dispersion ... 1st dimension of dc and k_pts are not compatible")
   ENSURE(3==size(k_pts,2),"ATOM:get_dispersion ... 2nd dimension of k_pts must be 3!")
      II = IMAGIFY(ONE)
      anom = dispersion_correction_(self)
      n_k = size(k_pts,1)
      Fa = ZERO

      ! Temperature part, ADP4's
      if (has_only_ADP4s_and_errors_(self)) then

         ! Get ADP tensors
         call put_ADP2_vector_to_(self,adp2)
         call put_ADP3_vector_to_(self,adp3)
         call put_ADP4_vector_to_(self,adp4)
         do k = 1,n_k

            ! U tensor contracted with k vector
            kv = k_pts(k,:)
            c2 = contract_with_(adp2,kv)*HALF
            c3 = contract_with_(adp3,kv)*SIXTH
            c4 = contract_with_(adp4,kv)*SIXTH*QUARTER

            ! SF contribution (quartic anharmonic!)
            phase = k_pts(k,1)*self%position(1)+k_pts(k,2)*self%position(2)+k_pts(k,3)*self%position(3)
            phase = exp(II*phase)
            Fa(k) = Fa(k)+anom*phase*exp(-c2)*(ONE-II*c3+c4)/rf
         end do

      ! Temperature part, ADP3's
      else if (has_only_ADP3s_and_errors_(self)) then

         ! Get ADP tensors
         call put_ADP2_vector_to_(self,adp2)
         call put_ADP3_vector_to_(self,adp3)
         do k = 1,n_k

            ! U tensor contracted with k vector
            kv = k_pts(k,:)
            c2 = contract_with_(adp2,kv)*HALF
            c3 = contract_with_(adp3,kv)*SIXTH

            ! SF contribution (cubic anharmonic!)
            phase = k_pts(k,1)*self%position(1)+k_pts(k,2)*self%position(2)+k_pts(k,3)*self%position(3)
            phase = exp(II*phase)
            Fa(k) = Fa(k)+anom*phase*exp(-c2)*(ONE-II*c3)/rf
         end do

      ! Harmonic ...
      else

         ! Get ADP tensor
         call put_ADP2_vector_to_(self,adp2)
         do k = 1,n_k

            ! U tensor contracted with k vector
            kv = k_pts(k,:)
            c2 = contract_with_(adp2,kv)*HALF

            ! SF contribution (harmonic!)
            phase = kv(1)*self%position(1)+kv(2)*self%position(2)+kv(3)*self%position(3)
            phase = exp(II*phase)
            val = anom*phase*exp(-c2)/rf
            Fa(k) = Fa(k)+val
         end do
      end if
   end subroutine

   PURE subroutine add_dispersion(self,Fc,k_pts,rf)
   ! Add the anamalous dispersion correction into the calculated
   ! structure factor "Fc", for a given set of "k_pts" and with "rf"
   ! the repetition factors.
      type(ATOM_TYPE), IN :: self
      VEC(CPX,:), INOUT :: Fc
      MAT(REAL,:,:), IN :: k_pts
      REAL, IN :: rf
      CPX :: II,anom,phase
   ! fr :: VEC{REAL}(3)
   ! Uv :: VEC{REAL}(6)
      VEC(REAL,3) :: kv
      MAT(REAL,3,3) :: adp2
      MAT3(REAL,3,3,3) :: adp3
      MAT4(REAL,3,3,3,3) :: adp4
      REAL :: c2,c3,c4
      INT :: k,n_k
      CPX :: val
   ENSURE(size(Fc,1)==size(k_pts,1),"ATOM:add_dispersion ... 1st dimension of dc and k_pts are not compatible")
   ENSURE(3==size(k_pts,2),"ATOM:add_dispersion ... 2nd dimension of k_pts must be 3!")
      II = IMAGIFY(ONE)
      anom = dispersion_correction_(self)
      n_k = size(k_pts,1)

   !       if (.atomic_number==16) then
   !          stdout.show("f'          =",RE(anom))
   !          stdout.show("f''         =",IM(anom))
   !          stdout.show("rf          =",rf)
   !          stdout.text("position:")
   !          stdout.put(.position)
   !       end

      ! Temperature part, ADP4's
      if (has_only_ADP4s_and_errors_(self)) then

         ! Get ADP tensors
         call put_ADP2_vector_to_(self,adp2)
         call put_ADP3_vector_to_(self,adp3)
         call put_ADP4_vector_to_(self,adp4)
         do k = 1,n_k

            ! U tensor contracted with k vector
            kv = k_pts(k,:)
            c2 = contract_with_(adp2,kv)*HALF
            c3 = contract_with_(adp3,kv)*SIXTH
            c4 = contract_with_(adp4,kv)*SIXTH*QUARTER

            ! SF contribution (quartic anharmonic!)
            phase = k_pts(k,1)*self%position(1)+k_pts(k,2)*self%position(2)+k_pts(k,3)*self%position(3)
            phase = exp(II*phase)
            Fc(k) = Fc(k)+anom*phase*exp(-c2)*(ONE-II*c3+c4)/rf
         end do

      ! Temperature part, ADP3's
      else if (has_only_ADP3s_and_errors_(self)) then

         ! Get ADP tensors
         call put_ADP2_vector_to_(self,adp2)
         call put_ADP3_vector_to_(self,adp3)
         do k = 1,n_k

            ! U tensor contracted with k vector
            kv = k_pts(k,:)
            c2 = contract_with_(adp2,kv)*HALF
            c3 = contract_with_(adp3,kv)*SIXTH

            ! SF contribution (cubic anharmonic!)
            phase = k_pts(k,1)*self%position(1)+k_pts(k,2)*self%position(2)+k_pts(k,3)*self%position(3)
            phase = exp(II*phase)
            Fc(k) = Fc(k)+anom*phase*exp(-c2)*(ONE-II*c3)/rf
         end do

      ! Harmonic ...
      else

         ! Get ADP tensor
         call put_ADP2_vector_to_(self,adp2)
         do k = 1,n_k

            ! U tensor contracted with k vector
            kv = k_pts(k,:)
            c2 = contract_with_(adp2,kv)*HALF

            ! SF contribution (harmonic!)
            phase = kv(1)*self%position(1)+kv(2)*self%position(2)+kv(3)*self%position(3)
            phase = exp(II*phase)
            val = anom*phase*exp(-c2)/rf
            Fc(k) = Fc(k)+val
         end do
      end if
   end subroutine

   PURE subroutine add_derivative_dispn(self,dFc,base,k_pts,rf)
   ! Add the derivative of the anamalous dispersion correction into
   ! the calculated derivative structure factor "Fc", for a given set
   ! of "k_pts". "base" is the index of where the derivatives for 
   ! this atom start in the full derivative structure factor array.
   ! "rf" is the repetition/site symmetry factor for the atom.
   ! -- This version works for the H U_iso case --
      type(ATOM_TYPE), IN :: self
      MAT(CPX,:,:), INOUT :: dFc
      INT, IN :: base
      MAT(REAL,:,:), IN :: k_pts
      REAL, IN :: rf
      CPX :: II,anom,phase
      CPX :: sfh,sf1,sf2,sf4,sf6,sf24
      VEC(REAL,3) :: kv
      MAT(REAL,3,3) :: adp2
      MAT3(REAL,3,3,3) :: adp3
      MAT4(REAL,3,3,3,3) :: adp4
      REAL :: c2,c3,c4
      REAL :: k1,k2,k3
      REAL :: k1_k1,k2_k2,k3_k3
      REAL :: k1_k2,k1_k3,k2_k3
      INT :: k,n_k
   ENSURE(size(dFc,1)==size(k_pts,1),"ATOM:add_derivative_dispn ... 1st dimension of dc and k_pts are not compatible")
   ENSURE(3==size(k_pts,2),"ATOM:add_derivative_dispn ... 2nd dimension of k_pts must be 3!")
   ! val :: VEC{CPX}(9)
      II = IMAGIFY(ONE)
      anom = dispersion_correction_(self)

         ! if (.atomic_number==16) then
         !    stdout.show("f'          =",RE(anom))
         !    stdout.show("f''         =",IM(anom))
         !    stdout.text("position:")
         !    stdout.put(.position)
         ! end
      n_k = size(k_pts,1)

      ! Temperature part, ADP4's
      if (has_only_ADP4s_and_errors_(self)) then
         ENSURE(self%atomic_number/=1,"ATOM:add_derivative_dispn ... can't add derivative dispersion corrections when refining H anharmonically with H isotropic")

         ! Get ADP tensors
         call put_ADP2_vector_to_(self,adp2)
         call put_ADP3_vector_to_(self,adp3)
         call put_ADP4_vector_to_(self,adp4)
         do k = 1,n_k

            ! Scattering vector
            k1 = k_pts(k,1)
            k2 = k_pts(k,2)
            k3 = k_pts(k,3)
            kv = [k1,k2,k3]

            ! Component products
            k1_k1 = k1*k1
            k2_k2 = k2*k2
            k3_k3 = k3*k3
            k1_k2 = k1*k2
            k1_k3 = k1*k3
            k2_k3 = k2*k3

            ! U tensor contracted with k vector
            c2 = contract_with_(adp2,kv)*HALF
            c3 = contract_with_(adp3,kv)*SIXTH
            c4 = contract_with_(adp4,kv)*SIXTH*QUARTER

            ! Constant part of the derivative dispersion
            ! correction, harmonic part only.
            ! NOTE: division by repetition factor "rf" in sfh
            phase = k_pts(k,1)*self%position(1)+k_pts(k,2)*self%position(2)+k_pts(k,3)*self%position(3)
            sfh = anom*exp(II*phase)*exp(-c2)/rf  ! <--- 

            ! Multiples of *anharmonic* part of anamalous correction
            sf1 = sfh*(ONE-II*c3+c4)
            sf2 = sf1*HALF

            ! Pos derivatives
            dFc(k,base+1) = dFc(k,base+1)+II*k1*sf1
            dFc(k,base+2) = dFc(k,base+2)+II*k2*sf1
            dFc(k,base+3) = dFc(k,base+3)+II*k3*sf1

            ! U2 derivatives
            dFc(k,base+4) = dFc(k,base+4)-k1_k1*sf2
            dFc(k,base+5) = dFc(k,base+5)-k2_k2*sf2
            dFc(k,base+6) = dFc(k,base+6)-k3_k3*sf2
            dFc(k,base+7) = dFc(k,base+7)-k1_k2*sf1
            dFc(k,base+8) = dFc(k,base+8)-k1_k3*sf1
            dFc(k,base+9) = dFc(k,base+9)-k2_k3*sf1

            ! Structure factor (harmonic)
            sf1 = sfh

            ! Multiples of *harmonic* part of the anomalous correction
            sf2 = sf1*HALF
            sf4 = sf1*QUARTER
            sf6 = sf1*SIXTH
            sf24 = sf1*SIXTH*QUARTER

            ! U3 derivatives
            dFc(k,base+10) = dFc(k,base+10)-II*k1_k1*k1*sf6
            dFc(k,base+11) = dFc(k,base+11)-II*k2_k2*k2*sf6
            dFc(k,base+12) = dFc(k,base+12)-II*k3_k3*k3*sf6
            dFc(k,base+13) = dFc(k,base+13)-II*k1_k1*k2*sf2
            dFc(k,base+14) = dFc(k,base+14)-II*k1_k1*k3*sf2
            dFc(k,base+15) = dFc(k,base+15)-II*k2_k2*k1*sf2
            dFc(k,base+16) = dFc(k,base+16)-II*k2_k2*k3*sf2
            dFc(k,base+17) = dFc(k,base+17)-II*k3_k3*k1*sf2
            dFc(k,base+18) = dFc(k,base+18)-II*k3_k3*k2*sf2
            dFc(k,base+19) = dFc(k,base+19)-II*k1*k2*k3*sf1

            ! U4 derivatives
            dFc(k,base+20) = dFc(k,base+20)+k1_k1*k1_k1*sf24
            dFc(k,base+21) = dFc(k,base+21)+k2_k2*k2_k2*sf24
            dFc(k,base+22) = dFc(k,base+22)+k3_k3*k3_k3*sf24
            dFc(k,base+23) = dFc(k,base+23)+k1_k1*k1_k2*sf6
            dFc(k,base+24) = dFc(k,base+24)+k1_k1*k1_k3*sf6
            dFc(k,base+25) = dFc(k,base+25)+k2_k2*k1_k2*sf6
            dFc(k,base+26) = dFc(k,base+26)+k2_k2*k2_k3*sf6
            dFc(k,base+27) = dFc(k,base+27)+k3_k3*k1_k3*sf6
            dFc(k,base+28) = dFc(k,base+28)+k3_k3*k2_k3*sf6
            dFc(k,base+29) = dFc(k,base+29)+k1_k1*k2_k2*sf4
            dFc(k,base+30) = dFc(k,base+30)+k1_k1*k3_k3*sf4
            dFc(k,base+31) = dFc(k,base+31)+k2_k2*k3_k3*sf4
            dFc(k,base+32) = dFc(k,base+32)+k1_k1*k2_k3*sf2
            dFc(k,base+33) = dFc(k,base+33)+k2_k2*k1_k3*sf2
            dFc(k,base+34) = dFc(k,base+34)+k3_k3*k1_k2*sf2
         end do

      ! Temperature part, ADP3's
      else if (has_only_ADP3s_and_errors_(self)) then
         ENSURE(self%atomic_number/=1,"ATOM:add_derivative_dispn ... can't add derivative dispersion corrections when refining H anharmonically with H isotropic")

         ! Get ADP tensors
         call put_ADP2_vector_to_(self,adp2)
         call put_ADP3_vector_to_(self,adp3)
         do k = 1,n_k

            ! Scattering vector
            k1 = k_pts(k,1)
            k2 = k_pts(k,2)
            k3 = k_pts(k,3)
            kv = [k1,k2,k3]

            ! Component products
            k1_k1 = k1*k1
            k2_k2 = k2*k2
            k3_k3 = k3*k3
            k1_k2 = k1*k2
            k1_k3 = k1*k3
            k2_k3 = k2*k3

            ! U tensor contracted with k vector
            c2 = contract_with_(adp2,kv)*HALF
            c3 = contract_with_(adp3,kv)*SIXTH

            ! Constant part of the derivative dispersion
            ! correction, harmonic part only.
            ! NOTE: division by repetition factor "rf" in sfh
            phase = k_pts(k,1)*self%position(1)+k_pts(k,2)*self%position(2)+k_pts(k,3)*self%position(3)
            sfh = anom*exp(II*phase)*exp(-c2)/rf  ! <---

            ! Multiples of *anharmonic* part of anamalous correction
            sf1 = sfh*(ONE-II*c3)
            sf2 = sf1*HALF

            ! Pos derivatives
            dFc(k,base+1) = dFc(k,base+1)+II*k1*sf1
            dFc(k,base+2) = dFc(k,base+2)+II*k2*sf1
            dFc(k,base+3) = dFc(k,base+3)+II*k3*sf1

            ! U2 derivatives
            dFc(k,base+4) = dFc(k,base+4)-k1_k1*sf2
            dFc(k,base+5) = dFc(k,base+5)-k2_k2*sf2
            dFc(k,base+6) = dFc(k,base+6)-k3_k3*sf2
            dFc(k,base+7) = dFc(k,base+7)-k1_k2*sf1
            dFc(k,base+8) = dFc(k,base+8)-k1_k3*sf1
            dFc(k,base+9) = dFc(k,base+9)-k2_k3*sf1

            ! Structure factor (harmonic)
            sf1 = sfh

            ! Multiples of *harmonic* part of the anomalous correction
            sf2 = sf1*HALF
            sf6 = sf1*SIXTH

            ! U3 derivatives
            dFc(k,base+10) = dFc(k,base+10)-II*k1_k1*k1*sf6
            dFc(k,base+11) = dFc(k,base+11)-II*k2_k2*k2*sf6
            dFc(k,base+12) = dFc(k,base+12)-II*k3_k3*k3*sf6
            dFc(k,base+13) = dFc(k,base+13)-II*k1_k1*k2*sf2
            dFc(k,base+14) = dFc(k,base+14)-II*k1_k1*k3*sf2
            dFc(k,base+15) = dFc(k,base+15)-II*k2_k2*k1*sf2
            dFc(k,base+16) = dFc(k,base+16)-II*k2_k2*k3*sf2
            dFc(k,base+17) = dFc(k,base+17)-II*k3_k3*k1*sf2
            dFc(k,base+18) = dFc(k,base+18)-II*k3_k3*k2*sf2
            dFc(k,base+19) = dFc(k,base+19)-II*k1*k2*k3*sf1
         end do

      ! Harmonic *and* NOT H atom ...
      else if (self%atomic_number>1) then

         ! Get ADP tensors
         call put_ADP2_vector_to_(self,adp2)
         do k = 1,n_k

            ! Scattering vector
            k1 = k_pts(k,1)
            k2 = k_pts(k,2)
            k3 = k_pts(k,3)
            kv = [k1,k2,k3]

            ! Component products
            k1_k1 = k1*k1
            k2_k2 = k2*k2
            k3_k3 = k3*k3
            k1_k2 = k1*k2
            k1_k3 = k1*k3
            k2_k3 = k2*k3

            ! U tensor contracted with k vector
            c2 = contract_with_(adp2,kv)*HALF

            ! Constant part of the derivative dispersion
            ! correction, harmonic part only.
            ! NOTE: division by repetition factor "rf" in sfh
            phase = k_pts(k,1)*self%position(1)+k_pts(k,2)*self%position(2)+k_pts(k,3)*self%position(3)
            sfh = anom*exp(II*phase)*exp(-c2)/rf  ! <---

            ! Multiples of *anharmonic* part of anamalous correction
            sf1 = sfh
            sf2 = sf1*HALF

            ! Pos derivatives
            dFc(k,base+1) = dFc(k,base+1)+II*k1*sf1
            dFc(k,base+2) = dFc(k,base+2)+II*k2*sf1
            dFc(k,base+3) = dFc(k,base+3)+II*k3*sf1

            ! U2 derivatives
            dFc(k,base+4) = dFc(k,base+4)-k1_k1*sf2
            dFc(k,base+5) = dFc(k,base+5)-k2_k2*sf2
            dFc(k,base+6) = dFc(k,base+6)-k3_k3*sf2
            dFc(k,base+7) = dFc(k,base+7)-k1_k2*sf1
            dFc(k,base+8) = dFc(k,base+8)-k1_k3*sf1
            dFc(k,base+9) = dFc(k,base+9)-k2_k3*sf1
         end do

      ! Harmonic and H U_iso case ...
      else

         ! Get ADP tensors
         call put_ADP2_vector_to_(self,adp2)
         do k = 1,n_k

            ! Scattering vector
            k1 = k_pts(k,1)
            k2 = k_pts(k,2)
            k3 = k_pts(k,3)
            kv = [k1,k2,k3]

            ! Component products
            k1_k1 = k1*k1
            k2_k2 = k2*k2
            k3_k3 = k3*k3
            k1_k2 = k1*k2
            k1_k3 = k1*k3
            k2_k3 = k2*k3

            ! U tensor contracted with k vector
            c2 = contract_with_(adp2,kv)*HALF

            ! Constant part of the derivative dispersion
            ! correction, harmonic part only.
            ! NOTE: division by repetition factor "rf" in sfh
            phase = k_pts(k,1)*self%position(1)+k_pts(k,2)*self%position(2)+k_pts(k,3)*self%position(3)
            sfh = anom*exp(II*phase)*exp(-c2)/rf  ! <---

            ! Multiples of *anharmonic* part of anamalous correction
            sf1 = sfh
            sf2 = HALF*sfh*(k1_k1+k2_k2+k3_k3)  ! NOTE

            ! Pos derivatives
            dFc(k,base+1) = dFc(k,base+1)+II*k1*sf1
            dFc(k,base+2) = dFc(k,base+2)+II*k2*sf1
            dFc(k,base+3) = dFc(k,base+3)+II*k3*sf1

            ! H U_iso derivatives; no off diagonal contribution
            dFc(k,base+4) = dFc(k,base+4)-sf2
            dFc(k,base+5) = dFc(k,base+5)-sf2
            dFc(k,base+6) = dFc(k,base+6)-sf2
         end do
      end if
   end subroutine


!   add_derivative_dispn_H_ADP_d(dFc,base,k_pts,rf) :: PURE
!   ! Add the derivative of the anamalous dispersion correction into
!   ! the calculated derivative structure factor "Fc", for a given set
!   ! of "k_pts". "base" is the index of where the derivatives for 
!   ! this atom start in the full derivative structure factor array.
!   ! "rf" is the repetition/site symmetry factor for the atom.
!      self :: IN
!      dFc :: MAT{CPX}, INOUT
!      base :: INT, IN
