!      rf :: REAL, IN
!
!   ENSURE(dFc.dim1==k_pts.dim1,"1st dimension of dc and k_pts are not compatible")
!   ENSURE(       3==k_pts.dim2,"2nd dimension of k_pts must be 3!")
!
!      II,anom,phase :: CPX
!      sfh,sf1,sf2,sf4,sf6,sf24 :: CPX
!      kv :: VEC{REAL}(3)
!      adp2 :: MAT{REAL}(3,3)
