!  ====
!  ANOs
!  ====

   PURE function no_of_occupied_NAOs(self,tol) result (res)
   ! Returns the number of non-zero occupied NAOs. For this purpose,
   ! occupied is greated than 1/14. See ROBY.
      type(ATOM_TYPE), IN :: self
      REAL, optional, IN :: tol
      INT :: res
      REAL :: eps
   ENSURE(allocated(self%NAO_occupations),"ATOM:no_of_occupied_NAOs ... no NAO occupations")
      eps = ROBY_OCCUPIED_ANO_CUTOFF
      if (present(tol)) eps = tol
      res = count(self%NAO_occupations>=eps)
   end function

   PURE function no_of_occupied_NOs(self,axiskind,tol) result (res)
   ! Returns the number of non-zero occupied natural orbitals. For this purpose,
   ! zero is defined to be "tol" if present, or TOL(7) otherwise
      type(ATOM_TYPE), IN :: self
      STR(len=*), optional, IN :: axiskind
      REAL, optional, IN :: tol
      INT :: res
   ENSURE(allocated(self%NO_occ_nos),"ATOM:no_of_occupied_NOs ... no occupation numbers")
      res = no_of_occupied_(self%NO_occ_nos,axiskind,tol)
   end function

   pure function has_NAO_matrices(self) result (res)
   ! Return TRUE if the NAOs exists for the atom.
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = allocated(self%NAOs) AND allocated(self%NAO_occupations)
   end function

   pure function has_ANO_matrices(self) result (res)
   ! Return TRUE if the ANOs exists for the atom.
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = allocated(self%NOs) AND allocated(self%NO_occ_nos)
   end function

!  ================
!  Symmetry methods
!  ================

   PURE subroutine symmetrize_0(self,mat,pointgroup)
   ! Symmetrize a matrix "mat" using "pointgroup"
      type(ATOM_TYPE), IN :: self
      MAT(REAL,:,:), INOUT :: mat
      type(POINTGROUP_TYPE), IN :: pointgroup
      MAT(REAL,:,:), allocatable :: sym,W
      MAT(REAL,:,:), allocatable :: tra,trb
      INT :: n_bf,n_shell
      INT :: n,a,b,na,nb
      INT :: fa,fb,la,lb
   ENSURE(is_square_(mat),"ATOM:symmetrize_0 ... non-square matrix")
   ENSURE(size(mat,1)==self%basis%n_bf,"ATOM:symmetrize_0 ... incorrectly dimensioned matrix")
   ENSURE(allocated(self%first_basis_fn_for_shell),"ATOM:symmetrize_0 ... no first_basis_fn_for_shell")
   ENSURE(allocated(self%last_basis_fn_for_shell),"ATOM:symmetrize_0 ... no last_basis_fn_for_shell")
   ENSURE(allocated(self%angular_moment_for_shell),"ATOM:symmetrize_0 ... no angular_moment_for_shell")

      ! The following code is inherited from ATOM
      n_bf = self%basis%n_bf
      n_shell = self%basis%n_shell
      call create_(sym,n_bf,n_bf)
      sym = ZERO
      do n = 1,pointgroup%order
         do a = 1,n_shell
            tra = xyz_mx_(pointgroup,n,self%angular_moment_for_shell(a))
            fa = self%first_basis_fn_for_shell(a)
            la = self%last_basis_fn_for_shell(a)
            na = la-fa+1
            do b = 1,n_shell
               trb = xyz_mx_(pointgroup,n,self%angular_moment_for_shell(b))
               fb = self%first_basis_fn_for_shell(b)
               lb = self%last_basis_fn_for_shell(b)
               nb = lb-fb+1
               call create_(W,na,nb)
               call to_product_of_(W,tra,mat(fa:la,fb:lb))
               call plus_product_of_(sym(fa:la,fb:lb),W,trb,transpose_b=TRUE)
               call destroy_(W)
            end do
         end do
      end do

      ! Average
      mat = sym/REALIFY(pointgroup%order)

      ! Clean up
      call destroy_(sym)
   end subroutine

   subroutine spherically_average(self,mat,is_spherical)
   ! Replace "mat", a density-like matrix over this atom's basis, by its
   ! average over all rotations, so that it is spherical. Set "is_spherical"
   ! if the basis is spherical. A point group cannot do this beyond p: "oh"
   ! leaves d-d blocks cubic, and "ih" fails from f-f on. So the average is
   ! over a grid of z-y-z Euler angles, exact for the angular components up
   ! to L = 2 l_max that products of the shells contain: L+1 equally spaced
   ! alpha and gamma, and L/2+1 Gauss-Legendre points in cos(beta).
      type(ATOM_TYPE), IN :: self
      MAT(REAL,:,:), INOUT :: mat
      BIN, IN :: is_spherical
      VEC(INT,:), allocatable :: first,last,momentum
      type(QUADRATURE_TYPE), allocatable :: q
      MAT3(REAL,:,:,:), allocatable :: R,dtr,ftr,gtr
      VEC(REAL,:), allocatable :: wt
      MAT(REAL,:,:), allocatable :: sym,W,tra,trb
      INT :: l_max,L,n_ag,n_b,n_rot,i,j,k,n,a,b,na,nb,fa,fb,la,lb
      REAL :: alpha,beta,gamma
   ENSURE(is_square_(mat),"ATOM:spherically_average ... non-square matrix")
   ENSURE(size(mat,1)==self%basis%n_bf,"ATOM:spherically_average ... incorrectly dimensioned matrix")
      call set_shell_limits_(self,first,last,momentum)
      l_max = maxval(momentum)
      DIE_IF(l_max>4,"ATOM:spherically_average ... h functions or higher are not done")

      ! The rotations and their weights
      L = 2*l_max
      n_ag = L+1
      n_b = L/2+1
      n_rot = n_ag*n_b*n_ag
      call create_(q)
      call set_kind_(q,"gauss_legendre")
      call set_n_pts_(q,n_b)
      call set_quadrature_points_(q)
      call create_(R,3,3,n_rot)
      call create_(wt,n_rot)
      n = 0
      do i = 1,n_ag
         alpha = TWO*PI*(i-1)/n_ag
         do j = 1,n_b
            beta = acos(q%pts(j))
            do k = 1,n_ag
               gamma = TWO*PI*(k-1)/n_ag
               n = n+1
               call to_euler_rotation_mx_(R(:,:,n),alpha,beta,gamma)
               wt(n) = q%wts(j)/(TWO*n_ag*n_ag)
            end do
         end do
      end do
      call destroy_(q)

      ! Representation matrices for d, f and g shells
      if (l_max>=2) dtr = d_xyz_rep_matrices_for_(R,is_spherical)
      if (l_max>=3) ftr = f_xyz_rep_matrices_for_(R,is_spherical)
      if (l_max>=4) gtr = g_xyz_rep_matrices_for_(R,is_spherical)

      ! Average
      call create_(sym,self%basis%n_bf,self%basis%n_bf)
      sym = ZERO
      do n = 1,n_rot
         do a = 1,self%basis%n_shell
            select case (momentum(a))
            case (0); call create_(tra,1,1); tra = ONE
            case (1); tra = R(:,:,n)
            case (2); tra = dtr(:,:,n)
            case (3); tra = ftr(:,:,n)
            case (4); tra = gtr(:,:,n)
            end select
            fa = first(a)
            la = last(a)
            na = la-fa+1
            do b = 1,self%basis%n_shell
               select case (momentum(b))
               case (0); call create_(trb,1,1); trb = ONE
               case (1); trb = R(:,:,n)
               case (2); trb = dtr(:,:,n)
               case (3); trb = ftr(:,:,n)
               case (4); trb = gtr(:,:,n)
               end select
               fb = first(b)
               lb = last(b)
               nb = lb-fb+1
               call create_(W,na,nb)
               call to_product_of_(W,tra,mat(fa:la,fb:lb))
               W = wt(n)*W
               call plus_product_of_(sym(fa:la,fb:lb),W,trb,transpose_b=TRUE)
               call destroy_(W)
               call destroy_(trb)
            end do
            call destroy_(tra)
         end do
      end do
      mat = sym

      ! Clean up
      call destroy_(sym)
      call destroy_(wt)
      call destroy_(gtr)
      call destroy_(ftr)
      call destroy_(dtr)
      call destroy_(R)
      call destroy_(momentum)
      call destroy_(last)
      call destroy_(first)
   end subroutine

   PURE subroutine symmetrize_1(self,mat,pointgroup)
   ! Symmetrize a matrix "mat" using "pointgroup"
      type(ATOM_TYPE), IN :: self
      MAT(CPX,:,:), INOUT :: mat
      type(POINTGROUP_TYPE), IN :: pointgroup
      MAT(CPX,:,:), allocatable :: sym,W
      MAT(REAL,:,:), allocatable :: tra,trb
      INT :: n_bf,n_shell
      INT :: n,a,b,na,nb
      INT :: fa,fb,la,lb
   ENSURE(is_square_(mat),"ATOM:symmetrize_1 ... non-square matrix")
   ENSURE(size(mat,1)==self%basis%n_bf,"ATOM:symmetrize_1 ... incorrectly dimensioned matrix")
   ENSURE(allocated(self%first_basis_fn_for_shell),"ATOM:symmetrize_1 ... no first_basis_fn_for_shell")
   ENSURE(allocated(self%last_basis_fn_for_shell),"ATOM:symmetrize_1 ... no last_basis_fn_for_shell")
   ENSURE(allocated(self%angular_moment_for_shell),"ATOM:symmetrize_1 ... no angular_moment_for_shell")

      ! The following code is inherited from ATOM
      n_bf = self%basis%n_bf
      n_shell = self%basis%n_shell
      call create_(sym,n_bf,n_bf)
      sym = ZERO
      do n = 1,pointgroup%order
         do a = 1,n_shell
            tra = xyz_mx_(pointgroup,n,self%angular_moment_for_shell(a))
            fa = self%first_basis_fn_for_shell(a)
            la = self%last_basis_fn_for_shell(a)
            na = la-fa+1
            do b = 1,n_shell
               trb = xyz_mx_(pointgroup,n,self%angular_moment_for_shell(b))
               fb = self%first_basis_fn_for_shell(b)
               lb = self%last_basis_fn_for_shell(b)
               nb = lb-fb+1
               call create_(W,na,nb)
               call to_product_of_(W,tra,mat(fa:la,fb:lb))
               call plus_product_of_(sym(fa:la,fb:lb),W,trb,transpose_b=TRUE)
               call destroy_(W)
            end do
         end do
      end do

      ! Average
      mat = sym/REALIFY(pointgroup%order)

      ! Clean up
      call destroy_(sym)
   end subroutine


!  Bond distances and bonding

   pure function distance_to(self,that) result (res)
   ! Return the distance between "self" and "that" other atom.
      type(ATOM_TYPE), IN :: self
      type(ATOM_TYPE), IN :: that
      REAL :: res
      res = bond_distance_to_(self,that)
   end function

   pure function bond_distance_to(self,that) result (res)
   ! Return the distance between "self" and "that" other atom.
      type(ATOM_TYPE), IN :: self
      type(ATOM_TYPE), IN :: that
      REAL :: res
      VEC(REAL,3) :: del
      del = that%position-self%position
      res = norm2(del)
   end function

   pure function is_nearby_to(self,that,dist) result (res)
   ! Return TRUE if atom "self" and "that" atom are nearby 
   ! i.e. within length "dist".
      type(ATOM_TYPE), IN :: self
      type(ATOM_TYPE), IN :: that
      REAL, IN :: dist
      BIN :: res
      VEC(REAL,3) :: tmp
      REAL :: r2
      tmp = self%position-that%position
      tmp = abs(tmp)
      res = FALSE
      if (tmp(1)>dist) return
      if (tmp(2)>dist) return
      if (tmp(3)>dist) return
      r2 = dot_product(tmp,tmp)
      res = r2<dist*dist
   end function

   pure function is_bonded_to(self,that,range_factor) result (res)
   ! Return true if "self" is bonded to atom "that". 
   ! "range_factor" is the distance range around the 
   ! covalent radii sum where the atoms are still
   ! regarded as covalently bonded. This is the CCDC 
   ! method. Radii from  Brun et al (2011) Struct. 
   ! Sci 67 p. 333-49.
      type(ATOM_TYPE), IN :: self
      type(ATOM_TYPE), IN :: that
      REAL, optional, IN :: range_factor
      BIN :: res
      REAL :: dx,dy,dz,r2,t
      REAL :: bond,bmin,bmax
      INT :: Za,Zb,as,bs
      Za = self%atomic_number
      Zb = that%atomic_number
      res = FALSE
      if (Za<1) return
      if (Zb<1) return
      if (Za>size(covalent_radii_ccdc)) return
      if (Zb>size(covalent_radii_ccdc)) return
      as = self%site_disorder_group
      bs = that%site_disorder_group
      if (as*bs>0 AND as/=bs) return
      t = atom_bonded_range_factor
      if (present(range_factor)) t = range_factor
      bond = covalent_radius_ccdc_(self)+covalent_radius_ccdc_(that)
      bmin = max(bond-t,ZERO)
      bmax = bond+t

      ! For HH, nothing closer than 0.7A
      if (Za==1 AND Zb==1) bmin = 0.7d0*BOHR_PER_ANGSTROM
      dx = abs(self%position(1)-that%position(1))
      dy = abs(self%position(2)-that%position(2))
      dz = abs(self%position(3)-that%position(3))
      if (dx>bmax) return
      if (dy>bmax) return
      if (dz>bmax) return
      r2 = dx*dx+dy*dy+dz*dz
      res = r2<bmax*bmax AND r2>bmin*bmin
   end function

   pure function is_vdw_bonded_to(self,that,range_factor,vdw_range_pc) result (res)
   ! Return true if "self" is VDW bonded to "that" atom. 
   ! Atoms covalently bonded are not regarded VDW bonded. 
   ! "range_factor" is the distance range around the 
   ! covalent radii sum where the atoms are still
   ! regarded as covalently bonded. "vdw_range_pc" is the 
   ! *percentage* increase in the vdw radius sum to be 
   ! tolerated so that atoms are vdw bonded (default 10%). 
      type(ATOM_TYPE), IN :: self
      type(ATOM_TYPE), IN :: that
      REAL, optional, IN :: range_factor
      REAL, optional, IN :: vdw_range_pc
      BIN :: res
      REAL :: dx,dy,dz,r2,t
      REAL :: bond,bmin,bmax
      INT :: Za,Zb,as,bs
   ! ag,bg :: INT
      BIN :: cov
      Za = self%atomic_number
      Zb = that%atomic_number
      res = FALSE
      if (Za<1) return
      if (Zb<1) return
      if (Za>size(vdw_radii_ccdc)) return
      if (Zb>size(vdw_radii_ccdc)) return
      as = self%site_disorder_group
      bs = that%site_disorder_group
      if (as*bs>0 AND as==bs) return

   ! This does not work for 1 group!
   ! ag = self.group
   ! bg = that.group
   ! if (ag*bg>0 AND ag==bg)    return

      ! Is it covalently bonded?
      ! WARNING: must be the same as .is_bonded_to
      t = atom_bonded_range_factor
      if (present(range_factor)) t = range_factor
      bond = covalent_radius_ccdc_(self)+covalent_radius_ccdc_(that)
      bmin = max(bond-t,ZERO)
      bmax = bond+t

      ! For HH, nothing closer than 0.7A
      if (Za==1 AND Zb==1) bmin = 0.7d0*BOHR_PER_ANGSTROM
      dx = abs(self%position(1)-that%position(1))
      dy = abs(self%position(2)-that%position(2))
      dz = abs(self%position(3)-that%position(3))

      ! Can't be vdw if covalent
      r2 = dx*dx+dy*dy+dz*dz
      cov = r2<bmax*bmax AND r2>bmin*bmin
      if (cov) return

      ! Still here? Now check if VDW bonded
      t = ONE+TOL(2)*atom_vdw_bonded_range_pc
      if (present(vdw_range_pc)) t = ONE+TOL(2)*vdw_range_pc
      bond = vdw_radius_ccdc_(self)+vdw_radius_ccdc_(that)
      bmax = bond*t
      if (dx>bmax) return
      if (dy>bmax) return
      if (dz>bmax) return

      ! Finally ...
      r2 = dx*dx+dy*dy+dz*dz
      res = r2<bmax*bmax
   end function

   pure function minimum_basis_exponent(self) result (res)
   ! Return the minimum exponent in the basis.
      type(ATOM_TYPE), IN :: self
      REAL :: res
      res = ZERO
      if (allocated(self%coppensbasis)) then; res = min_exponent_(self%coppensbasis%orbital)
      else if (allocated(self%slaterbasis)) then; res = min_exponent_(self%slaterbasis%shell)
      else if (allocated(self%basis)) then; res = min_exponent_(self%basis%shell)
      end if
   end function

   pure function r_max(self,cutoff) result (res)
   ! Return the distance "r_max" at which the basis function with the lowest
   ! exponent is less than the value "cutoff".
      type(ATOM_TYPE), IN :: self
      REAL, IN :: cutoff
      REAL :: res
      if (NOT allocated(self%basis)) then; res = ZERO
      else; res = r_max_(self%basis,cutoff)
      end if
   end function

   pure function r2_max(self,cutoff) result (res)
   ! Return the squared distance "r2_max" at which the basis function with the
   ! lowest exponent is less than the value "cutoff".
      type(ATOM_TYPE), IN :: self
      REAL, IN :: cutoff
      REAL :: res
      if (NOT allocated(self%basis)) then; res = ZERO
      else; res = r2_max_(self%basis,cutoff)
      end if
   end function

   elemental function covalent_radius_ccdc(self) result (res)
   ! Returns the CCDC covalent radius for this atom
      type(ATOM_TYPE), IN :: self
      REAL :: res
      if (self%atomic_number<1) then; res = ZERO
      else if (self%atomic_number>110) then; res = ZERO
      else; res = covalent_radii_ccdc(self%atomic_number)*BOHR_PER_ANGSTROM
      end if
   end function

   elemental function vdw_radius_ccdc(self) result (res)
   ! Returns the CCDC vdw radius for this atom
      type(ATOM_TYPE), IN :: self
      REAL :: res
      if (self%atomic_number<1) then; res = ZERO
      else if (self%atomic_number>110) then; res = ZERO
      else; res = vdw_radii_ccdc(self%atomic_number)*BOHR_PER_ANGSTROM
      end if
   end function


!  Properties

   pure function has_dipole(self) result (res)
   ! Return TRUE if the atomic dipole is nonzero.
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = NOT is_zero_(self%dipole)
   end function

   PURE function has_polarisability(self) result (res)
   ! Return TRUE if the atomic dipole is nonzero.
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = NOT is_zero_(self%charge_polarisability) OR NOT is_zero_(self%dipole_polarisability)
   end function

   pure function has_recognised_label(self) result (res)
   ! Return TRUE if the label corresponds to a recognised chemical element.
      type(ATOM_TYPE), IN :: self
      BIN :: res
      STR(len=STR_SIZE) :: label,symbol
      INT :: lensym
      BIN :: error
      label = self%label
      if (is_int_(label)) then

         ! The label must be the atomic number
         res = TRUE
      else

         ! First part of the label is the element symbol
         lensym = index_of_nonalphabetical_(label)-1
         error = lensym>2 OR lensym==0
         if (error) then
            res = FALSE
            return
         end if
         symbol = label(1:lensym)
         call to_upper_case_(symbol(1:1))
         call to_lower_case_(symbol(2:2))
         if (symbol=="D" OR symbol=="T" OR symbol(1:2)=="El") then
            res = TRUE
         else if (any(element_symbols(1:)==symbol(1:2))) then
            res = TRUE
         else
            res = FALSE
         end if
      end if
   end function


!  Dispersion coefficients and polarisabilities

   elemental function Spackman86_a_6_dispersion_coeff(self) result (res)
   ! Returns Spackman's a-coefficient for this atom
      type(ATOM_TYPE), IN :: self
      REAL :: res
      if (self%atomic_number<1) then; res = ZERO
      else if (self%atomic_number>110) then; res = ZERO
      else; res = Spackman86_a_6_disp_coeff(self%atomic_number)
      end if
   end function

   elemental function Spackman86_b_repulsion_coeff(self) result (res)
   ! Returns Spackman's b-coefficient for this atom
      type(ATOM_TYPE), IN :: self
      REAL :: res
      if (self%atomic_number<1) then; res = ZERO
      else if (self%atomic_number>110) then; res = ZERO
      else; res = Spackman86_b_exp_prefactor(self%atomic_number)
      end if
   end function

   elemental function Spackman86_c_repulsion_coeff(self) result (res)
   ! Returns Spackman's c-coefficient for this atom
      type(ATOM_TYPE), IN :: self
      REAL :: res
      if (self%atomic_number<1) then; res = ZERO
      else if (self%atomic_number>110) then; res = ZERO
      else; res = Spackman86_c_exp_exponent(self%atomic_number)
      end if
   end function

   elemental function Grimme06_a_6_dispersion_coeff(self) result (res)
   ! Return Grimme's a-coefficient for this atom
      type(ATOM_TYPE), IN :: self
      REAL :: res
      if (self%atomic_number<1) then; res = ZERO
      else if (self%atomic_number>110) then; res = ZERO
      else; res = Grimme06_a_6_disp_coeff(self%atomic_number)
      end if
   end function

   elemental function Grimme06_r_0_dispersion_coeff(self) result (res)
   ! Return Grimme's a-coefficient for this atom
      type(ATOM_TYPE), IN :: self
      REAL :: res
      if (self%atomic_number<1) then; res = ZERO
      else if (self%atomic_number>110) then; res = ZERO
      else; res = Grimme06_r_0_disp_coeff(self%atomic_number)
      end if
   end function

   elemental function Thakkar_atomic_dipole_polarizability(self,charged) result (res)
   ! Return Thakkar atomic dipole polarizability for this atom
      type(ATOM_TYPE), IN :: self
      REAL :: res
      BIN, IN, optional :: charged
      BIN :: use_charged
      use_charged = FALSE
      if (present(charged)) use_charged = charged
      if (self%atomic_number<1) then; res = ZERO
      else if (self%atomic_number>110) then; res = ZERO
      else
         if (use_charged) then; res = Charged_atomic_polarizibility(self%atomic_number)
         else; res = Thakkar_atomic_polarizability(self%atomic_number)
         end if
      end if
   end function


!  ====================
!  ADP inquiry methods
!  ====================

   PURE function has_zero_ADP_tensor(self) result (res)
   ! Return TRUE if there is a zero ADP tensor
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = is_zero_(self%ADP_tensor)
   end function

   PURE function has_nonzero_ADP_tensor(self) result (res)
   ! Return TRUE if there is a non-zero ADP tensor
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = NOT is_zero_(self%ADP_tensor)
   end function

   PURE function has_NPD_ADP(self) result (res)
   ! Return TRUE if the ADP is non-zero and non-positive definite.
      type(ATOM_TYPE), IN :: self
      BIN :: res
      MAT(REAL,3,3) :: evec
      VEC(REAL,3) :: eval
      res = FALSE
      if (NOT is_zero_(self%ADP_tensor)) then
         call diagonalize_Jacobi_(self%ADP_tensor,eval,evec)
         res = any(eval<ZERO)
      end if
   end function

   PURE function has_flat_ADP(self,ratio) result (res)
   ! Return TRUE if the ADP is flat i.e. the the max to
   ! the min eigenvalue is greater than "ratio" (or FOUR
   ! if not supplied).
      type(ATOM_TYPE), IN :: self
      REAL, IN, optional :: ratio
      BIN :: res
      MAT(REAL,3,3) :: evec
      VEC(REAL,3) :: eval
      REAL :: rat
      rat = FOUR
      if (present(ratio)) rat = ratio
      res = FALSE
      if (NOT is_zero_(self%ADP_tensor)) then
         call diagonalize_Jacobi_(self%ADP_tensor,eval,evec)
         res = abs(maxval(eval)/minval(eval))>rat
      end if
   end function

   PURE function ADP_principal_axis_ratio(self) result (res)
   ! Return the actual max/min ADP principal axis ratio
   ! (or 1000 if the min eigenvalue is zero).
      type(ATOM_TYPE), IN :: self
      REAL :: res
      MAT(REAL,3,3) :: evec
      VEC(REAL,3) :: eval
      REAL :: mineval,maxeval
      res = ZERO
      if (NOT is_zero_(self%ADP_tensor)) then
         call diagonalize_Jacobi_(self%ADP_tensor,eval,evec)
         maxeval = maxval(eval)
         mineval = minval(eval)
         res = 1000.0d0
         if (abs(mineval)>TOL(3)) res = maxeval/mineval
      end if
   end function


!  ====================
!  pADP inquiry methods
!  ====================

   pure function has_pADPs(self) result (res)
   ! Return TRUE if there are pADP's.
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = allocated(self%pADP_vector)
   end function

   pure function has_ADP3s(self) result (res)
   ! Return TRUE if there are third-order ADP's
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = has_pADPs_(self)
      if (NOT res) return
      res = res AND size(self%pADP_vector)>9
   end function

   pure function has_ADP4s(self) result (res)
   ! Return TRUE if there are fourth-order ADP's
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = has_pADPs_(self)
      if (NOT res) return
      res = res AND size(self%pADP_vector)>19
   end function

   pure function has_pADPs_and_errors(self) result (res)
   ! Return TRUE if there are pADP's *and* their errors
   ! Also check if the dimensions are equal.
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = allocated(self%pADP_vector) AND allocated(self%pADP_errors)
      if (NOT res) return
      res = size(self%pADP_vector)==size(self%pADP_errors)
   end function

   pure function has_ADP3s_and_errors(self) result (res)
   ! Return TRUE if there are third-order ADP's and errors
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = has_pADPs_and_errors_(self)
      if (NOT res) return
      res = res AND size(self%pADP_vector)>9
   end function

   pure function has_ADP4s_and_errors(self) result (res)
   ! Return TRUE if there are fourth-order ADP's and errors
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = has_pADPs_and_errors_(self)
      if (NOT res) return
      res = res AND size(self%pADP_vector)>19
   end function

   pure function has_only_ADP3s_and_errors(self) result (res)
   ! Return TRUE if there are *only* third-order ADP's and errors
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = has_pADPs_and_errors_(self)
      if (NOT res) return
      res = res AND size(self%pADP_vector)==19
   end function

   pure function has_only_ADP4s_and_errors(self) result (res)
   ! Return TRUE if there are *only* fourth-order ADP's and errors
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = has_pADPs_and_errors_(self)
      if (NOT res) return
      res = res AND size(self%pADP_vector)==34
   end function

   pure function has_anharmonic_ADPs(self) result (res)
   ! Return TRUE if there are anharmonic ADP's
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = has_only_ADP3s_and_errors_(self) OR has_only_ADP4s_and_errors_(self)
   end function

   pure function no_of_pADPs(self) result (res)
   ! Return the no. of positional/ADP parameters for refinement.
   ! NOTE: positions and second-order ADP's are always refined.
   ! i.e. there are always at least 9 pADPs, even if the pADP
   ! vector is not created.
      type(ATOM_TYPE), IN :: self
      INT :: res
      if (allocated(self%pADP_vector)) then; res = size(self%pADP_vector)
      else; res = 9
      end if
   end function

   PURE function tag_pADP_label(self,par_index) result (res)
   ! Return the unique tag with the positional-ADP label for parameter
   ! with index "par_index" e.g. "N13 Uxxy".
      type(ATOM_TYPE), IN :: self
      INT, IN :: par_index
      STR(len=STR_SIZE) :: res
   ENSURE(is_in_range_(par_index,[1,34]),"ATOM:tag_pADP_label ... par_index out of range")
      if (par_index<=3) then
         res = trim(self%tag)//" p"//trim(pADP_index_label(par_index))
      else
         res = trim(self%tag)//" U"//trim(pADP_index_label(par_index))
      end if
   end function

   PURE function pADP_label(par_index,form) result (res)
   ! Return the ADP label for parameter with index "par_index". The
   ! specific "form" of the ADP's may be given; the default is
   ! "xyz-repeated" e.g. "xxyy. For other forms see the code below.
      INT, IN :: par_index
      STR(len=*), optional, IN :: form
      STR(len=STR_SIZE) :: res
      STR(len=STR_SIZE) :: fmt
   ENSURE(is_in_range_(par_index,[1,34]),"ATOM:pADP_label ... par_index out of range")

      ! Set the symbol
      if (par_index<=3) then
         res = trim(pxyz_rep(par_index+1))
      else
         fmt = "underscore-xyz-repeated"
         if (present(form)) fmt = form
         res = " "
         select case (fmt)
         case ("underscore-123-repeated   "); res = "U_"//trim(p123_rep(par_index+1))
         case ("underscore-xyz-repeated   "); res = "U_"//trim(pxyz_rep(par_index+1))
         case ("underscore-xyz-power      "); res = "U_"//trim(pxyz_pow(par_index+1))
         case ("123-repeated-square-braces"); res = "U"//trim(b123_rep(par_index+1))
         case ("123-repeated              "); res = "U"//trim(p123_rep(par_index+1))
         case ("xyz-repeated              "); res = "U"//trim(pxyz_rep(par_index+1))
         case ("xyz-power                 "); res = "U"//trim(pxyz_pow(par_index+1))
         end select
      end if
   end function

   PURE function pADP_index_label(par_index,form) result (res)
   ! Return the ADP index label for parameter with index "par_index".
   ! The specific "form" of the ADP's may be given; the default is
   ! "xyz-repeated" e.g. "xxyy. For other forms see the code below.
      INT, IN :: par_index
      STR(len=*), optional, IN :: form
      STR(len=STR_SIZE) :: res
      STR(len=STR_SIZE) :: fmt
   ENSURE(is_in_range_(par_index,[1,34]),"ATOM:pADP_index_label ... par_index out of range")

      ! Set the symbol
      if (par_index<=3) then
         res = trim(pxyz_rep(par_index+1))
      else
         fmt = "xyz-repeated"
         if (present(form)) fmt = form
         res = " "
         select case (fmt)
         case ("underscore-123-repeated   "); res = "_"//trim(p123_rep(par_index+1))
         case ("underscore-xyz-repeated   "); res = "_"//trim(pxyz_rep(par_index+1))
         case ("underscore-xyz-power      "); res = "_"//trim(pxyz_pow(par_index+1))
         case ("123-repeated-square-braces"); res = trim(b123_rep(par_index+1))
         case ("123-repeated              "); res = trim(p123_rep(par_index+1))
         case ("xyz-repeated              "); res = trim(pxyz_rep(par_index+1))
         case ("xyz-power                 "); res = trim(pxyz_pow(par_index+1))
         end select
      end if
   end function

   PURE function ADP2_index_label(par_index,form) result (res)
   ! Return the ADP2 index label for parameter with index "par_index"
      INT, IN :: par_index
      STR(len=*), IN, optional :: form
      STR(len=STR_SIZE) :: res
   ENSURE(is_in_range_(par_index,[1,6]),"ATOM:ADP2_index_label ... par_index out of range")
      res = trim(pADP_index_label(par_index+3,form))
   end function

   PURE function ADP3_index_label(par_index,form) result (res)
   ! Return the ADP3 index label for parameter with index "par_index"
      INT, IN :: par_index
      STR(len=*), IN, optional :: form
      STR(len=STR_SIZE) :: res
   ENSURE(is_in_range_(par_index,[1,10]),"ATOM:ADP3_index_label ... par_index out of range")
      res = trim(pADP_index_label(par_index+9,form))
   end function

   PURE function ADP4_index_label(par_index,form) result (res)
   ! Return the ADP4 index label for parameter with index "par_index"
      INT, IN :: par_index
      STR(len=*), IN, optional :: form
      STR(len=STR_SIZE) :: res
   ENSURE(is_in_range_(par_index,[1,15]),"ATOM:ADP4_index_label ... par_index out of range")
      res = trim(pADP_index_label(par_index+19,form))
   end function

   PURE function ADP_label(par_index,form) result (res)
   ! Return the ADP label for parameter with index "par_index".
   ! Higher order indices can be obtained assuming they follow on in
   ! the usual pADP/gaussian lexical order.
      INT, IN :: par_index
      STR(len=*), IN, optional :: form
      STR(len=STR_SIZE) :: res
   ENSURE(is_in_range_(par_index,[1,31]),"ATOM:ADP_label ... par_index out of range")
      res = trim(pADP_label(par_index+3,form))
   end function

   PURE function ADP3_label(par_index,form) result (res)
   ! Return the ADP3 label for parameter with index "par_index"
      INT, IN :: par_index
      STR(len=*), IN, optional :: form
      STR(len=STR_SIZE) :: res
   ENSURE(is_in_range_(par_index,[1,10]),"ATOM:ADP3_label ... par_index out of range")
      res = trim(pADP_label(par_index+9,form))
   end function

   PURE function ADP4_label(par_index,form) result (res)
   ! Return the ADP4 label for parameter with index "par_index"
      INT, IN :: par_index
      STR(len=*), IN, optional :: form
      STR(len=STR_SIZE) :: res
   ENSURE(is_in_range_(par_index,[1,15]),"ATOM:ADP4_label ... par_index out of range")
      res = trim(pADP_label(par_index+19,form))
   end function


!  =========
!  Invarioms
!  =========

   PURE function allred_rochow_en(self) result (res)
   ! Returns the Allred-Rochow EN for this atom
      type(ATOM_TYPE), IN :: self
      REAL :: res
      if (self%atomic_number<0) then; res = ZERO
      else if (self%atomic_number>82) then; res = 1.0d0
      else; res = allred_rochow_electronegs(self%atomic_number)*0.01d0
      end if
   end function

   PURE function invariom_covalent_radius(self) result (res)
   ! Returns the covalent radius for this atom
      type(ATOM_TYPE), IN :: self
      REAL :: res
      if (self%atomic_number<0) then; res = ZERO
      else if (self%atomic_number>109) then; res = 1.0d0
      else; res = covalent_radii_invariom(self%atomic_number)*0.01d0
      end if
   end function

   PURE subroutine get_invariom_rotation(U,actual,reference,L,fail)
   ! Returns the invariom rotation matrix "U" which matches
   ! coordinates "reference" to "actual" in a least squares sense.
   ! Return the mean fitting error "L" or else "fail"  for failure.
      MAT(REAL,:,:), OUT :: U
      MAT(REAL,:,:), IN :: actual
      MAT(REAL,:,:), IN :: reference
      REAL, OUT :: L
      BIN, OUT :: fail
      MAT(REAL,:,:), allocatable :: U0,X,Rd
      INT :: d,n,p,q,i,iteration
      REAL :: val
   ENSURE(is_square_(U),"ATOM:get_invariom_rotation ... U must be square")
   ENSURE(size(U)==size(actual,2),"ATOM:get_invariom_rotation ... U incompatible with actual")
   ENSURE(size(reference,2)==size(actual,2),"ATOM:get_invariom_rotation ... reference incompatible with actual")

      ! Set dimension, number of points to fit
      d = size(U,1)
      n = size(reference,2)

      ! Set minimum L value
      L = ZERO

      ! Start with U being unit matrix
      call to_unit_mx_(U)

      ! Create antisymmetric matrix X, temporary rotation U
      call create_(X,d,d)
      call create_(U0,d,d)
      call create_(Rd,size(reference,1),size(reference,2))

      ! Repeatedly update U until converged
      iteration = 0
      fail = FALSE
      do
         iteration = iteration+1

         ! Rotate actual positions
         call to_product_of_(Rd,U,actual,transpose_A=TRUE)

         ! Get the derivative of L wrt. X_pq
         do p = 1,d
            do q = 1,p
               val = ZERO
               do i = 1,n
                  val = val+Rd(p,i)*reference(q,i)-Rd(q,i)*reference(p,q)
               end do
               val = -TWO*val
               X(p,q) = val
               X(q,p) = -val
            end do
            X(p,p) = ZERO
         end do

         ! Get maximum gradient
         val = maxval(abs(X))

         ! Exit if gradient converged or too many iteration
         if (val<TOL(4)) exit
         fail = iteration==1000
         if (fail) exit

         ! Otherwise scale X so the maximum value is less than 0.1
         val = TOL(1)/val
         X = X*val

         ! Exponentiate X
         call exponentiate_to_(X,U0)

         ! Update U
         call to_product_of_(X,U,U0)
         U = X
      end do

      ! Clean up
      call destroy_(Rd)
      call destroy_(U0)
      call destroy_(X)

      ! If failed, return, otherwise calculate L
      if (fail) return
      call create_(Rd,size(reference,1),size(reference,2))
      call to_product_of_(Rd,U,reference)
      L = ZERO
      do i = 1,d
         L = L+dot_product(actual(:,i),actual(:,i))+dot_product(reference(:,i),reference(:,i))-TWO*dot_product(actual(:,i),Rd(:,i))
      end do
      L = sqrt(L)/d
      call destroy_(Rd)
   end subroutine


!  =============================
!  ADP density plotting routines
!  =============================

   PURE subroutine make_ADP2_grid(self,g,pt)
   ! Make the effective ADP for a series of (Nx3) points "pt" and put
   ! the values into the grid vector "g".
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: g
      MAT(REAL,:,:), IN :: pt
      VEC(REAL,3) :: u,eval
      MAT(REAL,3,3) :: LL
      INT :: n_pt,i
      REAL :: det,fac
   ENSURE(NOT is_zero_(self%ADP_tensor),"ATOM:make_ADP2_grid ... no ADPs")
   ENSURE(size(pt,2)==3,"ATOM:make_ADP2_grid ... pt, dim2 is not 3")
   ENSURE(size(pt,1)==size(g,1),"ATOM:make_ADP2_grid ... pt and g, inconsistent")

      ! Get ADP principal axes
   ! .ADP_tensor.solve_symmetric_eigenproblem(eval,LL)
      call diagonalize_Jacobi_(self%ADP_tensor,eval,LL)

      ! Harmonic part. Note: U2^{-1} is the matrix for the PDF
      ! in cartesian coordinates.
      eval = ONE/eval
      det = product(eval)
      fac = sqrt(det/(TWO*PI)**3)
      n_pt = size(g)
      do i = 1,n_pt
         u = pt(i,:)-self%position
         u = matmul(u,LL)
         g(i) = fac*exp(-HALF*sum(u*eval*u))
      end do
   end subroutine

   PURE subroutine make_ADP2_exponent_grid(self,g,pt)
   ! Make the effective ADP2 PDF exponents for a series of (Nx3)
   ! points "pt" and put the values into the grid vector "g".
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: g
      MAT(REAL,:,:), IN :: pt
      VEC(REAL,3) :: u,eval
      MAT(REAL,3,3) :: LL
      INT :: n_pt,i
      REAL :: det,fac,top
   ENSURE(NOT is_zero_(self%ADP_tensor),"ATOM:make_ADP2_exponent_grid ... no ADPs")
   ENSURE(size(pt,2)==3,"ATOM:make_ADP2_exponent_grid ... pt, dim2 is not 3")
   ENSURE(size(pt,1)==size(g,1),"ATOM:make_ADP2_exponent_grid ... pt and g, inconsistent")

      ! Get ADP principal axes
   ! .ADP_tensor.solve_symmetric_eigenproblem(eval,LL)
      call diagonalize_Jacobi_(self%ADP_tensor,eval,LL)

      ! Harmonic part. Note: U2^{-1} is the matrix for the PDF
      ! in cartesian coordinates.
      eval = ONE/eval
      det = product(eval)
      fac = sqrt(det/(TWO*PI)**3)
      n_pt = size(g)
      do i = 1,n_pt
         u = pt(i,:)-self%position
         u = matmul(u,LL)
         top = -HALF*sum(u*eval*u)
         g(i) = top
      end do
   end subroutine

   PURE subroutine make_ADP_grid(self,g,pt,unit_cell)
   ! Make the ADP PDF values for a series of (Nx3) points "pt" and put
   ! the values into the grid vector "g". Supply "unit_cell" for
   ! reciprocal matrix, for the anharmonic constants.
   ! See Coppens, International Tables for Crystlography vol B p. 22
   ! equations (1.2.12.3) and (1.2.12.4)
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: g
      MAT(REAL,:,:), IN :: pt
      type(UNIT_CELL_TYPE), IN :: unit_cell
      VEC(INT,3) :: n
      VEC(REAL,3) :: u,eval
      MAT(INT,3,3) :: delta
      MAT(REAL,3,3) :: LL
      MAT3(REAL,3,3,3) :: U3
      MAT4(REAL,3,3,3,3) :: U4
      INT :: n_pt,i,j,k,l,m
      REAL :: det,top,fac,H
      VEC(REAL,:), allocatable :: P0,g3,g4
   ENSURE(NOT is_zero_(self%ADP_tensor),"ATOM:make_ADP_grid ... no ADPs")
   ENSURE(size(pt,2)==3,"ATOM:make_ADP_grid ... pt, dim2 is not 3")
   ENSURE(size(pt,1)==size(g,1),"ATOM:make_ADP_grid ... pt and g, inconsistent")

      ! Harmonic grid
      n_pt = size(g)
      call create_(P0,n_pt)

      ! Get ADP principal axes
   ! .ADP_tensor.solve_symmetric_eigenproblem(eval,LL)
      call diagonalize_Jacobi_(self%ADP_tensor,eval,LL)

      ! Harmonic part. Note: U2^{-1} is the matrix for the PDF
      ! in cartesian coordinates.
      eval = ONE/eval
      det = product(eval)
      fac = sqrt(det/(TWO*PI)**3)
      do i = 1,n_pt
         u = pt(i,:)-self%position
         u = matmul(u,LL)
         top = -HALF*sum(u*eval*u)
         P0(i) = fac*exp(top)
      end do
      g = P0
      if (has_ADP3s_and_errors_(self)) then

         ! Change to Coppens "c" coefficients
         call put_ADP3_vector_to_(self,U3)
         call change_basis_using_(U3,unit_cell%reciprocal_mx)
         call change_basis_using_(U3,LL)
         call to_unit_mx_(delta)
         call create_(g3,n_pt)
         g3 = 0
         do j = 1,3
            do k = 1,3
               do l = 1,3
                  n = delta(:,j)+delta(:,k)+delta(:,l)
                  do i = 1,n_pt
                     u = pt(i,:)-self%position
                     u = matmul(u,LL)
                     H = hermite_polynomial_prob_(u,n)
                     g3(i) = g3(i)+U3(j,k,l)*H
                  end do
               end do
            end do
         end do
         g = g+P0*g3/SIX
         call destroy_(g3)
      end if
      if (has_ADP4s_and_errors_(self)) then

         ! Change to Coppens "c" coefficients
         call put_ADP4_vector_to_(self,U4)
         call change_basis_using_(U4,unit_cell%reciprocal_mx)
         call change_basis_using_(U4,LL)
         call to_unit_mx_(delta)
         call create_(g4,n_pt)
         g4 = 0
         do j = 1,3
            do k = 1,3
               do l = 1,3
                  do m = 1,3
                     n = delta(:,j)+delta(:,k)+delta(:,l)+delta(:,m)
                     do i = 1,n_pt
                        u = pt(i,:)-self%position
                        u = matmul(u,LL)
                        H = hermite_polynomial_prob_(u,n)
                        g4(i) = g4(i)+U4(j,k,l,m)*H
                     end do
                  end do
               end do
            end do
         end do
         g = g+P0*g4/(FOUR*SIX)
         call destroy_(g4)
      end if
      call destroy_(P0)
   end subroutine

   PURE subroutine make_ADP_exponent_grid(self,g,pt,unit_cell)
   ! Make the effective ADP PDF exponent values for a series of (Nx3)
   ! points "pt" and put the values into the grid vector "g". Supply
   ! "unit_cell" for reciprocal matrix, for the anharmonic constants.
   ! See Coppens, International Tables for Crystlography vol B p. 22
   ! equations (1.2.12.3) and (1.2.12.4)
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: g
      MAT(REAL,:,:), IN :: pt
      type(UNIT_CELL_TYPE), IN :: unit_cell
      VEC(INT,3) :: n
      VEC(REAL,3) :: u,eval
      MAT(INT,3,3) :: delta
      MAT(REAL,3,3) :: LL
      MAT3(REAL,3,3,3) :: U3
      MAT4(REAL,3,3,3,3) :: U4
      INT :: n_pt,i,j,k,l,m
      REAL :: det,top,fac,H
      VEC(REAL,:), allocatable :: P0,g3,g4
   ENSURE(NOT is_zero_(self%ADP_tensor),"ATOM:make_ADP_exponent_grid ... no ADPs")
   ENSURE(size(pt,2)==3,"ATOM:make_ADP_exponent_grid ... pt, dim2 is not 3")
   ENSURE(size(pt,1)==size(g,1),"ATOM:make_ADP_exponent_grid ... pt and g, inconsistent")

      ! Harmonic grid
      n_pt = size(g)
      call create_(P0,n_pt)

      ! Get ADP principal axes
   ! .ADP_tensor.solve_symmetric_eigenproblem(eval,LL)
      call diagonalize_Jacobi_(self%ADP_tensor,eval,LL)

      ! Harmonic part. Note: U2^{-1} is the matrix for the PDF
      ! in cartesian coordinates.
      eval = ONE/eval
      det = product(eval)
      fac = sqrt(det/(TWO*PI)**3)
      do i = 1,n_pt
         u = pt(i,:)-self%position
         u = matmul(u,LL)
         top = -HALF*sum(u*eval*u)
         P0(i) = fac*exp(top)
      end do
      g = P0
      if (has_ADP3s_and_errors_(self)) then

         ! Change to Coppens "c" coefficients
         call put_ADP3_vector_to_(self,U3)
         call change_basis_using_(U3,unit_cell%reciprocal_mx)
         call change_basis_using_(U3,LL)
         call to_unit_mx_(delta)
         call create_(g3,n_pt)
         g3 = 0
         do j = 1,3
            do k = 1,3
               do l = 1,3
                  n = delta(:,j)+delta(:,k)+delta(:,l)
                  do i = 1,n_pt
                     u = pt(i,:)-self%position
                     u = matmul(u,LL)
                     H = hermite_polynomial_prob_(u,n)
                     g3(i) = g3(i)+U3(j,k,l)*H
                  end do
               end do
            end do
         end do
         g = g+P0*g3/SIX
         call destroy_(g3)
      end if
      if (has_ADP4s_and_errors_(self)) then

         ! Change to Coppens "c" coefficients
         call put_ADP4_vector_to_(self,U4)
         call change_basis_using_(U4,unit_cell%reciprocal_mx)
         call change_basis_using_(U4,LL)
         call to_unit_mx_(delta)
         call create_(g4,n_pt)
         g4 = 0
         do j = 1,3
            do k = 1,3
               do l = 1,3
                  do m = 1,3
                     n = delta(:,j)+delta(:,k)+delta(:,l)+delta(:,m)
                     do i = 1,n_pt
                        u = pt(i,:)-self%position
                        u = matmul(u,LL)
                        H = hermite_polynomial_prob_(u,n)
                        g4(i) = g4(i)+U4(j,k,l,m)*H
                     end do
                  end do
               end do
            end do
         end do
         g = g+P0*g4/(FOUR*SIX)
         call destroy_(g4)
      end if

      ! Make g the effecvtive exponent
      g = log(g/fac)
      call destroy_(P0)
   end subroutine

   PURE subroutine make_AADP_PDF_correction_grid(self,g,pt)
   ! Make the anharmonic ADP correction to the PDF values (this are
   ! all the purely cubic and quartic terms, not including the unity
   ! factor) for a series of (Nx3) points "pt" and put the values into
   ! the grid vector "g". Supply "unit_cell" for reciprocal matrix.
   ! See Coppens, International Tables for Crystlography vol B p. 22
   ! equations (1.2.12.3) and (1.2.12.4)
   ! NOTE: these numbers are multiplied by 10^9
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: g
      MAT(REAL,:,:), IN :: pt
      VEC(INT,3) :: n
      VEC(REAL,3) :: u,eval
      MAT(INT,3,3) :: delta
      MAT(REAL,3,3) :: LL
      MAT3(REAL,3,3,3) :: U3
      MAT4(REAL,3,3,3,3) :: U4
      INT :: n_pt,i,j,k,l,m
      REAL :: H
      VEC(REAL,:), allocatable :: g3,g4
   ENSURE(NOT is_zero_(self%ADP_tensor),"ATOM:make_AADP_PDF_correction_grid ... no ADPs")
   ENSURE(has_ADP3s_and_errors_(self),"ATOM:make_AADP_PDF_correction_grid ... no third order ADPs")
   ENSURE(has_ADP4s_and_errors_(self),"ATOM:make_AADP_PDF_correction_grid ... no fourth order ADPs")
   ENSURE(size(pt,2)==3,"ATOM:make_AADP_PDF_correction_grid ... pt, dim2 is not 3")
   ENSURE(size(pt,1)==size(g,1),"ATOM:make_AADP_PDF_correction_grid ... pt and g, inconsistent")
      n_pt = size(g)

      ! Get ADP principal axes
   ! .ADP_tensor.solve_symmetric_eigenproblem(eval,LL)
      call diagonalize_Jacobi_(self%ADP_tensor,eval,LL)
      g = ZERO
      if (has_ADP3s_and_errors_(self)) then

         ! Change to principal axis system
         call put_ADP3_vector_to_(self,U3)
         call change_basis_using_(U3,LL)
         call to_unit_mx_(delta)
         call create_(g3,n_pt)
         g3 = 0
         do j = 1,3
            do k = 1,3
               do l = 1,3
                  n = delta(:,j)+delta(:,k)+delta(:,l)
                  do i = 1,n_pt
                     u = pt(i,:)-self%position
                     u = matmul(u,LL)
                     H = hermite_polynomial_prob_(u,n)
                     g3(i) = g3(i)+U3(j,k,l)*H
                  end do
               end do
            end do
         end do
         g = g3/SIX
         call destroy_(g3)
      end if
      if (has_ADP4s_and_errors_(self)) then

         ! Change to Coppens "c" coefficients
         call put_ADP4_vector_to_(self,U4)
         call change_basis_using_(U4,LL)
         call to_unit_mx_(delta)
         call create_(g4,n_pt)
         g4 = 0
         do j = 1,3
            do k = 1,3
               do l = 1,3
                  do m = 1,3
                     n = delta(:,j)+delta(:,k)+delta(:,l)+delta(:,m)
                     do i = 1,n_pt
                        u = pt(i,:)-self%position
                        u = matmul(u,LL)
                        H = hermite_polynomial_prob_(u,n)
                        g4(i) = g4(i)+U4(j,k,l,m)*H
                     end do
                  end do
               end do
            end do
         end do
         g = g+g4/(FOUR*SIX)
         call destroy_(g4)
      end if
      g = 1.0d+9*g
   end subroutine


!  =========================
!  Density plotting routines
!  =========================

   PURE subroutine make_ED_grid_0(self,density_grid,pt,occ)
   ! Make the electron "density_grid" on "pt" using ".natural orbitals" and
   ! the ".NO_occ_nos" vector.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: density_grid
      MAT(REAL,:,:), IN :: pt
      REAL, optional, IN :: occ
   ENSURE(size(density_grid)==size(pt,1),"ATOM:make_ED_grid_0 ... inconsistent number of points")
   ENSURE(is_one_of_(self%basis_kind,["gaussian","slater  ","coppens "]),"ATOM:make_ED_grid_0 ... unknwon .basis_kind, "//trim(self%basis_kind))
      select case (self%basis_kind)

      case ("gaussian")
         if (self%use_interpolator AND allocated(self%interpolator)) then
            call make_interpolated_density_(self,density_grid,pt,occ)
         else
            ENSURE(allocated(self%basis),"ATOM:make_ED_grid_0 ... no basis")
            ENSURE(allocated(self%NOs),"ATOM:make_ED_grid_0 ... no NOs")
            call make_ED_grid_r_(self,density_grid,pt,occ)
         end if

      case ("slater")
         ENSURE(allocated(self%slaterbasis),"ATOM:make_ED_grid_0 ... no slaterbasis")
         call make_ED_grid_(self%slaterbasis,density_grid,pt,self%position,occ)

      case ("coppens")
         ENSURE(allocated(self%coppensbasis),"ATOM:make_ED_grid_0 ... no coppensbasis")
         call make_ED_grid_(self%coppensbasis,density_grid,pt,self%position,occ)
      end select
   end subroutine

   PURE subroutine add_ED_grid_0(self,density_grid,pt,occ)
   ! Add the electron "density_grid" on "pt" using ".natural orbitals" and
   ! the ".NO_occ_nos" vector.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), INOUT :: density_grid
      MAT(REAL,:,:), IN :: pt
      REAL, optional, IN :: occ
   ENSURE(size(density_grid)==size(pt,1),"ATOM:add_ED_grid_0 ... inconsistent number of points")
   ENSURE(is_one_of_(self%basis_kind,["gaussian","slater  ","coppens "]),"ATOM:add_ED_grid_0 ... unknwon .basis_kind, "//trim(self%basis_kind))
      select case (self%basis_kind)

      case ("gaussian")
         if (self%use_interpolator AND allocated(self%interpolator)) then
            call add_interpolated_density_(self,density_grid,pt,occ)
         else
            ENSURE(allocated(self%basis),"ATOM:add_ED_grid_0 ... no basis")
            ENSURE(allocated(self%NOs),"ATOM:add_ED_grid_0 ... no natural orbitals")
            call add_density_grid_r_(self,density_grid,pt,occ)
         end if

      case ("slater")
         ENSURE(allocated(self%slaterbasis),"ATOM:add_ED_grid_0 ... no slaterbasis")
         call add_ED_grid_(self%slaterbasis,density_grid,pt,self%position,occ)

      case ("coppens")
         ENSURE(allocated(self%coppensbasis),"ATOM:add_ED_grid_0 ... no coppensbasis")
         call add_ED_grid_(self%coppensbasis,density_grid,pt,self%position,occ)
      end select
   end subroutine

   PURE subroutine make_ED_grid_r(self,grid,pt,occ)
   ! Make the density "grid" for the supplied points "pt" from
   ! restricted real natural orbitals. "occ" is an overall occupancy
   ! factor to scale the densities by, Wrongly labelled, I think.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: grid
      MAT(REAL,:,:), IN :: pt
      REAL, optional, IN :: occ
      VEC(REAL,:), allocatable :: NO
      INT :: n_occ,n
      BIN :: do_occ
   ENSURE(size(pt,2)==3,"ATOM:make_ED_grid_r ... wrong dimension for points array")
   ENSURE(size(grid)==size(pt,1),"ATOM:make_ED_grid_r ... inconsistent number of points")
   ENSURE(is_allocated_with_genre_(self%NOs,"r"),"ATOM:make_ED_grid_r ... no restricted NO's")
   ENSURE(is_allocated_with_genre_(self%NO_occ_nos,"r"),"ATOM:make_ED_grid_r ... no occupation numbers")

      ! Do occupation factor?
      do_occ = FALSE
      if (present(occ)) then
         if (NOT equals_(occ,ONE)) then
            do_occ = TRUE
         end if
      end if
      grid = ZERO  ! set to zero
      call create_(NO,size(pt,1))
      n_occ = no_of_occupied_NOs_(self)
      do n = 1,n_occ
         call make_orbital_grid_r_(self,NO,self%NOs%r(:,n),pt,self%position)
         grid = grid+self%NO_occ_nos%r(n)*NO*NO
      end do
      if (do_occ) grid = occ*grid
      call destroy_(NO)
   end subroutine

   PURE subroutine add_density_grid_r(self,grid,pt,occ)
   ! Add the density "grid" for the supplied points "pt" from
   ! restricted real natural orbitals
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), INOUT :: grid
      MAT(REAL,:,:), IN :: pt
      REAL, optional, IN :: occ
      VEC(REAL,:), allocatable :: NO
      INT :: n_occ,n
      BIN :: do_occ
   ENSURE(size(pt,2)==3,"ATOM:add_density_grid_r ... wrong dimension for points array")
   ENSURE(size(grid)==size(pt,1),"ATOM:add_density_grid_r ... inconsistent number of points")
   ENSURE(is_allocated_with_genre_(self%NOs,"r"),"ATOM:add_density_grid_r ... no restricted NO's")
   ENSURE(is_allocated_with_genre_(self%NO_occ_nos,"r"),"ATOM:add_density_grid_r ... no occupation numbers")

      ! Do occupation factor?
      do_occ = FALSE
      if (present(occ)) then
         if (NOT equals_(occ,ONE)) then
            do_occ = TRUE
         end if
      end if
      call create_(NO,size(pt,1))
      n_occ = no_of_occupied_NOs_(self)
      if (do_occ) then
         do n = 1,n_occ
            call make_orbital_grid_r_(self,NO,self%NOs%r(:,n),pt,self%position)
            grid = grid+occ*self%NO_occ_nos%r(n)*NO*NO
         end do
      else
         do n = 1,n_occ
            call make_orbital_grid_r_(self,NO,self%NOs%r(:,n),pt,self%position)
            grid = grid+self%NO_occ_nos%r(n)*NO*NO
         end do
      end if
      call destroy_(NO)
   end subroutine

   PURE subroutine make_ED_grid_1(self,grid,pt,D,occ)
   ! Make the density "grid" for the supplied points "pt" from a
   ! density matrix "D"
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: grid
      MAT(REAL,:,:), IN :: pt
      MAT(REAL,:,:), IN :: D
      REAL, optional, IN :: occ
      MAT(REAL,:,:), allocatable :: g
      VEC(REAL,:), allocatable :: W
      INT :: i
      BIN :: do_occ
   ENSURE(size(pt,2)==3,"ATOM:make_ED_grid_1 ... wrong dimension for points array")
   ENSURE(size(grid)==size(pt,1),"ATOM:make_ED_grid_1 ... inconsistent number of points")
   ENSURE(is_square_(D),"ATOM:make_ED_grid_1 ... D, not square")
   ENSURE(size(D,1)==no_of_basis_functions_(self%basis),"ATOM:make_ED_grid_1 ... D, wrong size")

      ! Do occupation factor?
      do_occ = FALSE
      if (present(occ)) then
         if (NOT equals_(occ,ONE)) then
            do_occ = TRUE
         end if
      end if
      call create_(W,size(D,1))
      call create_(g,size(pt,1),size(D,1))
      call make_AO_grid_(self,g,pt,self%position)
      do i = 1,size(pt,1)
         call to_product_of_(W,D,g(i,:),transpose_a=TRUE)
         grid(i) = sum(W*g(i,:))
      end do
      if (do_occ) grid = occ*grid
      call destroy_(W)
      call destroy_(g)
   end subroutine

   PURE subroutine add_ED_grid_1(self,grid,pt,D,occ)
   ! Add the density "grid" for the supplied points "pt" from a
   ! density matrix "D"
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), INOUT :: grid
      MAT(REAL,:,:), IN :: pt
      MAT(REAL,:,:), IN :: D
      REAL, optional, IN :: occ
      MAT(REAL,:,:), allocatable :: g
      VEC(REAL,:), allocatable :: W
      INT :: i
      BIN :: do_occ
   ENSURE(size(pt,2)==3,"ATOM:add_ED_grid_1 ... wrong dimension for points array")
   ENSURE(size(grid)==size(pt,1),"ATOM:add_ED_grid_1 ... inconsistent number of points")
   ENSURE(is_square_(D),"ATOM:add_ED_grid_1 ... D, not square")
   ENSURE(size(D,1)==no_of_basis_functions_(self%basis),"ATOM:add_ED_grid_1 ... D, wrong size")

      ! Do occupation factor?
      do_occ = FALSE
      if (present(occ)) then
         if (NOT equals_(occ,ONE)) then
            do_occ = TRUE
         end if
      end if
      call create_(W,size(D,1))
      call create_(g,size(pt,1),size(D,1))
      call make_AO_grid_(self,g,pt,self%position)
      if (do_occ) then
         do i = 1,size(pt,1)
            call to_product_of_(W,D,g(i,:),transpose_a=TRUE)
            grid(i) = grid(i)+occ*sum(W*g(i,:))
         end do
      else
         do i = 1,size(pt,1)
            call to_product_of_(W,D,g(i,:),transpose_a=TRUE)
            grid(i) = grid(i)+sum(W*g(i,:))
         end do
      end if
      call destroy_(W)
      call destroy_(g)
   end subroutine


