!  ========================
!  Orbital density routines
!  ========================

   PURE subroutine make_AO_grid(self,g,pt,pos)
   ! Evaluate the AO density grid "g" on a set of grid points "pt" for
   ! an atom at position "pos".
      type(ATOM_TYPE), IN :: self
      MAT(REAL,:,:), OUT :: g
      MAT(REAL,:,:), IN :: pt
      VEC(REAL,3), IN :: pos
      type(SHELL1_TYPE) :: sh
      INT :: n_shell,f,l,s
   ENSURE(allocated(self%basis),"ATOM:make_AO_grid ... no basis set")
   ENSURE(size(pt,1)==size(g,1),"ATOM:make_AO_grid ... pt and g, incompatible")
   ENSURE(no_of_basis_functions_(self%basis)==size(g,2),"ATOM:make_AO_grid ... pt and g, incompatible")
   ENSURE(size(pt,2)==3,"ATOM:make_AO_grid ... wrong size, pt")
      n_shell = no_of_shells_(self%basis)
      l = 0
      do s = 1,n_shell
         call set_(sh,self%basis%shell(s),pos)
         f = l+1
         l = f+sh%n_bf-1
         call make_grid_(sh,g(:,f:l),pt)
      end do
   end subroutine

   PURE subroutine make_orbital_grid_r_0(self,g,orb,pt,square)
   ! Evaluate the orbital density grid "g" for *one* AO-basis
   ! coefficient orbital vector "orb" on a set of grid points "pt" for
   ! an atom.  If "square" is present and TRUE, the square of the
   ! orbital density is returned.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: g
      VEC(REAL,:), IN :: orb
      MAT(REAL,:,:), IN :: pt
      BIN, optional, IN :: square
      call make_orbital_grid_r_(self,g,orb,pt,self%position,square)
   end subroutine

   PURE subroutine make_orbital_grid_r_1(self,g,orb,pt,pos,square)
   ! Evaluate the orbital density grid "g" for *one* AO-basis
   ! coefficient orbital vector "orb" on a set of grid points "pt" for
   ! an atom at position "pos". If "square" is present and TRUE, the
   ! square of the orbital density is returned.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: g
      VEC(REAL,:), IN :: orb
      MAT(REAL,:,:), IN :: pt
      VEC(REAL,3), IN :: pos
      BIN, optional, IN :: square
      BIN :: sq
      type(SHELL1_TYPE) :: sh
      MAT(REAL,:,:), allocatable :: sh_grid
      INT :: n_pt,n_shell,f,l,s
   ENSURE(allocated(self%basis),"ATOM:make_orbital_grid_r_1 ... no basis set")
   ENSURE(no_of_basis_functions_(self%basis)==size(orb),"ATOM:make_orbital_grid_r_1 ... incorrect size, orb")
   ENSURE(size(pt,2)==3,"ATOM:make_orbital_grid_r_1 ... wrong size, pt")
      sq = FALSE
      if (present(square)) sq = square
      n_pt = size(pt,1)
      n_shell = no_of_shells_(self%basis)
      g = ZERO
      l = 0
      do s = 1,n_shell
         call set_(sh,self%basis%shell(s),pos)
         f = l+1
         l = f+sh%n_bf-1
         call create_(sh_grid,n_pt,sh%n_bf)
         call make_grid_(sh,sh_grid,pt)
         call plus_product_of_(g,sh_grid,orb(f:l))
         call destroy_(sh_grid)
      end do
      if (sq) g = g*g
   end subroutine

   PURE subroutine make_orbital_grid_c(self,g,orb,pt,pos,square)
   ! Evaluate the orbital density grid "g" for *one* AO-basis coefficient
   ! orbital vector "orb" on a set of grid points "pt" for an atom at position
   ! "pos". If "square" is present and TRUE, the square of the orbital density
   ! is returned.
      type(ATOM_TYPE), IN :: self
      VEC(CPX,:), OUT :: g
      VEC(CPX,:), IN :: orb
      MAT(REAL,:,:), IN :: pt
      VEC(REAL,3), IN :: pos
      BIN, optional, IN :: square
      BIN :: sq
      type(SHELL1_TYPE) :: sh
      MAT(REAL,:,:), allocatable :: sh_grid
      INT :: n_pt,n_shell,f,l,s
   ENSURE(allocated(self%basis),"ATOM:make_orbital_grid_c ... no basis set")
   ENSURE(no_of_basis_functions_(self%basis)==size(orb),"ATOM:make_orbital_grid_c ... incorrect suize, orb")
   ENSURE(size(pt,2)==3,"ATOM:make_orbital_grid_c ... wrong size, pt")
      sq = FALSE
      if (present(square)) sq = square
      n_pt = size(pt,1)
      n_shell = no_of_shells_(self%basis)
      g = ZERO
      l = 0
      do s = 1,n_shell
         call set_(sh,self%basis%shell(s),pos)
         f = l+1
         l = f+sh%n_bf-1
         call create_(sh_grid,n_pt,sh%n_bf)
         call make_grid_(sh,sh_grid,pt)
         call plus_product_of_(g,sh_grid,orb(f:l))
         call destroy_(sh_grid)
      end do
      if (sq) g = conjg(g)*g
   end subroutine


!  =====================
!  Exponential densities
!  =====================

   PURE subroutine make_exponential_densities(self,res,pt,rho0)
   ! Return the exponential density values at "pt"s into "res"
   ! given the density "rho0" at R = 0.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: res
      MAT(REAL,:,:), IN :: pt
      REAL, IN :: rho0
      VEC(REAL,:), allocatable :: x,y,z,r2
      INT :: n_pt
   ENSURE(size(pt,2)==3,"ATOM:make_exponential_densities ... wrong dimension for pt array")
      n_pt = size(pt,1)
      call create_(x,n_pt)
      call create_(y,n_pt)
      call create_(z,n_pt)
      call create_(r2,n_pt)
      call make_displaced_pts_(self,x,y,z,r2,pt,n_pt)
      res = rho0*exp(-TWO*self%atomic_number*sqrt(r2))
   end subroutine

   PURE subroutine add_exponential_densities(self,res,pt,rho0)
   ! Add the exponential density values at a series of "pt"s to "res"
   ! given the density "rho0" at R = 0.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), INOUT :: res
      MAT(REAL,:,:), IN :: pt
      REAL, IN :: rho0
      VEC(REAL,:), allocatable :: x,y,z,r2
      INT :: n_pt
   ENSURE(size(pt,2)==3,"ATOM:add_exponential_densities ... wrong dimension for pt array")
      n_pt = size(pt,1)
      call create_(x,n_pt)
      call create_(y,n_pt)
      call create_(z,n_pt)
      call create_(r2,n_pt)
      call make_displaced_pts_(self,x,y,z,r2,pt,n_pt)
      res = res+rho0*exp(-TWO*self%atomic_number*sqrt(r2))
   end subroutine


!  ======================
!  Spherical density at R
!  ======================

   PURE function density_at_radius(self,R) result (res)
   ! Work out the electron density at radius "R". The kind of density
   ! is determined by .basis_kind, which could be e.g. "gaussian".
      type(ATOM_TYPE), IN :: self
      REAL, IN :: R
      REAL :: res
      VEC(REAL,1) :: grid
      MAT(REAL,1,3) :: pt
      res = ZERO
      select case (self%basis_kind)

      case ("gaussian")
         ENSURE(allocated(self%basis),"ATOM:density_at_radius ... no basis")
         pt(1,:) = self%position+[R,ZERO,ZERO]
         call make_ED_grid_r_(self,grid,pt)
         res = grid(1)

      case ("slater")
         ENSURE(allocated(self%slaterbasis),"ATOM:density_at_radius ... no slaterbasis")
         ENSURE(allocated(self%slaterbasis%shell),"ATOM:density_at_radius ... no slaterbasis shells")
         res = density_at_radius_(self%slaterbasis,R)

      case ("coppens")
         ENSURE(allocated(self%coppensbasis),"ATOM:density_at_radius ... no coppensbasis")
         ENSURE(allocated(self%coppensbasis%orbital),"ATOM:density_at_radius ... no coppensbasis orbital")
         res = density_at_radius_(self%coppensbasis,R)
      end select
   end function

   PURE function density_value_at_radius(R) result (res)
   ! Return the density values at the radial value "R".
   ! This assumes that the atomic density is spherical!
      REAL, IN :: R
      REAL :: res
      res = density_at_radius_(saved_self,R)
   end function


!  ============
!  Interpolator
!  ============

   pure function has_interpolator(self) result (res)
   ! Return TRUE if interplator is there
      type(ATOM_TYPE), IN :: self
      BIN :: res
      res = allocated(self%interpolator)
   end function

   subroutine make_interpolator(self,interpolator)
   ! Make the .interpolator for the atom density. If present,
   ! "interpolator" is used as a template to get the settings needed.
   ! NOTE: This is for a gaussian basis set; for slater or coppens
   ! bases use the interpolators stored in those bases.
      type(ATOM_TYPE), INOUT :: self
      type(INTERPOLATOR_TYPE), allocatable, optional :: interpolator
   ENSURE(self%basis_kind=="gaussian","ATOM:make_interpolator ... interpolation must be for a gaussian basis")

      ! Create a copy of the template if it exists
      if (present(interpolator)) then
         if (allocated(interpolator)) then
            call destroy_(self%interpolator)
            self%interpolator = interpolator
         end if
      end if

      ! If no template, create a default interpolator
      if (NOT allocated(self%interpolator)) call create_(self%interpolator)

      ! Set domain scale factor. May not be required.
      call set_domain_scale_factor_(self%interpolator,bragg_slater_radius_(self)*BOHR_PER_ANGSTROM)

      ! Set the interpolation table
      call set_saved_self_(self)  ! Used by ATOM: function below
      call set_even_spaced_data_(self%interpolator,density_value_at_radius)
   end subroutine

   function interpolator_table_length(self,tol) result (length)
   ! Return the interpolator table "length" for a given tolerance "tol" for the
   ! atom density. The interpolator is a default one.
      type(ATOM_TYPE), IN :: self
      REAL, IN :: tol
      REAL :: length
      type(INTERPOLATOR_TYPE), allocatable :: interpolator
      call create_(interpolator)
      call set_saved_self_(self)  ! Used by function below ... NOT PURE
      length = the_table_length_(interpolator,density_value_at_radius,tol)
      call destroy_(interpolator)
   end function

   PURE subroutine make_interpolated_density(self,density,pt,occ)
   ! Make the spherical atomic "density" for the supplied points "pt"
   ! using a precalculated interpolator.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), INOUT :: density
      MAT(REAL,:,:), IN :: pt
      REAL, optional, IN :: occ
      VEC(REAL,:), allocatable :: R2
      INT :: n_pt,n
      REAL :: x,y,z
   ENSURE(size(pt,2)==3,"ATOM:make_interpolated_density ... wrong dimension for points array")
   ENSURE(size(density)==size(pt,1),"ATOM:make_interpolated_density ... inconsistent number of points")
   ENSURE(allocated(self%interpolator),"ATOM:make_interpolated_density ... no interpolator defined!")
   ENSURE(self%interpolator%domain_mapping(1:4)=="sqrt","ATOM:make_interpolated_density ... must using sqrt-like mapping")

      ! Space for R2
      n_pt = size(pt,1)
      call create_(R2,n_pt)

      ! Get squared distances R2
      do n = 1,n_pt
         x = pt(n,1)-self%position(1)
         y = pt(n,2)-self%position(2)
         z = pt(n,3)-self%position(3)
         R2(n) = x*x+y*y+z*z
      end do

      ! Get the interpolated density values
      call values_for_(self%interpolator,R2,density,occ)

      ! Clean up
      call destroy_(R2)
   end subroutine

   PURE subroutine add_interpolated_density(self,density,pt,occ)
   ! Add the spherical atomic "density" for the supplied points "pt"
   ! using a precalculated interpolator.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), INOUT :: density
      MAT(REAL,:,:), IN :: pt
      REAL, optional, IN :: occ
      VEC(REAL,:), allocatable :: R2
      INT :: n_pt,n
      REAL :: x,y,z
   ENSURE(size(pt,2)==3,"ATOM:add_interpolated_density ... wrong dimension for points array")
   ENSURE(size(density)==size(pt,1),"ATOM:add_interpolated_density ... inconsistent number of points")
   ENSURE(allocated(self%interpolator),"ATOM:add_interpolated_density ... no interpolator defined!")
   ENSURE(self%interpolator%domain_mapping(1:4)=="sqrt","ATOM:add_interpolated_density ... must using sqrt-like mapping")

      ! Space for R2
      n_pt = size(pt,1)
      call create_(R2,n_pt)

      ! Get squared distances R2
      do n = 1,n_pt
         x = pt(n,1)-self%position(1)
         y = pt(n,2)-self%position(2)
         z = pt(n,3)-self%position(3)
         R2(n) = x*x+y*y+z*z
      end do

      ! Get the interpolated density values
      call add_values_for_(self%interpolator,R2,density,occ)

      ! Clean up
      call destroy_(R2)
   end subroutine


!  ===========================
!  Nabla density grid routines
!  ===========================

   PURE subroutine make_nabla_ED_grid_0(self,grid,pts)
   ! Make nabla of the electron density "grid", on points in "pts".
      type(ATOM_TYPE), IN :: self
      MAT(REAL,:,:), OUT :: grid
      MAT(REAL,:,:), IN :: pts
   ENSURE(allocated(self%NOs),"ATOM:make_nabla_ED_grid_0 ... no natural orbitals")
   ENSURE(number_kind_(self%NOs)=="real","ATOM:make_nabla_ED_grid_0 ... code not written yet")
      if (number_kind_(self%NOs)=="real") then
         call make_nabla_ED_grid_r_(self,grid,pts)
      end if
   end subroutine

   PURE subroutine make_nabla_ED_grid_1(self,ngrid,dgrid,pts)
   ! Put the nabla of the density in "ngrid", and the density in
   ! "dgrid", evaluated on the set of points in "pts".
      type(ATOM_TYPE), IN :: self
      MAT(REAL,:,:), OUT :: ngrid
      VEC(REAL,:), OUT :: dgrid
      MAT(REAL,:,:), IN :: pts
   ENSURE(allocated(self%NOs),"ATOM:make_nabla_ED_grid_1 ... no natural orbitals")
   ENSURE(number_kind_(self%NOs)=="real","ATOM:make_nabla_ED_grid_1 ... code not written yet")
      if (number_kind_(self%NOs)=="real") then
         call make_nabla_ED_grid_r_(self,ngrid,dgrid,pts)
      end if
   end subroutine

   PURE subroutine make_nabla_ED_grid_r_0(self,ngrid,pts)
   ! Put the nabla of the density in "ngrid", evaluated on the points
   ! in "pts", using ".NOs" and the ".occupation" number vector.
      type(ATOM_TYPE), IN :: self
      MAT(REAL,:,:), OUT :: ngrid
      MAT(REAL,:,:), IN :: pts
      VEC(REAL,:), allocatable :: orb
      MAT(REAL,:,:), allocatable :: norb
      REAL :: occ
      INT :: n_occ,n,n_pts
   ENSURE(size(pts,2)==3,"ATOM:make_nabla_ED_grid_r_0 ... wrong dimension for points array")
   ENSURE(size(ngrid,1)==size(pts,1),"ATOM:make_nabla_ED_grid_r_0 ... wrong 1st dimension for ngrid array")
   ENSURE(size(ngrid,2)==3,"ATOM:make_nabla_ED_grid_r_0 ... wrong 2nd dimension for ngrid array")
   ENSURE(allocated(self%NOs),"ATOM:make_nabla_ED_grid_r_0 ... no natural orbitals")
   ENSURE(is_allocated_with_genre_(self%NOs,"r"),"ATOM:make_nabla_ED_grid_r_0 ... no restricted NO's")
   ENSURE(allocated(self%NO_occ_nos),"ATOM:make_nabla_ED_grid_r_0 ... no occupation numbers")
   ENSURE(is_allocated_with_genre_(self%NO_occ_nos,"r"),"ATOM:make_nabla_ED_grid_r_0 ... no occupation numbers")
      n_pts = size(pts,1)
      ngrid = ZERO
      call create_(orb,n_pts)
      call create_(norb,n_pts,3)
      n_occ = no_of_occupied_NOs_(self)
      do n = 1,n_occ
         call make_nabla_orbital_grid_r_(self,norb,orb,self%NOs%r(:,n),pts)
         occ = self%NO_occ_nos%r(n)
         ngrid(:,1) = ngrid(:,1)+occ*orb(:)*norb(:,1)
         ngrid(:,2) = ngrid(:,2)+occ*orb(:)*norb(:,2)
         ngrid(:,3) = ngrid(:,3)+occ*orb(:)*norb(:,3)
      end do
      ngrid = TWO*ngrid
      call destroy_(orb)
      call destroy_(norb)
   end subroutine

   PURE subroutine make_nabla_ED_grid_r_1(self,ngrid,dgrid,pts)
   ! Put the nabla of the density in "ngrid", the density in "dgrid",
   ! evaluated on the the points in "pts" using the ".NOs" and the
   ! ".occupation" number vector.
      type(ATOM_TYPE), IN :: self
      MAT(REAL,:,:), OUT :: ngrid
      VEC(REAL,:), OUT :: dgrid
      MAT(REAL,:,:), IN :: pts
      VEC(REAL,:), allocatable :: orb
      MAT(REAL,:,:), allocatable :: norb
      REAL :: occ
      INT :: n_occ,n,n_pts
   ENSURE(size(pts,2)==3,"ATOM:make_nabla_ED_grid_r_1 ... wrong dim2 for pts array")
   ENSURE(size(ngrid,2)==3,"ATOM:make_nabla_ED_grid_r_1 ... wrong dim2 for ngrid array")
   ENSURE(size(ngrid,1)==size(pts,1),"ATOM:make_nabla_ED_grid_r_1 ... wrong dim1 for ngrid array")
   ENSURE(size(dgrid)==size(pts,1),"ATOM:make_nabla_ED_grid_r_1 ... wrong dim for dgrid array")
   ENSURE(allocated(self%NOs),"ATOM:make_nabla_ED_grid_r_1 ... no NOs")
   ENSURE(is_allocated_with_genre_(self%NOs,"r"),"ATOM:make_nabla_ED_grid_r_1 ... no restricted NO's")
   ENSURE(allocated(self%NO_occ_nos),"ATOM:make_nabla_ED_grid_r_1 ... no NO occupation numbers")
   ENSURE(is_allocated_with_genre_(self%NO_occ_nos,"r"),"ATOM:make_nabla_ED_grid_r_1 ... no NO occupation numbers")
      n_pts = size(pts,1)
      ngrid = ZERO
      dgrid = ZERO
      call create_(orb,n_pts)
      call create_(norb,n_pts,3)
      n_occ = no_of_occupied_NOs_(self)
      do n = 1,n_occ
         call make_nabla_orbital_grid_r_(self,norb,orb,self%NOs%r(:,n),pts)
         occ = self%NO_occ_nos%r(n)
         ngrid(:,1) = ngrid(:,1)+occ*orb(:)*norb(:,1)
         ngrid(:,2) = ngrid(:,2)+occ*orb(:)*norb(:,2)
         ngrid(:,3) = ngrid(:,3)+occ*orb(:)*norb(:,3)
         dgrid(:) = dgrid(:)+occ*orb(:)*orb(:)
      end do
      ngrid = TWO*ngrid
      call destroy_(orb)
      call destroy_(norb)
   end subroutine

   PURE subroutine make_nabla_orbital_grid_r(self,g,h,orb,pt)
   ! Evaluate the nabla orbital density grid "g" as well as the orbital grid "h"
   ! for *one* AO-basis orbital vector "orb" on a set of grid points "pt"
      type(ATOM_TYPE), IN :: self
      MAT(REAL,:,:), OUT :: g
      VEC(REAL,:), OUT :: h
      VEC(REAL,:), IN :: orb
      MAT(REAL,:,:), IN :: pt
      type(SHELL1_TYPE) :: sh
      MAT3(REAL,:,:,:), allocatable :: sh_grid
      MAT(REAL,:,:), allocatable :: sh_grid0
      INT :: n_shell,n_pt,f,l,s
   ENSURE(allocated(self%basis),"ATOM:make_nabla_orbital_grid_r ... no basis set")
   ENSURE(no_of_basis_functions_(self%basis)==size(orb),"ATOM:make_nabla_orbital_grid_r ... incorrect suize, orb")
   ENSURE(size(g,1)==size(pt,1),"ATOM:make_nabla_orbital_grid_r ... grid array has wrong 1st dimension")
   ENSURE(size(g,2)==3,"ATOM:make_nabla_orbital_grid_r ... grid array has wrong 2nd dimension")
   ENSURE(size(h)==size(pt,1),"ATOM:make_nabla_orbital_grid_r ... grid array has wrong 1st dimension")
      n_pt = size(pt,1)
      n_shell = no_of_shells_(self%basis)
      g = ZERO
      h = ZERO
      l = 0
      do s = 1,n_shell
         call set_(sh,self%basis%shell(s),self%position)
         f = l+1
         if (sh%is_spherical) then
            call create_(sh_grid,n_pt,sh%n_sph,3)
            call create_(sh_grid0,n_pt,sh%n_sph)
            l = f+sh%n_sph-1
         else
            call create_(sh_grid,n_pt,sh%n_comp,3)
            call create_(sh_grid0,n_pt,sh%n_comp)
            l = f+sh%n_comp-1
         end if
         call make_nabla_grid_(sh,sh_grid,sh_grid0,pt)
         call plus_product_of_(g(:,1),sh_grid(:,:,1),orb(f:l))
         call plus_product_of_(g(:,2),sh_grid(:,:,2),orb(f:l))
         call plus_product_of_(g(:,3),sh_grid(:,:,3),orb(f:l))
         call plus_product_of_(h,sh_grid0,orb(f:l))
         call destroy_(sh_grid0)
         call destroy_(sh_grid)
      end do
   end subroutine


!  ==========================
!  Laplacian density routines
!  ==========================

   PURE subroutine make_laplacian_ED_grid(self,laplacian_grid,pt)
   ! Work out the electron "laplacian_grid" on "pt" using ".natural orbitals"
   ! and  the ".NO_occ_nos" vector.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: laplacian_grid
      MAT(REAL,:,:), IN :: pt
   ENSURE(allocated(self%NOs),"ATOM:make_laplacian_ED_grid ... no natural orbitals")
   ENSURE(has_any_genre_(self%NOs),"ATOM:make_laplacian_ED_grid ... no natural orbitals")
   ENSURE(number_kind_(self%NOs)=="real","ATOM:make_laplacian_ED_grid ... code not written yet")
      if (number_kind_(self%NOs)=="real") then
         call make_laplacian_ED_grid_r_(self,laplacian_grid,pt)
      end if
   end subroutine

   PURE subroutine make_laplacian_ED_grid_r(self,laplacian_grid,pt)
   ! Make the "laplacian_grid" for the supplied points "pt" from restricted
   ! real natural orbitals
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: laplacian_grid
      MAT(REAL,:,:), IN :: pt
      VEC(REAL,:), allocatable :: NO
      MAT(REAL,:,:), allocatable :: P,D
      INT :: n_occ,n,n_pt
      REAL :: occ
   ENSURE(size(pt,2)==3,"ATOM:make_laplacian_ED_grid_r ... wrong dimension for pt array")
   ENSURE(is_allocated_with_genre_(self%NOs,"r"),"ATOM:make_laplacian_ED_grid_r ... no restricted NO's")
   ENSURE(allocated(self%NO_occ_nos%r),"ATOM:make_laplacian_ED_grid_r ... no occupation #'s")
      n_pt = size(pt,1)
      laplacian_grid = ZERO
      call create_(NO,n_pt)
      call create_(P,n_pt,3)
      call create_(D,n_pt,3)
      n_occ = no_of_occupied_NOs_(self)
      do n = 1,n_occ
         call make_laplacian_orbital_grid_r_(self,D,P,NO,self%NOs%r(:,n),pt)
         occ = self%NO_occ_nos%r(n)
         laplacian_grid = laplacian_grid+occ*(NO*(D(:,1)+D(:,2)+D(:,3))+(P(:,1)*P(:,1)+P(:,2)*P(:,2)+P(:,3)*P(:,3)))
      end do
      laplacian_grid = TWO*laplacian_grid
      call destroy_(D)
      call destroy_(P)
      call destroy_(NO)
   end subroutine

   PURE subroutine make_laplacian_orbital_grid_r(self,g,h,i,orb,pt)
   ! Evaluate the laplacian orbital density grid "g", as well as the nabla
   ! orbital grid "h" and the orbital grid "i" for *one* AO-basis orbital
   ! vector "orb" on a set of grid points "pt"
      type(ATOM_TYPE), IN :: self
      MAT(REAL,:,:), OUT :: g
      MAT(REAL,:,:), OUT :: h
      VEC(REAL,:), OUT :: i
      VEC(REAL,:), IN :: orb
      MAT(REAL,:,:), IN :: pt
      type(SHELL1_TYPE) :: sh
      MAT3(REAL,:,:,:), allocatable :: sh_grid,sh_grid1
      MAT(REAL,:,:), allocatable :: sh_grid0
      INT :: n_pt,f,l,s,n_shell
   ENSURE(allocated(self%basis),"ATOM:make_laplacian_orbital_grid_r ... no basis set")
   ENSURE(no_of_basis_functions_(self%basis)==size(orb),"ATOM:make_laplacian_orbital_grid_r ... incorrect suize, orb")
   ENSURE(size(g,1)==size(pt,1),"ATOM:make_laplacian_orbital_grid_r ... grid array has wrong 1st dimension")
   ENSURE(size(g,2)==3,"ATOM:make_laplacian_orbital_grid_r ... grid array has wrong 2nd dimension")
   ENSURE(size(h,1)==size(pt,1),"ATOM:make_laplacian_orbital_grid_r ... grid array has wrong 1st dimension")
   ENSURE(size(h,2)==3,"ATOM:make_laplacian_orbital_grid_r ... grid array has wrong 2nd dimension")
   ENSURE(size(i)==size(pt,1),"ATOM:make_laplacian_orbital_grid_r ... grid array has wrong 1st dimension")
      n_pt = size(pt,1)
      n_shell = no_of_shells_(self%basis)
      g = ZERO
      h = ZERO
      i = ZERO
      l = 0
      do s = 1,n_shell
         call set_(sh,self%basis%shell(s),self%position)
         f = l+1
         if (sh%is_spherical) then
            call create_(sh_grid,n_pt,sh%n_sph,3)
            call create_(sh_grid1,n_pt,sh%n_sph,3)
            call create_(sh_grid0,n_pt,sh%n_sph)
            l = f+sh%n_sph-1
         else
            call create_(sh_grid,n_pt,sh%n_comp,3)
            call create_(sh_grid1,n_pt,sh%n_comp,3)
            call create_(sh_grid0,n_pt,sh%n_comp)
            l = f+sh%n_comp-1
         end if
         call make_laplacian_grid_(sh,sh_grid,sh_grid1,sh_grid0,pt)
         call plus_product_of_(g(:,1),sh_grid(:,:,1),orb(f:l))
         call plus_product_of_(g(:,2),sh_grid(:,:,2),orb(f:l))
         call plus_product_of_(g(:,3),sh_grid(:,:,3),orb(f:l))
         call plus_product_of_(h(:,1),sh_grid1(:,:,1),orb(f:l))
         call plus_product_of_(h(:,2),sh_grid1(:,:,2),orb(f:l))
         call plus_product_of_(h(:,3),sh_grid1(:,:,3),orb(f:l))
         call plus_product_of_(i,sh_grid0,orb(f:l))
         call destroy_(sh_grid0)
         call destroy_(sh_grid1)
         call destroy_(sh_grid)
      end do
   end subroutine

   PURE subroutine make_rL_grid(self,laplacian_grid,pt)
   ! Work out the reduced "laplacian_grid" on "pt" using ".natural orbitals"
   ! and  the ".NO_occ_nos" vector.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: laplacian_grid
      MAT(REAL,:,:), IN :: pt
   ENSURE(allocated(self%NOs),"ATOM:make_rL_grid ... no natural orbitals")
   ENSURE(has_any_genre_(self%NOs),"ATOM:make_rL_grid ... no natural orbitals")
   ENSURE(number_kind_(self%NOs)=="real","ATOM:make_rL_grid ... code not written yet")
      if (number_kind_(self%NOs)=="real") then
         call make_rL_grid_r_(self,laplacian_grid,pt)
      end if
   end subroutine

   PURE subroutine make_rL_grid_r(self,laplacian_grid,pt)
   ! Make the reduced "laplacian_grid" for the supplied points "pt" from
   ! restricted real natural orbitals
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: laplacian_grid
      MAT(REAL,:,:), IN :: pt
      VEC(REAL,:), allocatable :: rho,NO
      MAT(REAL,:,:), allocatable :: P,D
      INT :: n_occ,n,n_pt
      REAL :: occ
   ENSURE(size(pt,2)==3,"ATOM:make_rL_grid_r ... wrong dimension for pt array")
   ENSURE(is_allocated_with_genre_(self%NOs,"r"),"ATOM:make_rL_grid_r ... no restricted NO's")
   ENSURE(allocated(self%NO_occ_nos%r),"ATOM:make_rL_grid_r ... no occupation #'s")
      n_pt = size(pt,1)
      laplacian_grid = ZERO
      call create_(rho,n_pt); rho = ZERO
      call create_(NO,n_pt)
      call create_(P,n_pt,3)
      call create_(D,n_pt,3)
      n_occ = no_of_occupied_NOs_(self)
      do n = 1,n_occ
         call make_laplacian_orbital_grid_r_(self,D,P,NO,self%NOs%r(:,n),pt)
         occ = self%NO_occ_nos%r(n)
         laplacian_grid = laplacian_grid+occ*(NO*(D(:,1)+D(:,2)+D(:,3))+(P(:,1)*P(:,1)+P(:,2)*P(:,2)+P(:,3)*P(:,3)))
         rho = rho+occ*NO*NO
      end do
      laplacian_grid = TWO*laplacian_grid/rho

      ! Clean
      call destroy_(D)
      call destroy_(P)
      call destroy_(NO)
      call destroy_(rho)
   end subroutine


!  =============================
!  Energy density from rho grids
!  =============================

   PURE subroutine make_E_hf_dens_from_rho_grid(self,E_grid,pt)
   ! Work out the energy density as the scaled electron density.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: E_grid
      MAT(REAL,:,:), IN :: pt
      REAL :: fac
      if (self%atomic_number<1) then
         E_grid = ZERO
      else
         call make_ED_grid_(self,E_grid,pt)
         fac = self%energy/self%atomic_number
         E_grid = fac*E_grid
      end if
   end subroutine


!  ===================================
!  Virial type energy density routines
!  ===================================

   PURE subroutine make_H_from_virial_grid(self,H_grid,pt)
   ! Work out the energy density using the virial relationsip 2G + V = (1/4) L,
   ! or H = G + V = (1/4)L - G
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: H_grid
      MAT(REAL,:,:), IN :: pt
      VEC(REAL,:), allocatable :: G_grid
      call create_(G_grid,size(H_grid))
      call make_G_kinetic_energy_grid_(self,G_grid,pt)
      call make_laplacian_ED_grid_(self,H_grid,pt)
      H_grid = QUARTER*H_grid-G_grid
      call destroy_(G_grid)
   end subroutine

   PURE subroutine make_rH_from_virial_grid(self,H_grid,pt)
   ! Work out the reduced energy density using the virial relationsip
   ! 2G + V = (1/4) L, or H = G + V = (1/4)L - G
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: H_grid
      MAT(REAL,:,:), IN :: pt
      VEC(REAL,:), allocatable :: G_grid
      call create_(G_grid,size(H_grid))
      call make_rG_kinetic_energy_grid_(self,G_grid,pt)
      call make_rL_grid_(self,H_grid,pt)
      H_grid = QUARTER*H_grid-G_grid
      call destroy_(G_grid)
   end subroutine

   PURE subroutine make_H_Kirzhnits_grid(self,H_grid,pt)
   ! Work out the energy density using the Kirzhnits relationsip 2G + V = (1/4) L,
   ! or H = G + V = (1/4)L - G
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: H_grid
      MAT(REAL,:,:), IN :: pt
      VEC(REAL,:), allocatable :: G_grid
      call create_(G_grid,size(H_grid))
      call make_G_Kirzhnits_grid_(self,G_grid,pt)
      call make_laplacian_ED_grid_(self,H_grid,pt)
      H_grid = QUARTER*H_grid-G_grid
      call destroy_(G_grid)
   end subroutine

   PURE subroutine make_V_from_virial_grid(self,V,pt)
   ! Work out the potential energy density from using the
   ! virial theorem: V = (1/4) L - 2G
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: V
      MAT(REAL,:,:), IN :: pt
      VEC(REAL,:), allocatable :: G
      call create_(G,size(V))
      call make_G_kinetic_energy_grid_(self,G,pt)
      call make_laplacian_ED_grid_(self,V,pt)
      V = QUARTER*V-TWO*G
      call destroy_(G)
   end subroutine

   PURE subroutine make_rV_from_virial_grid(self,V,pt)
   ! Work out the reduced potenbtial energy density from using the
   ! virial theorem: V = (1/4) L - 2G
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: V
      MAT(REAL,:,:), IN :: pt
      VEC(REAL,:), allocatable :: G
      call create_(G,size(V))
      call make_rG_kinetic_energy_grid_(self,G,pt)
      call make_rL_grid_(self,V,pt)
      V = QUARTER*V-TWO*G
      call destroy_(G)
   end subroutine

   PURE subroutine make_V_Kirzhnits_grid(self,V,pt)
   ! Work out the potential energy density from using the
   ! Kirzhnits theorem: V = (1/4) L - 2G
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: V
      MAT(REAL,:,:), IN :: pt
      VEC(REAL,:), allocatable :: G
      call create_(G,size(V))
      call make_G_Kirzhnits_grid_(self,G,pt)
      call make_laplacian_ED_grid_(self,V,pt)
      V = QUARTER*V-TWO*G
      call destroy_(G)
   end subroutine


!  ===============================
!  G-type kinetic density routines
!  ===============================

   PURE subroutine make_G_kinetic_energy_grid(self,G_grid,pt)
   ! Work out the G-type kinetic energy density (using nabla phi.nabla phi) on
   ! "pt" using ".natural orbitals" and  the ".NO_occ_nos" vector.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: G_grid
      MAT(REAL,:,:), IN :: pt
   ENSURE(allocated(self%NOs),"ATOM:make_G_kinetic_energy_grid ... no natural orbitals")
   ENSURE(has_any_genre_(self%NOs),"ATOM:make_G_kinetic_energy_grid ... no natural orbitals")
   ENSURE(number_kind_(self%NOs)=="real","ATOM:make_G_kinetic_energy_grid ... code not written yet")
      if (number_kind_(self%NOs)=="real") then
         call make_G_kinetic_energy_grid_r_(self,G_grid,pt)
      end if
   end subroutine

   PURE subroutine make_G_kinetic_energy_grid_r(self,G_grid,pt)
   ! Make the G-type kinetic energy density "G_grid" for the supplied points
   ! "pt" from restricted real natural orbitals
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: G_grid
      MAT(REAL,:,:), IN :: pt
      VEC(REAL,:), allocatable :: NO
      MAT(REAL,:,:), allocatable :: P
      INT :: n_occ,n,n_pt
   ENSURE(size(pt,2)==3,"ATOM:make_G_kinetic_energy_grid_r ... wrong dimension for pt array")
   ENSURE(is_allocated_with_genre_(self%NOs,"r"),"ATOM:make_G_kinetic_energy_grid_r ... no restricted NO's")
   ENSURE(allocated(self%NO_occ_nos%r),"ATOM:make_G_kinetic_energy_grid_r ... no occupation #'s")
      n_pt = size(pt,1)
      G_grid = ZERO
      call create_(NO,n_pt)
      call create_(P,n_pt,3)
      n_occ = no_of_occupied_NOs_(self)
      do n = 1,n_occ
         call make_nabla_orbital_grid_r_(self,P,NO,self%NOs%r(:,n),pt)
         G_grid(:) = G_grid(:)+self%NO_occ_nos%r(n)*(P(:,1)*P(:,1)+P(:,2)*P(:,2)+P(:,3)*P(:,3))
      end do
      G_grid(:) = HALF*G_grid(:)
      call destroy_(P)
      call destroy_(NO)
   end subroutine

   PURE subroutine make_rG_kinetic_energy_grid(self,G_grid,pt)
   ! Work out the reduced G-type kinetic energy density (using nabla phi.nabla phi) on
   ! "pt" using ".natural orbitals" and  the ".NO_occ_nos" vector.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: G_grid
      MAT(REAL,:,:), IN :: pt
   ENSURE(allocated(self%NOs),"ATOM:make_rG_kinetic_energy_grid ... no natural orbitals")
   ENSURE(has_any_genre_(self%NOs),"ATOM:make_rG_kinetic_energy_grid ... no natural orbitals")
   ENSURE(number_kind_(self%NOs)=="real","ATOM:make_rG_kinetic_energy_grid ... code not written yet")
      if (number_kind_(self%NOs)=="real") then
         call make_rG_kinetic_energy_grid_r_(self,G_grid,pt)
      end if
   end subroutine

   PURE subroutine make_rG_kinetic_energy_grid_r(self,G_grid,pt)
   ! Make the reduced G-type kinetic energy density "G_grid" for the supplied points
   ! "pt" from restricted real natural orbitals
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: G_grid
      MAT(REAL,:,:), IN :: pt
      VEC(REAL,:), allocatable :: rho,NO
      MAT(REAL,:,:), allocatable :: P
      INT :: n_occ,n,n_pt
      REAL :: occ
   ENSURE(size(pt,2)==3,"ATOM:make_rG_kinetic_energy_grid_r ... wrong dimension for pt array")
   ENSURE(is_allocated_with_genre_(self%NOs,"r"),"ATOM:make_rG_kinetic_energy_grid_r ... no restricted NO's")
   ENSURE(allocated(self%NO_occ_nos%r),"ATOM:make_rG_kinetic_energy_grid_r ... no occupation #'s")
      n_pt = size(pt,1)
      G_grid = ZERO
      call create_(rho,n_pt); rho = ZERO
      call create_(NO,n_pt)
      call create_(P,n_pt,3)
      n_occ = no_of_occupied_NOs_(self)
      do n = 1,n_occ
         call make_nabla_orbital_grid_r_(self,P,NO,self%NOs%r(:,n),pt)
         occ = self%NO_occ_nos%r(n)
         G_grid = G_grid+occ*(P(:,1)*P(:,1)+P(:,2)*P(:,2)+P(:,3)*P(:,3))
         rho = rho+occ*NO*NO
      end do
      G_grid = HALF*G_grid/rho
      call destroy_(P)
      call destroy_(NO)
      call destroy_(rho)
   end subroutine

   PURE subroutine make_G_Kirzhnits_grid(self,G_grid,pt)
   ! Work out the G-type Kirzhnits kinetic energy density (using nabla phi.nabla phi) on
   ! "pt" using ".natural orbitals" and  the ".NO_occ_nos" vector.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: G_grid
      MAT(REAL,:,:), IN :: pt
   ENSURE(allocated(self%NOs),"ATOM:make_G_Kirzhnits_grid ... no natural orbitals")
   ENSURE(has_any_genre_(self%NOs),"ATOM:make_G_Kirzhnits_grid ... no natural orbitals")
   ENSURE(number_kind_(self%NOs)=="real","ATOM:make_G_Kirzhnits_grid ... code not written yet")
      if (number_kind_(self%NOs)=="real") then
         call make_G_Kirzhnits_grid_r_(self,G_grid,pt)
      end if
   end subroutine

   PURE subroutine make_G_Kirzhnits_grid_r(self,G_grid,pt)
   ! Make the G-type Kirzhnits kinetic energy density "G_grid" for the supplied points
   ! "pt" from restricted real natural orbitals
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: G_grid
      MAT(REAL,:,:), IN :: pt
      VEC(REAL,:), allocatable :: NO,rho,nab_ro2,lap_rho
      MAT(REAL,:,:), allocatable :: G,L,nab_rho
      REAL :: lambda,k2,fac,occ,occ2
      INT :: n_occ,n,n_pt
   ENSURE(size(pt,2)==3,"ATOM:make_G_Kirzhnits_grid_r ... wrong dimension for pt array")
   ENSURE(is_allocated_with_genre_(self%NOs,"r"),"ATOM:make_G_Kirzhnits_grid_r ... no restricted NO's")
   ENSURE(allocated(self%NO_occ_nos%r),"ATOM:make_G_Kirzhnits_grid_r ... no occupation #'s")
      n_pt = size(pt,1)
      call create_(rho,n_pt); rho = ZERO
      call create_(lap_rho,n_pt); lap_rho = ZERO
      call create_(nab_ro2,n_pt)
      call create_(nab_rho,n_pt,3); nab_rho = ZERO
      call create_(NO,n_pt)
      call create_(G,n_pt,3)
      call create_(L,n_pt,3)
      n_occ = no_of_occupied_NOs_(self)
      do n = 1,n_occ
         call make_laplacian_orbital_grid_r_(self,L,G,NO,self%NOs%r(:,n),pt)
         occ = self%NO_occ_nos%r(n)
         occ2 = TWO*occ
         rho = rho+occ*NO*NO
         nab_rho(:,1) = nab_rho(:,1)+occ2*NO*G(:,1)
         nab_rho(:,2) = nab_rho(:,2)+occ2*NO*G(:,1)
         nab_rho(:,3) = nab_rho(:,3)+occ2*NO*G(:,1)
         lap_rho = lap_rho+occ2*(NO*(L(:,1)+L(:,2)+L(:,3))+(G(:,1)*G(:,1)+G(:,2)*G(:,2)+G(:,3)*G(:,3)))
      end do
      call destroy_(L)
      call destroy_(G)
      call destroy_(NO)
      nab_ro2 = nab_rho(:,1)*nab_rho(:,1)+nab_rho(:,2)*nab_rho(:,2)+nab_rho(:,3)*nab_rho(:,3)
      call destroy_(nab_rho)
      lambda = ONE/72.0d0
      k2 = HALF/SIX
      fac = 0.3d0*(THREE*PI*PI)**(TWOTHIRD)
      G_grid = fac*rho**(FIVE/THREE)+lambda*nab_ro2/rho+k2*lap_rho
      call destroy_(nab_ro2)
      call destroy_(lap_rho)
      call destroy_(rho)
   end subroutine


!  ===============================
!  K-type kinetic density routines
!  ===============================

   PURE subroutine make_K_kinetic_energy_grid(self,K_grid,pt)
   ! Work out the K-type kinetic energy density (using the nabla^2) on "pt"
   ! using ".natural orbitals" and  the ".NO_occ_nos" vector.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: K_grid
      MAT(REAL,:,:), IN :: pt
   ENSURE(allocated(self%NOs),"ATOM:make_K_kinetic_energy_grid ... no natural orbitals")
   ENSURE(has_any_genre_(self%NOs),"ATOM:make_K_kinetic_energy_grid ... no natural orbitals")
   ENSURE(number_kind_(self%NOs)=="real","ATOM:make_K_kinetic_energy_grid ... code not written yet")
      if (number_kind_(self%NOs)=="real") then
         call make_K_kinetic_energy_grid_r_(self,K_grid,pt)
      end if
   end subroutine

   PURE subroutine make_K_kinetic_energy_grid_r(self,K_grid,pt)
   ! Make the K-type kinetic energy density "K_grid" for the supplied points
   ! "pt" from restricted real natural orbitals
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: K_grid
      MAT(REAL,:,:), IN :: pt
      VEC(REAL,:), allocatable :: NO
      MAT(REAL,:,:), allocatable :: P,D
      INT :: n_occ,n,n_pt
      REAL :: occ
   ENSURE(size(pt,2)==3,"ATOM:make_K_kinetic_energy_grid_r ... wrong dimension for pt array")
   ENSURE(is_allocated_with_genre_(self%NOs,"r"),"ATOM:make_K_kinetic_energy_grid_r ... no restricted NO's")
   ENSURE(allocated(self%NO_occ_nos%r),"ATOM:make_K_kinetic_energy_grid_r ... no occupation #'s")
      n_pt = size(pt,1)
      K_grid = ZERO
      call create_(NO,n_pt)
      call create_(P,n_pt,3)
      call create_(D,n_pt,3)
      n_occ = no_of_occupied_NOs_(self)
      do n = 1,n_occ
         call make_laplacian_orbital_grid_r_(self,D,P,NO,self%NOs%r(:,n),pt)
         occ = self%NO_occ_nos%r(n)
         K_grid(:) = K_grid(:)+occ*NO*(D(:,1)+D(:,2)+D(:,3))
      end do
      K_grid(:) = -HALF*K_grid(:)
      call destroy_(D)
      call destroy_(P)
      call destroy_(NO)
   end subroutine

   PURE subroutine make_rK_kinetic_energy_grid(self,K_grid,pt)
   ! Work out the reduced K-type kinetic energy density (using the nabla^2) on "pt"
   ! using ".natural orbitals" and  the ".NO_occ_nos" vector.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: K_grid
      MAT(REAL,:,:), IN :: pt
   ENSURE(allocated(self%NOs),"ATOM:make_rK_kinetic_energy_grid ... no natural orbitals")
   ENSURE(has_any_genre_(self%NOs),"ATOM:make_rK_kinetic_energy_grid ... no natural orbitals")
   ENSURE(number_kind_(self%NOs)=="real","ATOM:make_rK_kinetic_energy_grid ... code not written yet")
      if (number_kind_(self%NOs)=="real") then
         call make_rK_kinetic_energy_grid_r_(self,K_grid,pt)
      end if
   end subroutine

   PURE subroutine make_rK_kinetic_energy_grid_r(self,K_grid,pt)
   ! Make the K-type kinetic energy density "K_grid" for the supplied points
   ! "pt" from restricted real natural orbitals
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: K_grid
      MAT(REAL,:,:), IN :: pt
      VEC(REAL,:), allocatable :: rho,NO
      MAT(REAL,:,:), allocatable :: P,D
      INT :: n_occ,n,n_pt
      REAL :: occ
   ENSURE(size(pt,2)==3,"ATOM:make_rK_kinetic_energy_grid_r ... wrong dimension for pt array")
   ENSURE(is_allocated_with_genre_(self%NOs,"r"),"ATOM:make_rK_kinetic_energy_grid_r ... no restricted NO's")
   ENSURE(allocated(self%NO_occ_nos%r),"ATOM:make_rK_kinetic_energy_grid_r ... no occupation #'s")
      n_pt = size(pt,1)
      K_grid = ZERO
      call create_(rho,n_pt); rho = ZERO
      call create_(NO,n_pt)
      call create_(P,n_pt,3)
      call create_(D,n_pt,3)
      n_occ = no_of_occupied_NOs_(self)
      do n = 1,n_occ
         call make_laplacian_orbital_grid_r_(self,D,P,NO,self%NOs%r(:,n),pt)
         occ = self%NO_occ_nos%r(n)
         K_grid = K_grid+occ*NO*(D(:,1)+D(:,2)+D(:,3))
         rho = rho+occ*NO*NO
      end do
      K_grid = -HALF*K_grid/rho
      call destroy_(D)
      call destroy_(P)
      call destroy_(NO)
      call destroy_(rho)
   end subroutine


!  =============
!  DFT potential
!  =============

   PURE subroutine make_DFT_xc_pot_grid(self,V,pt,exchange,correlation)
   ! Work out the DFT exchange-correlation potential "V" at a series of points
   ! "pt".
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: V
      MAT(REAL,:,:), IN :: pt
      STR(len=*), IN :: exchange
      STR(len=*), IN :: correlation
      type(DFT_FUNCTIONAL_TYPE) :: dft
      type(XC_POTENTIAL_TYPE) :: pot
      VEC(REAL,:), allocatable :: rho
      call create_(rho,size(V))
      call make_ED_grid_(self,rho,pt)
      call make_r_energy_and_potential_(dft,pot,exchange,correlation,rho)
      V = pot%v_rho(:,1)
      call destroy_ptr_part_(pot)
      call destroy_(rho)
   end subroutine

   PURE subroutine make_DFT_eff_pot_grid(self,V,pt,exchange,correlation)
   ! Work out the DFT effective potential "V" (i.e. the DFT potential plus the
   ! classical electric potential) on a grid of points "pt".
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), INOUT :: V
      MAT(REAL,:,:), IN :: pt
      STR(len=*), IN :: exchange
      STR(len=*), IN :: correlation
      VEC(REAL,:), allocatable :: rho
      type(DFT_FUNCTIONAL_TYPE) :: dft
      type(XC_POTENTIAL_TYPE) :: pot
      call make_EP_grid_(self,V,pt)
      call create_(rho,size(V))
      call make_ED_grid_(self,rho,pt)
      call make_r_energy_and_potential_(dft,pot,exchange,correlation,rho)
      V = V+pot%v_rho(:,1)
      call destroy_ptr_part_(pot)
      call destroy_(rho)
   end subroutine

   PURE subroutine make_DFT_energy_grid(self,V,pt,exchange,correlation)
   ! Work out the Slater DFT energy "V" (i.e. the Slater potential times the
   ! density plus the classical electric energy) on a grid of points "pt".
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), INOUT :: V
      MAT(REAL,:,:), IN :: pt
      STR(len=*), IN :: exchange
      STR(len=*), IN :: correlation
      VEC(REAL,:), allocatable :: Ve,rho
      type(DFT_FUNCTIONAL_TYPE) :: dft
      type(XC_POTENTIAL_TYPE) :: pot
   ENSURE(allocated(self%density_mx),"ATOM:make_DFT_energy_grid ... no density matrix")
   ENSURE(allocated(self%density_mx%r),"ATOM:make_DFT_energy_grid ... no restricted density matrix")
      call make_nucl_potential_grid_(self,V,pt)
      call create_(Ve,size(V))
      call make_elec_potential_grid_(self,Ve,pt,self%density_mx%r)
      V = -V-HALF*Ve
      call destroy_(Ve)
      call create_(rho,size(V))
      call make_ED_grid_(self,rho,pt)
      call make_r_energy_and_potential_(dft,pot,exchange,correlation,rho)
      V = V+pot%energy
      V = V*rho
      call destroy_ptr_part_(pot)
      call destroy_(rho)
   end subroutine

   PURE subroutine make_H_DFT_energy_grid(self,H_grid,pt,exchange,correlation)
   ! Work out the H DFT energy density "H_grid" on a set ofpoints "pt"
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: H_grid
      MAT(REAL,:,:), IN :: pt
      STR(len=*), IN :: exchange
      STR(len=*), IN :: correlation
      VEC(REAL,:), allocatable :: G_grid
      call create_(G_grid,size(H_grid))
      call make_G_kinetic_energy_grid_(self,G_grid,pt)
      call make_DFT_energy_grid_(self,H_grid,pt,exchange,correlation)
      H_grid = H_grid+G_grid
      call destroy_(G_grid)
   end subroutine


!  ==================
!  Electric potential
!  ==================

   PURE subroutine make_EP_grid(self,pot_grid,pt)
   ! Make the total electric potential grid "pot_grid" (nuclear and
   ! electronic) on a series of points "pt".
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: pot_grid
      MAT(REAL,:,:), IN :: pt
   ENSURE(allocated(self%density_mx),"ATOM:make_EP_grid ... no density matrix")
   ENSURE(allocated(self%density_mx%r),"ATOM:make_EP_grid ... no restricted density matrix")
   ENSURE(number_kind_(self%NOs)=="real","ATOM:make_EP_grid ... code not written yet")
      if (number_kind_(self%density_mx)=="real") then
         call make_EP_grid_r_(self,pot_grid,pt,self%density_mx%r)
      end if
   end subroutine

   PURE subroutine make_EP_grid_r(self,pot_grid,pt,dens)
   ! Make the total electric potential "pot_grid" on a series of grid points
   ! "pt" using AO density matrix "dens"
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: pot_grid
      MAT(REAL,:,:), IN :: pt
      MAT(REAL,:,:), IN :: dens
      VEC(REAL,:), allocatable :: elec_grid

      ! Nuclear
      call make_nucl_potential_grid_(self,pot_grid,pt)

      ! Electronic
      call create_(elec_grid,size(pot_grid))
      call make_elec_potential_grid_(self,elec_grid,pt,dens)

      ! Add
      call plus_(pot_grid,elec_grid)
      call destroy_(elec_grid)
   end subroutine

   PURE subroutine make_elec_potential_grid(self,pot_grid,pt,dens)
   ! Make the electronic potential grid "pot_grid" on a series of grid
   ! points "pt" using AO density matrix "dens"
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: pot_grid
      MAT(REAL,:,:), IN :: pt
      MAT(REAL,:,:), IN :: dens
      MAT(REAL,:,:), allocatable :: Vab
      type(SHELL2_TYPE) :: sh
      INT :: n_pt,n_shell_pairs,q,fa,fb,la,lb,k
   ENSURE(allocated(self%basis),"ATOM:make_elec_potential_grid ... no basis set")
      n_pt = size(pt,1)
      n_shell_pairs = no_of_shells_(self%basis)
      n_shell_pairs = triangle_number_(n_shell_pairs)
      pot_grid = ZERO
      do q = 1,n_shell_pairs
         call set_shell2_from_(self,q,sh,fa,la,fb,lb)
         if (sh%is_spherical) then
            call create_(Vab,sh%a%n_sph,sh%b%n_sph)
         else
            call create_(Vab,sh%a%n_comp,sh%b%n_comp)
         end if
         if (fa/=fb) then
            do k = 1,n_pt
               call get_nuc_(sh,Vab,ONE,pt(k,:))
               pot_grid(k) = pot_grid(k)-TWO*sum(Vab*dens(fa:la,fb:lb))
            end do
         else
            do k = 1,n_pt
               call get_nuc_(sh,Vab,ONE,pt(k,:))
               pot_grid(k) = pot_grid(k)-sum(Vab*dens(fa:la,fb:lb))
            end do
         end if
         call destroy_(Vab)
         call destroy_ptr_part_(sh)
      end do
   end subroutine

   PURE subroutine make_nucl_potential_grid(self,values,pts)
   ! Calculate the nuclear potential "values" of a given set of "pts".
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: values
      MAT(REAL,:,:), IN :: pts
      INT :: i
      REAL :: r,x,y,z,xi,yi,zi
      values = ZERO
      x = self%position(1)
      y = self%position(2)
      z = self%position(3)
      do i = 1,size(values)
         xi = pts(i,1)-x
         yi = pts(i,2)-y
         zi = pts(i,3)-z
         r = sqrt(xi*xi+yi*yi+zi*zi)
         if (r>tiny(r)) then; values(i) = values(i)+self%atomic_number/r
         else; values(i) = values(i)+huge(ONE)
         end if
      end do
   end subroutine


!  =================================
!  DFT grids for all basis functions
!  =================================

   PURE subroutine make_bf_grid_0(self,grid,pt)
   ! Make a "grid" on which all the atom basis functions are
   ! evaluated, for the supplied points "pt".
      type(ATOM_TYPE), IN :: self
      MAT(REAL,:,:), OUT :: grid
      MAT(REAL,:,:), IN :: pt
      type(SHELL1_TYPE) :: sh
      INT :: s,f,l,n_shell
   ENSURE(allocated(self%basis),"ATOM:make_bf_grid_0 ... no basis set")
   ENSURE(size(pt,2)==3,"ATOM:make_bf_grid_0 ... wrong dimension for pt array")
   ENSURE(size(grid,1)==size(pt,1),"ATOM:make_bf_grid_0 ... incompatible grid and pt arrays")
   ENSURE(size(grid,2)==no_of_basis_functions_(self%basis),"ATOM:make_bf_grid_0 ... wrong size, grid array")
      n_shell = no_of_shells_(self%basis)
      l = 0
      do s = 1,n_shell
         call set_(sh,self%basis%shell(s),self%position)
         f = l+1
         if (sh%is_spherical) then; l = l+sh%n_sph
         else; l = l+sh%n_comp
         end if
         call make_grid_(sh,grid(:,f:l),pt)
      end do
   end subroutine

   PURE subroutine make_nabla_bf_grid_0(self,nabla_grid,pt)
   ! Make a "nabla_grid" on which the gradient of all the atom basis
   ! functions are evaluated, for the supplied points "pt".
      type(ATOM_TYPE), IN :: self
      MAT3(REAL,:,:,:), OUT :: nabla_grid
      MAT(REAL,:,:), IN :: pt
      type(SHELL1_TYPE) :: sh
      INT :: s,n_shell
   ENSURE(allocated(self%basis),"ATOM:make_nabla_bf_grid_0 ... no basis set")
   ENSURE(size(pt,2)==3,"ATOM:make_nabla_bf_grid_0 ... wrong dimension for pt array")
   ENSURE(size(nabla_grid,1)==size(pt,1),"ATOM:make_nabla_bf_grid_0 ... incompatible nabla_grid and pt arrays")
   ENSURE(size(nabla_grid,2)==no_of_basis_functions_(self%basis),"ATOM:make_nabla_bf_grid_0 ... wrong size, nabla_grid array")
   ENSURE(size(nabla_grid,3)==3,"ATOM:make_nabla_bf_grid_0 ... wrong size, nabla_grid array")
      n_shell = no_of_shells_(self%basis)
      do s = 1,n_shell
         call set_(sh,self%basis%shell(s),self%position)
         call make_nabla_grid_(sh,nabla_grid,pt)
      end do
   end subroutine

   PURE subroutine make_nabla_bf_grid_1(self,nabla_grid,grid,pt)
   ! Make a "nabla_grid" on which the gradient of all the atom basis
   ! functions are evaluated, for the supplied points "pt". Also
   ! return "grid", which tabluates the values of all the atom basis
   ! functions on the grid points.
      type(ATOM_TYPE), IN :: self
      MAT3(REAL,:,:,:), OUT :: nabla_grid
      MAT(REAL,:,:), OUT :: grid
      MAT(REAL,:,:), IN :: pt
      type(SHELL1_TYPE) :: sh
      INT :: s,f,l,n_shell
   ENSURE(allocated(self%basis),"ATOM:make_nabla_bf_grid_1 ... no basis set")
   ENSURE(size(pt,2)==3,"ATOM:make_nabla_bf_grid_1 ... wrong dimension for pt array")
   ENSURE(size(nabla_grid,1)==size(pt,1),"ATOM:make_nabla_bf_grid_1 ... incompatible nabla_grid and pt arrays")
   ENSURE(size(nabla_grid,2)==no_of_basis_functions_(self%basis),"ATOM:make_nabla_bf_grid_1 ... wrong size, nabla_grid array")
   ENSURE(size(nabla_grid,3)==3,"ATOM:make_nabla_bf_grid_1 ... wrong size, nabla_grid array")
   ENSURE(size(grid,1)==size(pt,1),"ATOM:make_nabla_bf_grid_1 ... incompatible grid and pt arrays")
   ENSURE(size(grid,2)==no_of_basis_functions_(self%basis),"ATOM:make_nabla_bf_grid_1 ... wrong size, grid array")
      n_shell = no_of_shells_(self%basis)
      l = 0
      do s = 1,n_shell
         call set_(sh,self%basis%shell(s),self%position)
         f = l+1
         if (sh%is_spherical) then; l = l+sh%n_sph
         else; l = l+sh%n_comp
         end if
         call make_nabla_grid_(sh,nabla_grid(:,f:l,1),nabla_grid(:,f:l,2),nabla_grid(:,f:l,3),grid(:,f:l),pt)
      end do
   end subroutine

   PURE subroutine make_bf_grid_1(self,grid0,pt,cutoff)
   ! Make a "grid0" on which all the atom basis functions are evaluated, for the
   ! supplied points "pt".
      type(ATOM_TYPE), IN :: self
      MAT(REAL,:,:), OUT :: grid0
      MAT(REAL,:,:), IN :: pt
      REAL, IN :: cutoff
      VEC(REAL,:), allocatable :: x,y,z,r2
      type(SHELL1_TYPE) :: sh
      INT :: n_pt,s,f,l,n_shell
   ENSURE(allocated(self%basis),"ATOM:make_bf_grid_1 ... no basis set")
   ENSURE(size(pt,2)==3,"ATOM:make_bf_grid_1 ... wrong dimension for pt array")
   ENSURE(size(grid0,1)==size(pt,1),"ATOM:make_bf_grid_1 ... incompatible grid0 and pt arrays")
   ENSURE(size(grid0,2)==no_of_basis_functions_(self%basis),"ATOM:make_bf_grid_1 ... wrong size, grid0 array")
      n_pt = size(pt,1)
      call create_(x,n_pt)
      call create_(y,n_pt)
      call create_(z,n_pt)
      call create_(r2,n_pt)
      call make_displaced_pts_(self,x,y,z,r2,pt,n_pt)
      n_shell = no_of_shells_(self%basis)
      l = 0
      do s = 1,n_shell
         call set_(sh,self%basis%shell(s),self%position)
         f = l+1
         if (sh%is_spherical) then; l = l+sh%n_sph
         else; l = l+sh%n_comp
         end if
         call make_grid_(sh,grid0(:,f:l),x,y,z,r2,cutoff)
      end do
      call destroy_(r2)
      call destroy_(z)
      call destroy_(y)
      call destroy_(x)
   end subroutine

   PURE subroutine make_nabla_bf_grid_2(self,grid1,pt,cutoff)
   ! Make a nabla grid, "grid1", on which the gradient of all the atom basis
   ! functions are evaluated, for the supplied points "pt".
      type(ATOM_TYPE), IN :: self
      MAT3(REAL,:,:,:), OUT :: grid1
      MAT(REAL,:,:), IN :: pt
      REAL, IN :: cutoff
      VEC(REAL,:), allocatable :: x,y,z,r2
      type(SHELL1_TYPE) :: sh
      INT :: n_pt,s
   ENSURE(allocated(self%basis),"ATOM:make_nabla_bf_grid_2 ... no basis set")
   ENSURE(size(pt,2)==3,"ATOM:make_nabla_bf_grid_2 ... wrong dimension for pt array")
   ENSURE(size(grid1,1)==size(pt,1),"ATOM:make_nabla_bf_grid_2 ... incompatible grid1 and pt arrays")
   ENSURE(size(grid1,2)==no_of_basis_functions_(self%basis),"ATOM:make_nabla_bf_grid_2 ... wrong size, grid1 array")
   ENSURE(size(grid1,3)==3,"ATOM:make_nabla_bf_grid_2 ... wrong size, grid1 array")
      n_pt = size(pt,1)
      call create_(x,n_pt)
      call create_(y,n_pt)
      call create_(z,n_pt)
      call create_(r2,n_pt)
      call make_displaced_pts_(self,x,y,z,r2,pt,n_pt)
      do s = 1,no_of_shells_(self%basis)
         call set_(sh,self%basis%shell(s),self%position)
         call make_nabla_grid_(sh,grid1,x,y,z,r2,cutoff)
      end do
      call destroy_(r2)
      call destroy_(z)
      call destroy_(y)
      call destroy_(x)
   end subroutine

   PURE subroutine make_nabla_bf_grid_3(self,grid1,grid0,pt,cutoff)
   ! Make a nabla grid "grid1" on which the gradient of all the atom basis functions
   ! are evaluated, for the supplied points "pt". Also return "grid0", which
   ! tabluates the values of all the atom basis functions on the grid points.
      type(ATOM_TYPE), IN :: self
      MAT3(REAL,:,:,:), OUT :: grid1
      MAT(REAL,:,:), OUT :: grid0
      MAT(REAL,:,:), IN :: pt
      REAL, IN :: cutoff
      type(SHELL1_TYPE) :: sh
      INT :: n_pt,s,f,l
      VEC(REAL,:), allocatable :: x,y,z,r2
   ENSURE(allocated(self%basis),"ATOM:make_nabla_bf_grid_3 ... no basis set")
   ENSURE(size(pt,2)==3,"ATOM:make_nabla_bf_grid_3 ... wrong dimension for pt array")
   ENSURE(size(grid1,1)==size(pt,1),"ATOM:make_nabla_bf_grid_3 ... incompatible grid1 and pt arrays")
   ENSURE(size(grid1,2)==no_of_basis_functions_(self%basis),"ATOM:make_nabla_bf_grid_3 ... wrong size, grid1 array")
   ENSURE(size(grid1,3)==3,"ATOM:make_nabla_bf_grid_3 ... wrong size, grid1 array")
   ENSURE(size(grid0,1)==size(pt,1),"ATOM:make_nabla_bf_grid_3 ... incompatible grid0 and pt arrays")
   ENSURE(size(grid0,2)==no_of_basis_functions_(self%basis),"ATOM:make_nabla_bf_grid_3 ... wrong size, grid array")
      n_pt = size(pt,1)
      call create_(x,n_pt)
      call create_(y,n_pt)
      call create_(z,n_pt)
      call create_(r2,n_pt)
      call make_displaced_pts_(self,x,y,z,r2,pt,n_pt)
      l = 0
      do s = 1,no_of_shells_(self%basis)
         call set_(sh,self%basis%shell(s),self%position)
         f = l+1
         if (sh%is_spherical) then; l = l+sh%n_sph
         else; l = l+sh%n_comp
         end if
         call make_nabla_grid_(sh,grid1(:,f:l,1),grid1(:,f:l,2),grid1(:,f:l,3),grid0(:,f:l),x,y,z,r2,cutoff)
      end do
      call destroy_(r2)
      call destroy_(z)
      call destroy_(y)
      call destroy_(x)
   end subroutine


!  ================
!  Make point lists
!  ================

   PURE subroutine make_logval(self,logval,r2,n_pt)
   ! For a list of points with distances "r2" from an atom center,
   ! return the log of the mkaximuk value "logval" which can be used
   ! to implement a cutoff.
      type(ATOM_TYPE), IN :: self
      INT, IN :: n_pt
      VEC(INT,n_pt), OUT :: logval
      VEC(REAL,n_pt), IN :: r2
      REAL :: rr,ex
      INT :: n
   ENSURE(allocated(self%basis),"ATOM:make_logval ... no basis set")
      ex = min_exponent_(self%basis%shell)
      do n = 1,n_pt
         rr = r2(n)
         logval(n) = ceiling(log10(exp(-ex*rr)))
      end do
   end subroutine

   PURE subroutine make_displaced_pts(self,dx,dy,dz,r2,pt,n_pt)
   ! For a list of points "pt" of length "n_pt", return displacements
   ! "dx", "dy", "dz", from the atom center, and their square "r2".
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: dx,dy,dz,r2
      MAT(REAL,:,:), IN :: pt
      INT, IN :: n_pt
      REAL :: px,py,pz,xx,yy,zz,rr
      INT :: n
   ENSURE(allocated(self%basis),"ATOM:make_displaced_pts ... no basis set")
   ENSURE(size(dx)==n_pt,"ATOM:make_displaced_pts ... wrong size, dx")
   ENSURE(size(dy)==n_pt,"ATOM:make_displaced_pts ... wrong size, dy")
   ENSURE(size(dz)==n_pt,"ATOM:make_displaced_pts ... wrong size, dy")
   ENSURE(size(pt,1)==n_pt,"ATOM:make_displaced_pts ... wrong dim1, pt")
   ENSURE(size(pt,2)==3,"ATOM:make_displaced_pts ... wrong dim1, pt")
      px = self%position(1)
      py = self%position(2)
      pz = self%position(3)
      do n = 1,n_pt
         xx = pt(n,1)-px
         yy = pt(n,2)-py
         zz = pt(n,3)-pz
         rr = xx*xx+yy*yy+zz*zz
         dx(n) = xx
         dy(n) = yy
         dz(n) = zz
         r2(n) = rr
      end do
   end subroutine

   PURE subroutine make_displaced_skip_pts(self,dx,dy,dz,r2,skip,pt,n_pt,cutoff)
   ! For a list of points "pt" of length "n_pt", return displacements
   ! "dx", "dy", "dz", their square "r2" and "skip" which tells when
   ! the basis function is less than "cutoff".
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), OUT :: dx,dy,dz,r2
      VEC(BIN,:), OUT :: skip
      MAT(REAL,:,:), IN :: pt
      INT, IN :: n_pt
      REAL, IN :: cutoff
      REAL :: px,py,pz,xx,yy,zz,rr,r2_max
      INT :: n
   ENSURE(allocated(self%basis),"ATOM:make_displaced_skip_pts ... no basis set")
   ENSURE(size(dx)>=n_pt,"ATOM:make_displaced_skip_pts ... wrong size, dx")
   ENSURE(size(dy)>=n_pt,"ATOM:make_displaced_skip_pts ... wrong size, dy")
   ENSURE(size(dz)>=n_pt,"ATOM:make_displaced_skip_pts ... wrong size, dy")
   ENSURE(size(pt,1)>=n_pt,"ATOM:make_displaced_skip_pts ... wrong dim1, pt")
   ENSURE(size(pt,2)==3,"ATOM:make_displaced_skip_pts ... wrong dim1, pt")
      px = self%position(1)
      py = self%position(2)
      pz = self%position(3)
      r2_max = r2_max_(self,cutoff)
      do n = 1,n_pt
         xx = pt(n,1)-px
         yy = pt(n,2)-py
         zz = pt(n,3)-pz
         rr = xx*xx+yy*yy+zz*zz
         dx(n) = xx
         dy(n) = yy
         dz(n) = zz
         r2(n) = rr
         skip(n) = rr>r2_max
      end do
   end subroutine

   PURE subroutine make_significant_points_0(self,x,y,z,r2,skip,pt,cutoff)
   ! From a given list of points "pt" return the significant displacements "x",
   ! "y", "z" and their square "r2". These are comprised of those points for
   ! which the basis functions of the atom have a significant value above
   ! "cutoff" i.e. those points for which "skip" is FALSE.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), allocatable, OUT :: x,y,z,r2
      VEC(BIN,:), allocatable, OUT :: skip
      MAT(REAL,:,:), IN :: pt
      REAL, IN :: cutoff
      REAL :: px,py,pz,xx,yy,zz,rr,r2_max
      INT :: n_pt,n,k
   ENSURE(allocated(self%basis),"ATOM:make_significant_points_0 ... no basis set")
      n_pt = size(pt,1)
      call create_(skip,n_pt)
      call create_(x,n_pt)
      call create_(y,n_pt)
      call create_(z,n_pt)
      call create_(r2,n_pt)
      r2_max = r2_max_(self,cutoff)
      px = self%position(1)
      py = self%position(2)
      pz = self%position(3)
      k = 0
      do n = 1,n_pt
         xx = pt(n,1)-px
         yy = pt(n,2)-py
         zz = pt(n,3)-pz
         rr = xx*xx+yy*yy+zz*zz
         skip(n) = rr>r2_max
         if (skip(n)) cycle
         k = k+1
         x(k) = xx
         y(k) = yy
         z(k) = zz
         r2(k) = rr
      end do
      if (k==0) then
         call destroy_(skip)
         call destroy_(x); call destroy_(y); call destroy_(z)
         call destroy_(r2)
      else
         call shrink_(x,k); call shrink_(y,k); call shrink_(z,k)
         call shrink_(r2,k)
      end if
   end subroutine

   PURE subroutine make_significant_points_1(self,x,y,z,r2,d2,skip,pt,cutoff)
   ! From a given list of points "pt" return the significant displacements "x",
   ! "y", "z" and their square "r2". These are comprised of those points for
   ! which the basis functions of the atom have a significant value above
   ! "cutoff" i.e. those points for which "skip" is FALSE.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), allocatable, OUT :: x,y,z,r2,d2
      VEC(BIN,:), allocatable, OUT :: skip
      MAT(REAL,:,:), IN :: pt
      REAL, IN :: cutoff
      REAL :: px,py,pz,xx,yy,zz,rr,r2_max
      INT :: n_pt,n,k
   ENSURE(allocated(self%basis),"ATOM:make_significant_points_1 ... no basis set")
      n_pt = size(pt,1)
      call create_(skip,n_pt)
      call create_(x,n_pt)
      call create_(y,n_pt)
      call create_(z,n_pt)
      call create_(r2,n_pt)
      call create_(d2,n_pt)
      r2_max = r2_max_(self,cutoff)
      px = self%position(1)
      py = self%position(2)
      pz = self%position(3)
      k = 0
      do n = 1,n_pt
         xx = pt(n,1)-px
         yy = pt(n,2)-py
         zz = pt(n,3)-pz
         rr = xx*xx+yy*yy+zz*zz
         d2(n) = rr
         skip(n) = rr>r2_max
         if (skip(n)) cycle
         k = k+1
         x(k) = xx
         y(k) = yy
         z(k) = zz
         r2(k) = rr
      end do
      if (k==0) then
         call destroy_(skip)
         call destroy_(x)
         call destroy_(y)
         call destroy_(z)
         call destroy_(r2)
         call destroy_(d2)
      else
         call shrink_(x,k)
         call shrink_(y,k)
         call shrink_(z,k)
         call shrink_(r2,k)  ! don't shrink d2 or skip
      end if
   end subroutine

   PURE subroutine make_significant_points_2(self,x,y,z,r2,skip,pt,skip2,cutoff)
   ! From a given list of points "pt" return the significant displacements "x",
   ! "y", "z" and their square "r2". These are comprised of those points for
   ! which the basis functions of the atom have a significant value above
   ! "cutoff" i.e. those points for which "skip" is FALSE. "skip2" is an array
   ! which skips (in addition) some preselcted points.
      type(ATOM_TYPE), IN :: self
      VEC(REAL,:), allocatable, OUT :: x,y,z,r2
      VEC(BIN,:), allocatable, OUT :: skip
      MAT(REAL,:,:), IN :: pt
      VEC(BIN,:), IN :: skip2
      REAL, IN :: cutoff
      REAL :: xx,yy,zz,rr,r2_max
      INT :: n_pt,n,k
   ENSURE(allocated(self%basis),"ATOM:make_significant_points_2 ... no basis set")
      n_pt = size(pt,1)
      call create_(skip,n_pt)
      call create_(x,n_pt)
      call create_(y,n_pt)
      call create_(z,n_pt)
      call create_(r2,n_pt)
      r2_max = r2_max_(self,cutoff)
      k = 0
      do n = 1,n_pt
         xx = pt(n,1)-self%position(1)
         yy = pt(n,2)-self%position(2)
         zz = pt(n,3)-self%position(3)
         rr = xx*xx+yy*yy+zz*zz
         skip(n) = skip2(n) OR rr>r2_max
         if (skip(n)) cycle
         k = k+1
         x(k) = xx
         y(k) = yy
         z(k) = zz
         r2(k) = rr
      end do
      if (k==0) then
         call destroy_(skip)
         call destroy_(x)
         call destroy_(y)
         call destroy_(z)
         call destroy_(r2)
      else
         call shrink_(x,k)
         call shrink_(y,k)
         call shrink_(z,k)
         call shrink_(r2,k)  ! don't shrink skip
      end if
   end subroutine


!  ============================
!  Make basis shell information
!  ============================

   PURE subroutine make_shell_info(self)
   ! Define a vector of atom numbers corresponding to the molecule
   ! basis set shell numbers; also define a vector of atom shell numbers
   ! corresponding to the molecule basis set shell number
      type(ATOM_TYPE), INOUT :: self
   ENSURE(allocated(self%basis),"ATOM:make_shell_info ... no basis set")
      call destroy_(self%first_basis_fn_for_shell)
      call destroy_(self%last_basis_fn_for_shell)
      call destroy_(self%angular_moment_for_shell)
      call set_shell_limits_(self,self%first_basis_fn_for_shell,self%last_basis_fn_for_shell,self%angular_moment_for_shell)
      call make_precomputed_shellpairs_(self)

   ! GAUSSIAN_DATA:set_indices(maxval(.basis.shell.l)) ! NOT PURE
   end subroutine

   PURE subroutine set_shell_limits(self,first,last,momentum)
   ! Set the indices of first and last basis functions in a particular shell
   ! "s", first(s) and last(s), respectively.
      type(ATOM_TYPE), IN :: self
      VEC(INT,:), allocatable, OUT :: first,last,momentum
      INT :: n_shell,f,l,s
      n_shell = no_of_shells_(self%basis)
      call create_(first,n_shell)
      call create_(last,n_shell)
      call create_(momentum,n_shell)
      l = 0
      do s = 1,n_shell
         f = l+1
         l = f+self%basis%shell(s)%n_bf-1
         first(s) = f
         last(s) = l
         momentum(s) = self%basis%shell(s)%l
      end do
   end subroutine

   PURE subroutine make_precomputed_shellpairs(self)
   ! Make a SHELLPAIR vector "shellpair" which includes precomputed data for the
   ! basis set.
   ! NOTE for later: n_unique_shells should be a basisvec routine.
   ! NOTE for later: basis_shell1pair should be a MAT{REAL} type
      type(ATOM_TYPE), INOUT :: self
      INT :: n,a,b
   ENSURE(allocated(self%basis),"ATOM:make_precomputed_shellpairs ... no basis set")
      n = no_of_shells_(self%basis)
      call destroy_(self%basis_shell1pair)
      call create_(self%basis_shell1pair,n,n)
      do a = 1,n
         do b = 1,n
            call set_a_(self%basis_shell1pair(a,b),self%basis%shell(a))
            call set_b_(self%basis_shell1pair(a,b),self%basis%shell(b))
            call make_precalculated_data_(self%basis_shell1pair(a,b))
         end do
      end do
   end subroutine

   PURE subroutine set_shell2_from(self,q,sh2,fa,la,fb,lb)
   ! Get the SHELL2 object "sh2" correponding to the pair index "q"
   ! Also return the basis function start indices "fa", "la", etc ...
      type(ATOM_TYPE), IN :: self
      INT, IN :: q
      type(SHELL2_TYPE), OUT :: sh2
      INT, OUT :: fa,la
      INT, OUT :: fb,lb
      INT :: a,b
   ENSURE(allocated(self%basis_shell1pair),"ATOM:set_shell2_from ... no precomputed basis shellpair data")
   ENSURE(allocated(self%first_basis_fn_for_shell),"ATOM:set_shell2_from ... no first_basis_fn data")
   ENSURE(allocated(self%last_basis_fn_for_shell),"ATOM:set_shell2_from ... no last_basis_fn data")
      a = (1+int(sqrt(8.0d0*q-7.0d0)))/2
      b = q-a*(a-1)/2
      fa = self%first_basis_fn_for_shell(a)
      fb = self%first_basis_fn_for_shell(b)
      la = self%last_basis_fn_for_shell(a)
      lb = self%last_basis_fn_for_shell(b)
      call set_and_precompute_from_(sh2,self%basis_shell1pair(a,b),self%position,self%position,same_center=TRUE,skip=FALSE)
   end subroutine

   PURE subroutine set_shell2_0_from(self,q,sh2,fa,la,fb,lb)
   ! Get the SHELL2 object "sh2" correponding to the pair index "q"
   ! Also return the basis function start indices "fa", "la", etc ...
   ! HOWEVER, place both functions at the origin not at .position.
      type(ATOM_TYPE), IN :: self
      INT, IN :: q
      type(SHELL2_TYPE), OUT :: sh2
      INT, OUT :: fa,la
      INT, OUT :: fb,lb
      INT :: a,b
      VEC(REAL,3) :: zv
   ENSURE(allocated(self%basis_shell1pair),"ATOM:set_shell2_0_from ... no precomputed basis shellpair data")
   ENSURE(allocated(self%first_basis_fn_for_shell),"ATOM:set_shell2_0_from ... no first_basis_fn data")
   ENSURE(allocated(self%last_basis_fn_for_shell),"ATOM:set_shell2_0_from ... no last_basis_fn data")
      a = (1+int(sqrt(8.0d0*q-7.0d0)))/2
      b = q-a*(a-1)/2
      fa = self%first_basis_fn_for_shell(a)
      fb = self%first_basis_fn_for_shell(b)
      la = self%last_basis_fn_for_shell(a)
      lb = self%last_basis_fn_for_shell(b)
      zv = ZERO
      call set_and_precompute_from_(sh2,self%basis_shell1pair(a,b),zv,zv,same_center=TRUE,skip=FALSE)
   end subroutine


!  ==========================
!  Structure factor integrals
!  ==========================

   PURE subroutine make_FT(self,res,k_pts)
   ! Fourier transform of the density described by ".density_mx"
   ! evaluated at a reciprocal space points [k_pts(i,:), i = 1,dim ]
      type(ATOM_TYPE), IN :: self
      VEC(CPX,:), OUT :: res
      MAT(REAL,:,:), IN :: k_pts
      if (self%use_IAM_ITC_FFs) then; call make_FT_IAM_ITC_FF_(self,res,k_pts)
      else; call make_FT_density_mx_(self,res,k_pts)
      end if
   end subroutine

   PURE subroutine make_FT_IAM_ITC_FF(self,res,k_pts)
   ! Analytical representation of the spherical IAM form factor
   ! evaluated at a reciprocal space points [k_pts(i,:), i = 1,dim ]
   ! From the International Tables C.
      type(ATOM_TYPE), IN :: self
      VEC(CPX,:), OUT :: res
      MAT(REAL,:,:), IN :: k_pts
      VEC(REAL,:), allocatable :: k_z
      INT :: k_max
      CPX :: II
      VEC(CPX,:), allocatable :: phv
   ENSURE(self%use_IAM_ITC_FFs,"ATOM:make_FT_IAM_ITC_FF ... use_IAM_ITC_FFs is FALSE!")
      k_max = size(k_pts,1)
      II = IMAGIFY(ONE)
      if (self%atomic_number==1) then

         ! H atom uses Stewart-Davidson-Simpson (SDS) AIM
         call create_(k_z,k_max)
         call get_row_norms_(k_pts,k_z)
         res = H_SDS_form_factor(k_z)*exp(II*(self%position(1)*k_pts(:,1)+self%position(2)*k_pts(:,2)+self%position(3)*k_pts(:,3)))
         call destroy_(k_z)
      else

         ! Other atoms use fitted *neutral* HF form factors
         call create_(phv,k_max)
         call create_(k_z,k_max)
         call get_row_norms_(k_pts,k_z)
         res = HF_n0_form_factor_(self,k_z)
         phv = exp(II*(self%position(1)*k_pts(:,1)+self%position(2)*k_pts(:,2)+self%position(3)*k_pts(:,3)))
         res = res*phv
         call destroy_(k_z)
         call destroy_(phv)
      end if
   end subroutine

   PURE subroutine make_FT_density_mx(self,res,k_pts)
   ! Fourier transform of the density described by ".density_mx"
   ! evaluated at a reciprocal space points [k_pts(i,:), i = 1,dim ]
      type(ATOM_TYPE), IN :: self
      VEC(CPX,:), OUT :: res
      MAT(REAL,:,:), IN :: k_pts
      INT :: k_max,k
      INT :: n_shell_pairs
      INT :: q,fa,fb,la,lb
      MAT3(CPX,:,:,:), allocatable :: FT
      MAT(REAL,:,:), allocatable :: D
      type(SHELL2_TYPE) :: sh
   ENSURE(allocated(self%density_mx),"ATOM:make_FT_density_mx ... no .density_mx")
   ENSURE(allocated(self%density_mx%r),"ATOM:make_FT_density_mx ... only works for restricted .density_mx")
   ENSURE(allocated(self%basis_shell1pair),"ATOM:make_FT_density_mx ... no basis_shell1pair info")
      n_shell_pairs = no_of_shells_(self%basis)
      n_shell_pairs = triangle_number_(n_shell_pairs)
      k_max = size(k_pts,1)

      ! Use whatever atomic .density_mx is there
      res = ZERO
      do q = 1,n_shell_pairs

         ! Get shell
         call set_shell2_from_(self,q,sh,fa,la,fb,lb)

         ! Make the FT 
         call create_(FT,k_max,sh%a%n_comp,sh%b%n_comp)
         call make_ft_c_(sh,FT,k_pts)

         ! Trace with density matrix
         ! Count off-diagonals twice
         D = self%density_mx%r(fa:la,fb:lb)
         if (fa/=fb) then
            do k = 1,k_max
               res(k) = res(k)+sum(FT(k,:,:)*D)*TWO
            end do
         else
            do k = 1,k_max
               res(k) = res(k)+sum(FT(k,:,:)*D)
            end do
         end if

         ! Clean
         call destroy_(FT)
         call destroy_ptr_part_(sh)
      end do
   end subroutine

   PURE subroutine make_FT_along_z(self,res,k_z)
   ! Fourier transform of the density described by ".density_mx"
   ! evaluated at a reciprocal space points [0,0,k_z(i), i = 1,dim].
   ! NOTE: evaluated at the ORIGIN!
      type(ATOM_TYPE), IN :: self
      VEC(CPX,:), OUT :: res
      VEC(REAL,:), IN :: k_z
      INT :: n_shell_pairs,q,fa,fb,la,lb,k_max,k
      VEC(REAL,:), allocatable :: k_x,k_y
   ! partition :: MAT{REAL}@
      MAT3(CPX,:,:,:), allocatable :: FT
      MAT(REAL,:,:), allocatable :: D
      type(SHELL2_TYPE) :: sh
   ENSURE(allocated(self%density_mx),"ATOM:make_FT_along_z ... no .density_mx")
   ENSURE(allocated(self%density_mx%r),"ATOM:make_FT_along_z ... only works for restricted .density_mx")
   ENSURE(allocated(self%basis_shell1pair),"ATOM:make_FT_along_z ... no precomputed basis shellpair data")
      k_max = size(k_z,1)
      if (self%atomic_number==1 AND self%use_IAM_ITC_FFs) then

         ! H atom uses Stewart-Davidson-Simpson (SDS) AIM
         res = COMPLEXIFY(H_SDS_form_factor(k_z),ZERO)
      else if (self%use_IAM_ITC_FFs) then

         ! Uses neutral atom form factors
         res = COMPLEXIFY(HF_n0_form_factor_(self,k_z),ZERO)
      else

         ! Use whatever atomic .density_mx is there
         ! It should be spherical though ...
         n_shell_pairs = no_of_shells_(self%basis)
         n_shell_pairs = triangle_number_(n_shell_pairs)

         ! Other components
         call create_(k_x,k_max); k_x = 0
         call create_(k_y,k_max); k_y = 0
         res = ZERO
         do q = 1,n_shell_pairs

            ! Get shell pair *AT ORIGIN*
            call set_shell2_0_from_(self,q,sh,fa,la,fb,lb)

            ! Make the FT 
            call create_(FT,k_max,sh%a%n_comp,sh%b%n_comp)
            call make_ft_c_(sh,FT,k_x,k_y,k_z)

         ! partition.create(sh.a.n_comp,sh.b.n_comp)
         ! partition = ONE
         ! sh.make_FT_parted_c(FT,k_x,k_y,k_z,partition)

            ! Trace with density matrix
            ! Count off-diagonals twice
            D = self%density_mx%r(fa:la,fb:lb)
            if (fa/=fb) then
               do k = 1,k_max
                  res(k) = res(k)+sum(FT(k,:,:)*D)*TWO
               end do
            else
               do k = 1,k_max
                  res(k) = res(k)+sum(FT(k,:,:)*D)
               end do
            end if

            ! Clean
         ! partition.destroy
            call destroy_(FT)
            call destroy_ptr_part_(sh)
         end do

         ! Clean
         call destroy_(k_y)
         call destroy_(k_x)
      end if
   end subroutine

   subroutine FT_along_z_r(res,k_z)
   ! Real part of fourier transform of the density described by
   ! ".density_mx" evaluated at a reciprocal space points
   ! [0,0,k_z(i), i = 1,dim]
      VEC(REAL,:), OUT :: res
      VEC(REAL,:), IN :: k_z
      VEC(CPX,:), allocatable :: tmp
      call create_(tmp,size(res))
      call make_FT_along_z_(saved_self,tmp,k_z)
      res = RE(tmp)
      call destroy_(tmp)
   end subroutine

   subroutine FT_along_z_i(res,k_z)
   ! Imaginary part of fourier transform of the density described by
   ! ".density_mx" evaluated at a reciprocal space points
   ! [0,0,k_z(i), i = 1,dim]
      VEC(REAL,:), OUT :: res
      VEC(REAL,:), IN :: k_z
      VEC(CPX,:), allocatable :: tmp
      call create_(tmp,size(res))
      call make_FT_along_z_(saved_self,tmp,k_z)
      res = IM(tmp)
      call destroy_(tmp)
   end subroutine

   subroutine put_FT_along_z_r(self,length,spacing)
   ! Put the real part of the spherical atomic form factors (along z
   ! direction) NOTE: X axis is converted to Angstrom^-1
      type(ATOM_TYPE), IN :: self
      REAL, IN :: length
      REAL, IN :: spacing
      type(INTERPOLATOR_TYPE), allocatable :: interpolator
   ! points :: VEC{REAL}@

      ! Used below to make interpolator
      call set_saved_self_(self)  ! NOT PURE

      ! Set the interpolation table
      call create_(interpolator)
      call set_data_(interpolator,length,spacing,FT_along_z_r)

      ! Set H SDS points from the IT C table
   ! points.create(23)

    !    0.7300  ]
   ! points = FOUR*PI * ANGSTROM_PER_BOHR * points ! in Bohr^-1
   ! interpolator.create
   ! interpolator.set_data_points(points)
   ! interpolator.set_data(length,spacing,ATOM::FT_along_z_r)

      ! Neutral H atom form factors points
   ! points.create(46)

    !    1.00    ]
   ! points = FOUR*PI * ANGSTROM_PER_BOHR * points ! in Bohr^-1
   ! interpolator.create
   ! interpolator.set_data_points(points)
   ! interpolator.set_data(length,spacing,ATOM::FT_along_z_r)

      ! Put
      call put_(interpolator,fac=BOHR_PER_ANGSTROM/(FOUR*PI))

      ! Clean
      call destroy_(interpolator)
   end subroutine

   subroutine put_FT_along_z_i(self,length,spacing)
   ! Put the imaginary part of the spherical atomic form factors
   ! (along z direction) NOTE: X axis is converted to Angstrom^-1
      type(ATOM_TYPE), IN :: self
      REAL, IN :: length
      REAL, IN :: spacing
      type(INTERPOLATOR_TYPE), allocatable :: interpolator

      ! Set the interpolation table
      call set_saved_self_(self)  ! Used below
      call create_(interpolator)
      call set_data_(interpolator,length,spacing,FT_along_z_i)

      ! Clean
      call put_(interpolator,fac=BOHR_PER_ANGSTROM/(FOUR*PI))

      ! Clean
      call destroy_(interpolator)
   end subroutine


!  ====
!  Dump
!  ====

   subroutine do_dump(self)
   ! Dump object data as text
      type(ATOM_TYPE), IN :: self
      call dump_(stdout,"label",self%label)
      call dump_(stdout,"tag",self%tag)
      call dump_(stdout,"atomic_number",self%atomic_number)
      call dump_(stdout,"nuclear_charge",self%nuclear_charge)
      call dump_(stdout,"oxidation_state",self%oxidation_state)
      call dump_(stdout,"position",self%position)
      call dump_(stdout,"position_error",self%position_error)
      call dump_(stdout,"group",self%group)
      call dump_(stdout,"site_occupancy",self%site_occupancy)
      call dump_(stdout,"site_disorder_group",self%site_disorder_group)
      call dump_(stdout,"U_iso",self%U_iso)
      call dmpa_(stdout,"pADP_vector",self%pADP_vector)
      call dmpa_(stdout,"pADP_errors",self%pADP_errors)
      call dump_(stdout,"pos_axis_system",self%pos_axis_system)
      call dump_(stdout,"ADP_axis_system",self%ADP_axis_system)
      call dump_(stdout,"ADPn_axis_system",self%ADPn_axis_system)
      call dump_(stdout,"charge",self%charge)
      call dump_(stdout,"dipole",self%dipole)
      call dump_(stdout,"quadrupole",self%quadrupole)
      call dump_(stdout,"spin",self%spin)
      call dump_(stdout,"spin_dipole",self%spin_dipole)
      call dump_(stdout,"spin_quadrupole",self%spin_quadrupole)
      call dump_(stdout,"charge_polarisability",self%charge_polarisability)
      call dump_(stdout,"dipole_polarisability",self%dipole_polarisability)
      call dump_(stdout,"basis_label",self%basis_label)
      call dump_(stdout,"basis_kind",self%basis_kind)
      call dmpa_(self%basis,"basis")
      call dump_(stdout,"slaterbasis_label",self%slaterbasis_label)
      call dmpa_(self%slaterbasis,"slaterbasis")
      call dump_(stdout,"coppensbasis_label:STR",self%coppensbasis_label)
      call dmpa_(self%coppensbasis,"coppensbasis")
      call dump_(stdout,"kind",self%kind)
      call dump_(stdout,"is_unique_kind",self%is_unique_kind)
      call dump_(stdout,"energy",self%energy)
      call dump_(stdout,"AOs",self%AOs)
      call dump_(stdout,"density_mx",self%density_mx)
      call dump_(stdout,"NOs",self%NOs)
      call dump_(stdout,"NO_occ_nos",self%NO_occ_nos)
      call dump_(stdout,"atom_data_made",self%atom_data_made)
      call dump_(stdout,"use_interpolator",self%use_interpolator)
      call dump_(self%interpolator,"interpolator")
      call dmpa_(stdout,"first_basis_fn_for_shell",self%first_basis_fn_for_shell)
      call dmpa_(stdout,"last_basis_fn_for_shell",self%last_basis_fn_for_shell)
      call dmpa_(self%basis_shell1pair,"basis_shell1pair",lower_triangle=TRUE)
      call dump_(stdout,"invariom_label",self%invariom_label)
      call dump_(stdout,"mm_forcefield_name",self%mm_forcefield_name)
      call dump_(stdout,"mm_atom_type",self%mm_atom_type)
      call dump_(stdout,"mm_chargeL",self%mm_charge)
      call dump_(stdout,"restraining_position",self%restraining_position)
      call dump_(stdout,"restraining_force_constant",self%restraining_force_constant)
   end subroutine

   subroutine dump(self,object_name,all)
   ! Dump object data as text
      type(ATOM_TYPE), IN :: self
      STR(len=*), IN :: object_name
      BIN, optional, IN :: all
      BIN :: is_all

      ! The following code is inherited from OBJECT
      is_all = FALSE
      if (present(all)) is_all = all
      if (is_all) then; call text_(stdout,trim(object_name)//":ATOM@ = { ")
      else; call text_(stdout,trim(object_name)//":ATOM = { ")
      end if
      call increment_margin_width_(stdout,1)
      call do_dump_(self)
      call increment_margin_width_(stdout,-1)
      call text_(stdout,"}")
   end subroutine

   subroutine dmpa(self,object_name)
   ! Dump allocatable object data as text
      type(ATOM_TYPE), allocatable, IN :: self
      STR(len=*), IN :: object_name

      ! The following code is inherited from OBJECT
      if (NOT allocated(self)) then
         call text_(stdout,trim(object_name)//":ATOM@ = null")
      else
         call dump_(self,trim(object_name),all=TRUE)
      end if
   end subroutine


!  ==============
!  Output methods
!  ==============

   subroutine put(self)
   ! Put out the atom information to file "stdout"
      type(ATOM_TYPE), IN :: self
      call put_short_(self)

   ! if (.residue_sequence_number/=0) .put_mm_info
      if (allocated(self%basis)) call put_(self%basis)
      if (allocated(self%slaterbasis)) call put_(self%slaterbasis)
      if (allocated(self%coppensbasis)) call put_(self%coppensbasis)
      call put_ANOs_(self)
   end subroutine

   subroutine put_short(self)
   ! Put out the atom information to file "stdout"
      type(ATOM_TYPE), IN :: self
      call flush_(stdout)
      call show_(stdout,"Label                  =",trim(self%label))
      call show_(stdout,"Unique tag             =",trim(self%tag))
      call show_(stdout,"Atomic No.             =",self%atomic_number)
      call show_(stdout,"Chemical symbol        =",trim(chemical_symbol_(self)))
      call show_(stdout,"Atom position          =",self%position(1),self%position(2),self%position(3))
      call show_(stdout,"Site disorder group    =",self%site_disorder_group)
      call show_(stdout,"Site occupancy         =",self%site_occupancy)
   end subroutine

   subroutine put_ANOs(self)
   ! Put out the ANO information to file "stdout"
      type(ATOM_TYPE), IN :: self
      call flush_(stdout)
      if (allocated(self%AOs)) then
         call flush_(stdout)
         call text_(stdout,"Atomic orbitals:")
         call flush_(stdout)
         call put_(stdout,self%AOs)
      end if
      if (allocated(self%density_mx)) then
         call flush_(stdout)
         call text_(stdout,"Density matrix:")
         call flush_(stdout)
         call put_(stdout,self%density_mx)
      end if
      if (allocated(self%NOs)) then
         call flush_(stdout)
         call text_(stdout,"Natural occupations and orbitals:")
         call flush_(stdout)
         call put_(stdout,self%NO_occ_nos)
         call flush_(stdout)
         call put_(stdout,self%NOs)
      end if
   end subroutine


!   put_mm_info
!   ! Put out the MM/protien part of the atom information to file "stdout"
!      self :: IN
!
!      stdout.flush
!      stdout.show("Residue atom code       =",trim(.residue_atom_code))
!      stdout.show("Residue code            =",trim(.residue_code))
!      stdout.show("Residue sequence number =",.residue_sequence_number)
!      stdout.show("MM forcefield name      =",.mm_forcefield_name)
!      stdout.show("MM atom type            =",.mm_atom_type)
!      stdout.show("MM charge               =",.mm_charge)
!      stdout.show("Restraining position    =",.restraining_position)
!      stdout.show("Restraining force       =",.restraining_force_constant)
!
!   end

   subroutine put_NOs(self)
   ! Put out the current molecular orbitals to file "out"
      type(ATOM_TYPE), IN :: self
   ENSURE(allocated(self%NOs),"ATOM:put_NOs ... no natural orbitals")
   ENSURE(allocated(self%NO_occ_nos),"ATOM:put_NOs ... no natural orbital occupations")
      call flush_(stdout)
      call text_(stdout,"NO occupation numbers:")
      call put_(stdout,self%NO_occ_nos)
      call flush_(stdout)
      call text_(stdout,"Natural orbitals:")
      call put_(stdout,self%NOs)
   end subroutine

   subroutine put_interpolator(self)
   ! Put out the atom information to file "stdout"
      type(ATOM_TYPE), IN :: self
      select case (self%basis_kind)

      case ("slater")
         ENSURE(allocated(self%slaterbasis),"ATOM:put_interpolator ... no slaterbasis")
         call flush_(stdout)
         call text_(stdout,"Atom slaterbasis info:")
         call put_(self%slaterbasis%interpolator)

      case ("coppens")
         ENSURE(allocated(self%coppensbasis),"ATOM:put_interpolator ... no coppensbasis")
         call flush_(stdout)
         call text_(stdout,"Atom coppensbasis info:")
         call put_(self%coppensbasis%interpolator)

      case default
         DIE("ATOM:put_interpolator ... no interpolator for basis "//trim(self%basis_kind))
      end select
   end subroutine

end module
